// 理财（com.aibox.finance）—— FinancePluginKit 的 React 复刻。
//
// 根职责：装配 store / ledger / quotes / alerts → 接宿主外壳（tabs / toolbar / ai / notifications）
// → 注册 23 个 `finance_*` AI 工具 → 路由子页与弹层 → 跑刷新循环。
// 宿主能力缺席时全部走自绘降级件（见 components/Shell.jsx），不留点了没反应的按钮。

import React from 'react'
import { THEME_CSS } from './components/theme.js'
import { NavBar, SearchField, StorageBanner, TabBar, ToolbarButton } from './components/Shell.jsx'
import WatchlistPage from './components/WatchlistPage.jsx'
import IndustryPage from './components/IndustryPage.jsx'
import PortfolioPage from './components/PortfolioPage.jsx'
import SettingsPage, { GroupsSheet } from './components/SettingsPage.jsx'
import DetailPage from './components/DetailPage.jsx'
import SearchPage from './components/SearchPage.jsx'
import TradePanel from './components/TradePanel.jsx'
import AlertPanel from './components/AlertPanel.jsx'
import StrategyPage from './components/StrategyPage.jsx'
import AIPanel, { buildContext } from './components/AIPanel.jsx'
import { AccountsSheet, CashFlowSheet, HistorySheet } from './components/AccountsPage.jsx'
import { FinanceStore } from './lib/store.js'
import { Ledger } from './lib/ledger.js'
import { QuoteService } from './lib/quotes.js'
import { AlertStore, isPercentCondition, isUpwardCondition } from './lib/alerts.js'
import { registerTools } from './lib/tools.js'
import { useSubpageStack } from './lib/subpages.js'
import { INDEX_ROWS, decimalsFor, resolveSymbol } from './lib/symbol.js'
import { formatPercent, formatPrice } from './lib/format.js'
import {
  aiAvailability, capabilities, onEvent, onNamespaceEvent, openChat, scheduleNotification,
} from './lib/host.js'
import { currentLocale, makeT, onLocaleChanged } from './i18n/index.js'

const TABS = [
  { id: 'markets', titleKey: 'finance.tab.markets', icon: 'chart.line.uptrend.xyaxis' },
  { id: 'industry', titleKey: 'finance.tab.industry', icon: 'square.grid.2x2' },
  { id: 'portfolio', titleKey: 'finance.tab.portfolio', icon: 'wallet.pass' },
  { id: 'settings', titleKey: 'finance.tab.settings', icon: 'gearshape' },
]

function useForceRender() {
  const [, setTick] = React.useState(0)
  return React.useCallback(() => setTick((n) => n + 1), [])
}

function useThemeSetup() {
  React.useEffect(() => {
    if (document.getElementById('__finance_css__')) return
    const style = document.createElement('style')
    style.id = '__finance_css__'
    style.textContent = THEME_CSS
    document.head.appendChild(style)
  }, [])
  React.useEffect(() => {
    const query = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null
    const apply = () => {
      document.documentElement.setAttribute('data-prefers-color-scheme', query && query.matches ? 'dark' : 'light')
    }
    apply()
    if (query && query.addEventListener) {
      query.addEventListener('change', apply)
      return () => query.removeEventListener('change', apply)
    }
    return undefined
  }, [])
}

export default function App() {
  useThemeSetup()
  const rerender = useForceRender()

  const [locale, setLocale] = React.useState(currentLocale)
  const t = React.useMemo(() => makeT(locale), [locale])

  const refs = React.useRef(null)
  if (refs.current === null) {
    const store = new FinanceStore()
    refs.current = { store, ledger: new Ledger(), quotes: new QuoteService(), alerts: new AlertStore(store) }
  }
  const { store, ledger, quotes, alerts } = refs.current

  const [ready, setReady] = React.useState(false)
  const [tab, setTab] = React.useState('markets')
  // 子页栈 = 宿主原生页栈的镜像（见 lib/subpages.js）：进详情走 `aibox.navigation.push`，
  // 返回一律经 popstate 回来，于是最左缘左滑是**系统自己的** interactive pop。
  const subpages = useSubpageStack({ pathFor: routePath, titleFor: (row) => (row && row.title) || '' })
  const [sheet, setSheet] = React.useState(null)          // { name, ... }
  const [aiSession, setAISession] = React.useState(null)
  const [refreshing, setRefreshing] = React.useState(false)
  const [accountID, setAccountID] = React.useState(null)
  const [shell, setShell] = React.useState({ tabsRendered: false, toolbarRendered: false })
  const [hasAI, setHasAI] = React.useState(false)

  React.useEffect(() => {
    const offs = [store.subscribe(rerender), ledger.subscribe(rerender), quotes.subscribe(rerender)]
    return () => offs.forEach((off) => off())
  }, [store, ledger, quotes, rerender])

  React.useEffect(() => onLocaleChanged(setLocale), [])

  // —— 启动：hydrate 磁盘快照秒显 → 再拉网络 ——
  React.useEffect(() => {
    let cancelled = false
    const boot = async () => {
      await Promise.all([store.load(), ledger.load()])
      if (cancelled) return
      const saved = await store.loadQuotes()
      if (cancelled) return
      if (saved) quotes.hydrate(saved.rows, saved.lastUpdated)
      quotes.refreshInterval = store.settings.refreshInterval
      quotes.source = store.settings.quoteSource
      setAccountID((current) => current || (ledger.primaryAccount() || {}).id || null)
      setReady(true)
    }
    boot()
    return () => { cancelled = true }
  }, [store, ledger, quotes])

  // 设置变化要立刻改写行情服务的 TTL 与故障切换策略。
  React.useEffect(() => {
    quotes.refreshInterval = store.settings.refreshInterval
    quotes.source = store.settings.quoteSource
  }, [quotes, store.settings.refreshInterval, store.settings.quoteSource])

  React.useEffect(() => {
    let cancelled = false
    const probe = async () => {
      const info = capabilities.ai ? await aiAvailability() : { available: false }
      if (!cancelled) setHasAI(!!info.available && capabilities.chat)
    }
    probe()
    return () => { cancelled = true }
  }, [])

  // —— 刷新（§2.5）——
  //
  // 每轮的标的 = **7 个指数 + 全部自选**（不只当前可见分组）+ 持仓。
  // 刷完做三件事：① 检查到价提醒并推本地通知 ② 写磁盘快照（节流 20s）③ 更新 lastUpdated。
  const busy = React.useRef(false)
  const refresh = React.useCallback(async (force) => {
    if (busy.current) return                                  // 并发保护：正在刷新时直接返回
    busy.current = true
    setRefreshing(true)
    try {
      const symbols = [
        ...INDEX_ROWS.map((row) => row.canonical),
        ...store.items.map((row) => row.instrumentSymbol),
        ...ledger.positions.filter((row) => row.quantity > 0).map((row) => row.instrumentSymbol),
      ]
      const result = await quotes.refresh(symbols, { force })
      await quotes.exchangeRates({ force })

      const fired = await alerts.check(result.quotes, Date.now())
      for (const hit of fired) {
        if (!store.settings.notifyAlerts) break
        const symbol = resolveSymbol(hit.alert.instrumentSymbol)
        const decimals = symbol ? decimalsFor(symbol.market) : 2
        const current = isPercentCondition(hit.alert.conditionRaw)
          ? formatPercent(hit.quote.changePct)
          : formatPrice(hit.quote.price, decimals)
        const target = isPercentCondition(hit.alert.conditionRaw)
          ? formatPercent(hit.alert.targetPrice)
          : formatPrice(hit.alert.targetPrice, decimals)
        await scheduleNotification({
          title: `${hit.alert.name} · ${t('finance.notify.title')}`,
          body: t(isUpwardCondition(hit.alert.conditionRaw) ? 'finance.notify.above' : 'finance.notify.below', current, target),
          afterMinutes: 0,
        })
      }
      await store.persistQuotes(quotes.snapshot(), quotes.lastUpdated, { force })
    } finally {
      busy.current = false
      setRefreshing(false)
    }
  }, [store, ledger, quotes, alerts, t])

  // 进页刷一次；自动刷新开着则按间隔循环。任务 id = 自选串 + 开关 + 间隔，任一变化就重启。
  const watchKey = store.items.map((row) => row.instrumentSymbol).join(',')
  React.useEffect(() => {
    if (!ready) return undefined
    refresh(false)
    if (!store.settings.autoRefresh) return undefined
    const timer = window.setInterval(() => refresh(false), Math.max(10, store.settings.refreshInterval) * 1000)
    return () => window.clearInterval(timer)
  }, [ready, watchKey, store.settings.autoRefresh, store.settings.refreshInterval]) // eslint-disable-line react-hooks/exhaustive-deps

  // 退出/后台时强制落盘最新行情（原生的退出按钮就是先 persistNow 再关小应用）。
  React.useEffect(() => onEvent('lifecycle.background', () => {
    store.persistQuotes(quotes.snapshot(), quotes.lastUpdated, { force: true })
  }), [store, quotes])

  // —— 宿主外壳接线 ——
  const openSearchRef = React.useRef(null)
  const openAIRef = React.useRef(null)
  // 外壳接线只跑一次，而 reset 要在每次切 Tab 时清掉子页栈 —— 经 ref 取最新那一个。
  const resetRef = React.useRef(subpages.reset)
  resetRef.current = subpages.reset

  React.useEffect(() => {
    let cancelled = false
    const offs = []
    const wire = async () => {
      const api = window.aibox
      if (api && api.tabs && typeof api.tabs.getState === 'function') {
        try {
          const state = await api.tabs.getState()
          if (!cancelled && state && state.rendered) {
            setShell((current) => ({ ...current, tabsRendered: true }))
            if (state.selected) setTab(state.selected)
          }
        } catch (error) { /* 宿主没这能力：留给自绘 TabBar */ }
        offs.push(onNamespaceEvent('tabs', 'changed', (state) => {
          if (!state) return
          // `rendered` 会**在挂载之后翻转**（形态切换、控制器重建都会重发 changed）。
          // 只在启动那一刻判断一次，自绘 TabBar 就会永远缺席或永远多一条。
          const rendered = state.rendered !== false
          setShell((current) => (current.tabsRendered === rendered
            ? current : { ...current, tabsRendered: rendered }))
          if (state.selected) { setTab(state.selected); resetRef.current() }
        }))
      }
      if (api && api.toolbar && typeof api.toolbar.getState === 'function') {
        try {
          const state = await api.toolbar.getState()
          if (!cancelled && state) setShell((current) => ({ ...current, toolbarRendered: state.rendered !== false }))
        } catch (error) { /* 同上 */ }
        offs.push(onNamespaceEvent('toolbar', 'invoke', (payload) => {
          if (!payload) return
          if (payload.id === 'search' && openSearchRef.current) openSearchRef.current()
          if (payload.id === 'ai' && openAIRef.current) openAIRef.current()
        }))
      }
    }
    wire()
    return () => { cancelled = true; offs.forEach((off) => off && off()) }
  }, [])

  // 没有 AI 就把 ✨ 隐藏——不留死按钮。
  React.useEffect(() => {
    const api = window.aibox
    if (api && api.toolbar && typeof api.toolbar.update === 'function') {
      api.toolbar.update({ items: { ai: { hidden: !hasAI } } }).catch(() => {})
    }
  }, [hasAI])

  // —— 注册 23 个 finance_* 工具 ——
  React.useEffect(() => {
    if (!ready) return
    registerTools({ store, ledger, quotes, alerts })
  }, [ready, store, ledger, quotes, alerts])

  // —— 路由与动作 ——
  const { push: navigate, back } = subpages

  const openDetail = React.useCallback((canonical) => {
    const symbol = resolveSymbol(canonical)
    if (!symbol) return
    navigate({ name: 'detail', canonical, symbol, title: store.instrumentName(canonical) })
  }, [navigate, store])

  const askAI = React.useCallback(async ({ identity, seed }) => {
    const context = buildContext({ t, locale, store, quotes, ledger, settings: store.settings })
    await openChat({ prompt: `${context}\n\n${seed}`, categoryKey: 'finance', autoSend: true, identity })
  }, [t, locale, store, quotes, ledger])

  const valuation = (ready && accountID) ? ledger.valuation(accountID, quotes.quoteMap(), quotes.fx) : null
  const perf = (ready && accountID) ? ledger.performance(accountID) : null

  const ctx = React.useMemo(() => ({
    t,
    locale,
    store,
    ledger,
    quotes,
    alerts,
    settings: store.settings,
    accountID,
    valuation,
    perf,
    hasAI,
    refreshing,
    actions: {
      navigate,
      back,
      refresh,
      openDetail,
      openSearch: () => setSheet({ name: 'search' }),
      openAccounts: () => setSheet({ name: 'accounts' }),
      openCashFlow: () => setSheet({ name: 'cashflow' }),
      openHistory: () => setSheet({ name: 'history' }),
      openGroups: () => setSheet({ name: 'groups' }),
      openTrade: (canonical, symbol, name) => setSheet({ name: 'trade', canonical, symbol, symbolName: name }),
      openAlert: (canonical, symbol, name) => setSheet({ name: 'alert', canonical, symbol, symbolName: name }),
      openStrategy: (canonical, symbol, name) => setSheet({ name: 'strategy', canonical, symbol, symbolName: name }),
      selectAccount: setAccountID,
      toggleWatch: (canonical, name) => (store.isWatched(canonical)
        ? store.removeWatch(canonical)
        : store.addWatch(canonical, { name })),
      removeWatch: (canonical) => store.removeWatch(canonical),
      askAI,
      askAboutSymbol: (canonical, name, quote) => setAISession({
        identity: `finance:${canonical}`,
        symbolName: `${name}（${canonical}）${quote ? ` ${formatPrice(quote.price, 2)} ${formatPercent(quote.changePct)}` : ''}`,
      }),
    },
  }), [t, locale, store, ledger, quotes, alerts, store.version, ledger.version, quotes.lastUpdated,
    accountID, valuation, perf, hasAI, refreshing, navigate, back, refresh, openDetail, askAI]) // eslint-disable-line react-hooks/exhaustive-deps

  openSearchRef.current = ctx.actions.openSearch
  openAIRef.current = () => setAISession({ identity: 'finance:root' })

  const { route } = subpages
  const currentTab = TABS.find((row) => row.id === tab) || TABS[0]
  const title = route ? route.title : t(currentTab.titleKey)

  React.useEffect(() => {
    document.title = title
    const api = window.aibox
    if (api && api.navigation && typeof api.navigation.setTitle === 'function') api.navigation.setTitle(title)
  }, [title])

  const selectTab = (next) => {
    setTab(next)
    subpages.reset()
    const api = window.aibox
    if (api && api.tabs && typeof api.tabs.select === 'function') api.tabs.select(next).catch(() => {})
  }

  const closeSheet = () => setSheet(null)
  const sheetName = sheet ? sheet.name : null

  return (
    <div className="fin-root">
      {/* 宿主画了顶栏就**不再自绘** —— 子页也不自绘：宿主在 `webDepth > 0` 时自己就有返回键，
          两条一起画等于两层导航栏、两个标题。没有宿主顶栏时（fullscreen 形态 / 无宿主）才补上。 */}
      {!shell.toolbarRendered ? (
        <NavBar
          title={title}
          onBack={route ? back : undefined}
          backLabel={t('finance.cancel')}
          trailing={!route ? (
            <>
              {hasAI ? (
                <ToolbarButton icon="sparkles" label={t('finance.ai.title')} onClick={() => openAIRef.current()} />
              ) : null}
              <ToolbarButton icon="magnifyingglass" label={t('finance.search.title')} onClick={ctx.actions.openSearch} />
            </>
          ) : null}
        />
      ) : null}

      {!store.storageHealthy ? <StorageBanner text={t('finance.storage.banner')} /> : null}

      {!ready ? <div className="fin-scroll" /> : route ? (
        route.name === 'detail' ? <DetailPage ctx={ctx} route={route} /> : null
      ) : (
        <>
          {tab === 'markets' ? <WatchlistPage ctx={ctx} /> : null}
          {tab === 'industry' ? <IndustryPage ctx={ctx} /> : null}
          {tab === 'portfolio' ? <PortfolioPage ctx={ctx} /> : null}
          {tab === 'settings' ? <SettingsPage ctx={ctx} /> : null}
        </>
      )}

      {!shell.tabsRendered ? (
        <TabBar
          items={TABS.map((row) => ({ ...row, title: t(row.titleKey) }))}
          selected={tab}
          onSelect={selectTab}
        />
      ) : (
        <div style={{ height: 'env(safe-area-inset-bottom)', flex: '0 0 auto' }} />
      )}

      <SearchPage ctx={ctx} visible={sheetName === 'search'} onClose={closeSheet} />
      <AccountsSheet ctx={ctx} visible={sheetName === 'accounts'} onClose={closeSheet} />
      <CashFlowSheet ctx={ctx} visible={sheetName === 'cashflow'} onClose={closeSheet} />
      <HistorySheet ctx={ctx} visible={sheetName === 'history'} onClose={closeSheet} />
      <GroupsSheet ctx={ctx} visible={sheetName === 'groups'} onClose={closeSheet} />
      <TradePanel
        ctx={ctx}
        visible={sheetName === 'trade'}
        onClose={closeSheet}
        route={sheet && sheet.name === 'trade' ? { ...sheet, name: sheet.symbolName } : null}
      />
      <AlertPanel
        ctx={ctx}
        visible={sheetName === 'alert'}
        onClose={closeSheet}
        route={sheet && sheet.name === 'alert' ? { ...sheet, name: sheet.symbolName } : null}
      />
      <StrategyPage
        ctx={ctx}
        visible={sheetName === 'strategy'}
        onClose={closeSheet}
        route={sheet && sheet.name === 'strategy' ? { ...sheet, name: sheet.symbolName } : null}
      />
      <AIPanel ctx={ctx} session={aiSession} onClose={() => setAISession(null)} />
    </div>
  )
}

/** 子页在 history 里的路径。页面自己不读它，只为宿主诊断与 `navigation.getState().url` 可读。 */
function routePath(route) {
  if (!route) return '#/'
  if (route.name === 'detail') return `#/detail/${encodeURIComponent(route.canonical || '')}`
  return `#/${route.name}`
}

// 账户管理 / 现金流水 / 交易历史 —— 规格 §9.3 + §10.6 + §12「账户」「历史」段。
//
// 导出走 `aibox.share.file`（宿主没有该能力就整块不渲染入口，不留死按钮）。

import React from 'react'
import Icon from './Icon.jsx'
import { Card, Field, Row, Segmented, Sheet, SheetHeader, Spinner } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatMinor, formatPrice, formatQuantity, isoDate } from '../lib/format.js'
import { parseNumberInput, toMinor } from '../lib/money.js'
import { CASH_FLOW_KINDS, isExternalFlow } from '../lib/portfolio.js'
import { accountLabel } from '../i18n/index.js'
import { capabilities, shareFile } from '../lib/host.js'

const CURRENCIES = ['CNY', 'HKD', 'USD']

export function AccountsSheet({ ctx, visible, onClose }) {
  const { t, ledger } = ctx
  const [creating, setCreating] = React.useState(false)
  const [name, setName] = React.useState('')
  const [currency, setCurrency] = React.useState('CNY')
  const [initial, setInitial] = React.useState('1000000')
  const [busy, setBusy] = React.useState(false)

  const create = async () => {
    setBusy(true)
    await ledger.createAccount({
      name: name.trim(),
      currency,
      initialCashMinor: toMinor(parseNumberInput(initial) || 0),
    })
    setBusy(false)
    setCreating(false)
    setName('')
  }

  const archived = ledger.accounts.filter((row) => row.isArchived)
  const active = ledger.accounts.filter((row) => !row.isArchived)

  return (
    <Sheet visible={visible} onClose={onClose}>
      <SheetHeader
        title={t('finance.account.manage')}
        onClose={onClose}
        closeLabel={t('finance.done')}
        trailing={(
          <button
            type="button"
            className="fin-btn fin-press"
            aria-label={t('finance.account.new')}
            onClick={() => setCreating((current) => !current)}
            style={{ color: C.brand }}
          >
            <Icon name="plus" size={17} weight="semibold" />
          </button>
        )}
      />
      <div className="fin-scroll" style={{ padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s4 }}>
        {creating ? (
          <Card title={t('finance.account.new')}>
            <Field label={t('finance.account.name')} value={name} onChange={setName} numeric={false} placeholder={t('finance.account.namePlaceholder')} autoFocus />
            <div style={{ padding: '11px 0', display: 'flex', alignItems: 'center', gap: SPACE.s3, borderBottom: `0.5px solid ${C.line}` }}>
              <span style={{ fontSize: 15, flex: '0 0 auto', minWidth: 76 }}>{t('finance.account.currency')}</span>
              <div style={{ flex: '1 1 auto' }}>
                <Segmented value={currency} onChange={setCurrency} items={CURRENCIES.map((id) => ({ id, label: id }))} />
              </div>
            </div>
            <Field label={t('finance.account.initialCash')} value={initial} onChange={setInitial} suffix={currency} />
            <button
              type="button"
              className="fin-btn fin-press"
              disabled={busy}
              onClick={create}
              style={{
                marginTop: SPACE.s3, width: '100%', textAlign: 'center', padding: '11px 0',
                borderRadius: RADIUS.field, background: C.brand, color: C.onAccent, fontSize: 15, fontWeight: 600,
              }}
            >
              {busy ? <Spinner size={16} color={C.onAccent} /> : t('finance.save')}
            </button>
          </Card>
        ) : null}

        <Card>
          {active.map((row, index) => (
            <AccountRow key={row.id} ctx={ctx} account={row} last={index === active.length - 1} />
          ))}
        </Card>

        {archived.length > 0 ? (
          <Card title={t('finance.account.archived')}>
            {archived.map((row, index) => (
              <Row
                key={row.id}
                title={accountLabel(t, row.name)}
                subtitle={row.currency}
                last={index === archived.length - 1}
                accessory={(
                  <button
                    type="button"
                    className="fin-btn fin-press"
                    onClick={() => ledger.updateAccount(row.id, { isArchived: false })}
                    style={{ color: C.brand, fontSize: 13 }}
                  >
                    {t('finance.account.unarchive')}
                  </button>
                )}
              />
            ))}
          </Card>
        ) : null}
      </div>
    </Sheet>
  )
}

function AccountRow({ ctx, account, last }) {
  const { t, ledger } = ctx
  const [open, setOpen] = React.useState(false)
  const canShare = capabilities.share

  const exportArchive = async () => {
    const archive = ledger.archiveFor(account.id)
    if (!archive) return
    await shareFile({
      filename: `${account.name}-finance-backup.json`,
      content: JSON.stringify(archive, null, 2),
      mimeType: 'application/json',
    })
  }

  return (
    <>
      <Row
        title={accountLabel(t, account.name)}
        subtitle={`${account.currency}${account.isRealCopy ? ` · ${t('finance.account.realCopy')}` : ''}`}
        detail={formatMinor(account.cashMinor, account.currency)}
        onClick={() => setOpen((current) => !current)}
        accessory={<Icon name={open ? 'chevron.down' : 'chevron.right'} size={13} color={C.muted} />}
        last={last && !open}
      />
      {open ? (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: SPACE.s2, padding: `${SPACE.s2}px 0 ${SPACE.s3}px` }}>
          {[
            { id: 'reset', label: t('finance.account.reset'), onClick: () => ledger.resetAccount(account.id) },
            { id: 'archive', label: t('finance.account.archive'), onClick: () => ledger.updateAccount(account.id, { isArchived: true }) },
            { id: 'copy', label: t('finance.account.copy'), onClick: () => ledger.copyAccount(account.id) },
            ...(canShare ? [{ id: 'export', label: t('finance.history.export'), onClick: exportArchive }] : []),
            { id: 'delete', label: t('finance.delete'), danger: true, onClick: () => ledger.deleteAccount(account.id) },
          ].map((button) => (
            <button
              key={button.id}
              type="button"
              className="fin-btn fin-press"
              onClick={button.onClick}
              style={{
                padding: '6px 11px', borderRadius: RADIUS.pill, fontSize: 12,
                color: button.danger ? C.danger : C.brand,
                background: 'color-mix(in srgb, var(--fin-muted) 10%, transparent)',
              }}
            >
              {button.label}
            </button>
          ))}
        </div>
      ) : null}
    </>
  )
}

/** 现金流水（§10.6）：入金/出金改本金但不计入盈亏；分红/利息/税费计入。 */
export function CashFlowSheet({ ctx, visible, onClose }) {
  const { t, ledger, accountID } = ctx
  const [kind, setKind] = React.useState('deposit')
  const [amount, setAmount] = React.useState('')
  const [note, setNote] = React.useState('')
  const [error, setError] = React.useState(null)

  const account = ledger.accountByID(accountID)
  const value = parseNumberInput(amount)
  const canSubmit = account && Number.isFinite(value) && value > 0

  const submit = async () => {
    if (!canSubmit) return
    const result = await ledger.addCashFlow({
      accountID: account.id, kind, amountMinor: toMinor(value), note, source: 'manual',
    })
    if (result.ok) { setAmount(''); setNote(''); setError(null) } else setError(result.error)
  }

  const flows = account ? ledger.cashFlowsOf(account.id, 10) : []

  return (
    <Sheet visible={visible} onClose={onClose}>
      <SheetHeader title={t('finance.cashflow.title')} onClose={onClose} closeLabel={t('finance.done')} />
      <div className="fin-scroll" style={{ padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s4 }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: SPACE.s2 }}>
          {CASH_FLOW_KINDS.map((id) => (
            <button
              key={id}
              type="button"
              className="fin-btn fin-press"
              onClick={() => setKind(id)}
              style={{
                padding: '6px 11px', borderRadius: RADIUS.pill, fontSize: 12,
                color: kind === id ? C.brand : C.muted,
                background: kind === id ? 'color-mix(in srgb, var(--fin-brand) 12%, transparent)' : C.surface,
              }}
            >
              {t(`finance.cashflow.${id}`)}
            </button>
          ))}
        </div>
        <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: `0 ${SPACE.s3}px` }}>
          <Field label={t('finance.cashflow.amount')} value={amount} onChange={setAmount} placeholder="0" suffix={account ? account.currency : ''} />
          <Field label={t('finance.cashflow.note')} value={note} onChange={setNote} numeric={false} placeholder="" />
        </div>
        <span style={{ fontSize: 12, color: C.muted, lineHeight: 1.45 }}>
          {t(isExternalFlow(kind) ? 'finance.cashflow.externalFoot' : 'finance.cashflow.internalFoot')}
        </span>
        {error ? <span style={{ fontSize: 13, color: C.danger }}>{t(`finance.trade.error.${error}`)}</span> : null}
        <button
          type="button"
          className="fin-btn fin-press"
          disabled={!canSubmit}
          onClick={submit}
          style={{
            textAlign: 'center', padding: '12px 0', borderRadius: RADIUS.field, fontSize: 16, fontWeight: 600,
            color: C.onAccent, background: C.brand, opacity: canSubmit ? 1 : 0.4,
          }}
        >
          {t('finance.save')}
        </button>

        {flows.length > 0 ? (
          <Card title={t('finance.cashflow.history')}>
            {flows.map((flow, index) => (
              <Row
                key={flow.id}
                title={t(`finance.cashflow.${flow.kindRaw}`)}
                subtitle={`${isoDate(flow.occurredAt)}${flow.note ? ` · ${flow.note}` : ''}`}
                detail={formatMinor(flow.amountMinor, flow.currency, { signed: true })}
                detailColor={flow.amountMinor < 0 ? C.danger : C.ink}
                last={index === flows.length - 1}
              />
            ))}
          </Card>
        ) : null}
      </div>
    </Sheet>
  )
}

/** 交易历史（全量流水）。 */
