// AI 面板 —— 规格 §13.1 / §13.2 / §13.3。
//
// 容器没有「停靠式会话」，所以走原生自己就有的**降级路径**：把上下文 + 种子 prompt
// 交给宿主聊天页开一个新会话（`aibox.chat.open`）。宿主连 AI 都没有时，
// ✨ 入口与本面板**整块不渲染**（在 app.jsx 里由 `hasAI` 门控）。

import React from 'react'
import Icon from './Icon.jsx'
import { Sheet, SheetHeader, Spinner } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatPercent, formatPrice, formatStamp } from '../lib/format.js'
import { INDEX_ROWS, decimalsFor, resolveSymbol } from '../lib/symbol.js'
import { quoteTTL, resolveDataState } from '../lib/quotes.js'
import { accountLabel } from '../i18n/index.js'

const ROOT_CHIPS = ['market', 'review', 'watch', 'compare', 'explain']
const DETAIL_CHIPS = [
  { id: 'trend', icon: 'chart.line.uptrend.xyaxis' },
  { id: 'risk', icon: 'exclamationmark.triangle' },
  { id: 'peers', icon: 'arrow.left.arrow.right' },
  { id: 'metrics', icon: 'questionmark.circle' },
]

/**
 * 上下文构造（§13.3）。六个部分顺序固定：指数 / 自选 / 组合 / 行情时间 / 来源 / 数据质量。
 * 核心约束是明确告诉模型：**这是页面快照不是实时承诺**；只有页面数值或刚拉的 finance_* 结果
 * 算事实；要区分事实与推断；要保留来源与时间限定；仅供研究与模拟。
 */
export function buildContext(ctx) {
  const { t, locale, store, quotes, ledger, settings } = ctx
  const missingQuotes = []

  const indices = INDEX_ROWS.map((row) => {
    const quote = quotes.quote(row.canonical)
    if (!quote) { missingQuotes.push(row.canonical); return null }
    return `${t(row.key)} ${formatPrice(quote.price, 2)} ${formatPercent(quote.changePct)}`
  }).filter(Boolean).join('\n')

  const watch = store.items.slice(0, 20).map((item) => {
    const canonical = item.instrumentSymbol
    const quote = quotes.quote(canonical)
    const symbol = resolveSymbol(canonical)
    const decimals = symbol ? decimalsFor(symbol.market) : 2
    if (!quote) missingQuotes.push(canonical)
    return `${store.instrumentName(canonical)} [${canonical}] ${quote ? formatPrice(quote.price, decimals) : '—'} ${quote ? formatPercent(quote.changePct) : '—'}`
  }).join('\n')

  const portfolio = ledger.accounts.filter((row) => !row.isArchived).slice(0, 8).map((account) => {
    const valuation = ledger.valuation(account.id, quotes.quoteMap(), quotes.fx)
    const label = `${accountLabel(t, account.name)} (${account.currency})`
    if (!valuation || !valuation.isComplete) return `${label}: —`
    const holdings = valuation.rows.slice(0, 12)
      .map((row) => `${row.position.name} [${row.position.instrumentSymbol}] ×${row.position.quantity}`)
      .join(', ')
    return `${label} ${(valuation.totalMinor / 100).toFixed(2)}; ${holdings}`
  }).join('\n')

  const stamp = quotes.lastUpdated ? formatStamp(quotes.lastUpdated, locale) : '—'
  const sourceLabel = quotes.source === 'automatic' ? t('finance.settings.sourceAuto')
    : quotes.source === 'sina' ? 'Sina' : 'Tencent'

  const state = resolveDataState({
    failed: quotes.lastFailed,
    lastUpdated: quotes.lastUpdated,
    refreshing: false,
    missingCount: quotes.missingSymbols.length,
    ttlMs: quoteTTL(settings.refreshInterval),
    now: Date.now(),
  })
  const quality = []
  if (state === 'failedWithCache' || state === 'failedWithoutData') quality.push(t('finance.ai.data.failed'))
  else if (state === 'partial') quality.push(t('finance.quote.partial'))
  else if (state === 'cached') quality.push(t('finance.ai.data.cached'))
  else quality.push(t('finance.ai.data.fresh'))
  const missing = [...new Set(missingQuotes)].sort()
  if (missing.length > 0) quality.push(t('finance.valuation.missingQuoteList', missing.join(', ')))

  const header = locale === 'zh-Hans'
    ? '以下是理财页面此刻的快照，不是实时承诺。只有下面的数值、或你刚用 finance_* 工具拉到的结果，才算事实；其余一律说明是推断。回答时保留数据来源与时间限定。仅供研究与模拟，不构成投资建议。'
    : 'The following is a snapshot of the finance page right now, not a live guarantee. Only the values below — or results you just pulled with the finance_* tools — count as facts; label everything else as inference. Keep the source and time qualifier in your answer. Research and simulation only; not investment advice.'

  return [
    header,
    `\n[Indices]\n${indices || '—'}`,
    `\n[Watchlist]\n${watch || '—'}`,
    `\n[Portfolio]\n${portfolio || '—'}`,
    `\n[Quote time] ${stamp}`,
    `\n[Source] ${sourceLabel}`,
    `\n[Data quality] ${quality.join('; ')}`,
  ].join('\n')
}

export default function AIPanel({ ctx, session, onClose }) {
  const { t, locale, actions } = ctx
  const [text, setText] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const visible = !!session

  React.useEffect(() => { if (visible) setText('') }, [visible])
  if (!ctx.hasAI) return null

  const send = async (seed) => {
    const body = String(seed || text).trim()
    if (!body) return
    setBusy(true)
    // 种子 = base + 语言指令；systemContext 走 buildContext。
    await actions.askAI({
      identity: session.identity,
      seed: `${body}\n\n${t('finance.ai.replyLang')}`,
    })
    setBusy(false)
    onClose()
  }

  const detail = session && session.symbolName
  const chips = detail
    ? DETAIL_CHIPS.map((row) => ({
      id: row.id,
      icon: row.icon,
      label: t(`finance.ai.quick.${row.id}`),
      seed: t(`finance.ai.quick.${row.id}.seed`, session.symbolName),
    }))
    : ROOT_CHIPS.map((id) => ({
      id,
      label: t(`finance.ai.chip.${id}`),
      seed: t(`finance.ai.chip.${id}.seed`),
    }))

  return (
    <Sheet visible={visible} onClose={onClose}>
      <SheetHeader
        title={detail ? t('finance.companion.title') : t('finance.ai.title')}
        onClose={onClose}
        closeLabel={t('finance.done')}
      />
      <div className="fin-scroll" style={{ padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
        <span style={{ fontSize: 15, color: C.muted }}>{t('finance.ai.header')}</span>

        <div style={{
          display: 'flex', alignItems: 'flex-end', gap: SPACE.s2,
          background: C.surface, borderRadius: RADIUS.field, padding: SPACE.s3,
        }}
        >
          <textarea
            className="fin-field"
            rows={2}
            value={text}
            placeholder={t('finance.ai.ask.placeholder')}
            onChange={(event) => setText(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); send() }
            }}
            style={{ resize: 'none', lineHeight: 1.4, maxHeight: 96 }}
          />
          <button
            type="button"
            className="fin-btn fin-press"
            aria-label={t('finance.ai.ask.send')}
            disabled={!text.trim() || busy}
            onClick={() => send()}
            style={{ color: C.brand, opacity: text.trim() && !busy ? 1 : 0.35, flex: '0 0 auto' }}
          >
            {busy ? <Spinner size={22} color={C.brand} /> : <Icon name="arrow.up.circle.fill" size={26} />}
          </button>
        </div>

        {chips.map((chip) => (
          <button
            key={chip.id}
            type="button"
            className="fin-btn fin-press"
            onClick={() => send(chip.seed)}
            style={{
              display: 'flex', alignItems: 'center', gap: SPACE.s3,
              background: C.surface, borderRadius: RADIUS.field, padding: SPACE.s4,
            }}
          >
            {chip.icon ? <Icon name={chip.icon} size={17} color={C.brand} /> : null}
            <span style={{ flex: '1 1 auto', fontSize: 15 }}>{chip.label}</span>
            <Icon name="chevron.right" size={13} color={C.brand} />
          </button>
        ))}

        <span style={{ fontSize: 12, color: C.muted, textAlign: 'center', padding: `${SPACE.s2}px 0 ${SPACE.s4}px` }}>
          {t('finance.settings.disclaimer')}
        </span>
      </div>
    </Sheet>
  )
}

// 到价提醒面板 —— 规格 §3 右上 `bell` + §14.2 的诚实降级。
//
// footer 文案如实说明「刷新时检查、App 活跃时生效」：这个容器**没有后台唤醒**，
// 假装能后台盯盘比不做更糟。

import React from 'react'
import Icon from './Icon.jsx'
import { Field, Row, Segmented, Sheet, SheetHeader, Toggle } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatPercent, formatPrice } from '../lib/format.js'
import { parseNumberInput } from '../lib/money.js'
import { isPercentCondition } from '../lib/alerts.js'
import { decimalsFor } from '../lib/symbol.js'

const CONDITION_KEYS = {
  above: 'finance.alert.above',
  below: 'finance.alert.below',
  up_pct: 'finance.alert.upPct',
  down_pct: 'finance.alert.downPct',
}

export default function AlertPanel({ ctx, route, visible, onClose }) {
  const { t, alerts, quotes } = ctx
  const { canonical, symbol, name } = route || {}
  const [condition, setCondition] = React.useState('above')
  const [target, setTarget] = React.useState('')
  const quote = canonical ? quotes.quote(canonical) : null
  const decimals = symbol ? decimalsFor(symbol.market) : 2

  React.useEffect(() => {
    if (!visible) return
    setCondition('above')
    setTarget(quote ? formatPrice(quote.price, decimals) : '')
  }, [visible, canonical]) // eslint-disable-line react-hooks/exhaustive-deps

  const rows = canonical ? alerts.forSymbol(canonical) : []
  const value = parseNumberInput(target)
  const canSubmit = Number.isFinite(value)

  const submit = async () => {
    if (!canSubmit) return
    await alerts.set({ symbol: canonical, name, condition, targetPrice: value })
    setTarget('')
  }

  return (
    <Sheet visible={visible} onClose={onClose}>
      <SheetHeader title={t('finance.alert.title')} onClose={onClose} closeLabel={t('finance.done')} />
      <div className="fin-scroll" style={{ padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s4 }}>
        <Segmented
          value={condition}
          onChange={setCondition}
          items={Object.keys(CONDITION_KEYS).map((id) => ({ id, label: t(CONDITION_KEYS[id]) }))}
        />
        <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: `0 ${SPACE.s3}px` }}>
          <Field
            label={t('finance.alert.target')}
            value={target}
            onChange={setTarget}
            placeholder="0"
            suffix={isPercentCondition(condition) ? '%' : (quote ? quote.currency : '')}
          />
        </div>
        <button
          type="button"
          className="fin-btn fin-press"
          disabled={!canSubmit}
          onClick={submit}
          style={{
            textAlign: 'center', padding: '12px 0', borderRadius: RADIUS.field, fontSize: 16, fontWeight: 600,
            color: C.onAccent, background: C.brand, opacity: canSubmit ? 1 : 0.4,
          }}
        >
          {t('finance.alert.set')}
        </button>
        <span style={{ fontSize: 12, color: C.muted, lineHeight: 1.45 }}>{t('finance.alert.footer')}</span>

        {rows.length > 0 ? (
          <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: `0 ${SPACE.s3}px` }}>
            {rows.map((row, index) => (
              <Row
                key={row.id}
                title={`${t(CONDITION_KEYS[row.conditionRaw])} ${isPercentCondition(row.conditionRaw)
                  ? formatPercent(row.targetPrice)
                  : formatPrice(row.targetPrice, decimals)}`}
                subtitle={row.lastFiredAt ? new Date(row.lastFiredAt).toLocaleString() : null}
                last={index === rows.length - 1}
                accessory={(
                  <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3 }}>
                    <Toggle checked={row.enabled} onChange={(next) => alerts.setEnabled(row.id, next)} label={t('finance.alert.title')} />
                    <button
                      type="button"
                      className="fin-btn fin-press"
                      aria-label={t('finance.alert.delete')}
                      onClick={() => alerts.remove(row.id)}
                      style={{ color: C.danger }}
                    >
                      <Icon name="trash" size={16} />
                    </button>
                  </div>
                )}
              />
            ))}
          </div>
        ) : (
          <span style={{ fontSize: 13, color: C.muted }}>{t('finance.alert.empty')}</span>
        )}
      </div>
    </Sheet>
  )
}

// 图表（规格 §7）—— 全部手绘 SVG。
//
// **全模块没有一根蜡烛**：所有价格图都是折线 + 渐变面积图，
// **没有**十字光标、tooltip、长按刻度、双指缩放、时间轴标签。别"好心"升级成蜡烛图或加交互，
// 那会偏离 1:1（§15 第 1 条）。
//
// 为什么不用内置的 chart.js：这里要的是「面积渐变 18%→2%、X 轴完全隐藏、Y 轴不含 0」这种
// 逐像素对齐原生 Swift Charts 的形态。手绘 SVG 反而更短、更可控，也不引入需要注册控制器的依赖。

import React from 'react'
import { C } from './theme.js'

let gradientSeq = 0

function useGradientID() {
  const ref = React.useRef(null)
  if (ref.current === null) { gradientSeq += 1; ref.current = `fin-grad-${gradientSeq}` }
  return ref.current
}

/** 数值序列 → SVG 路径点。`nulls` 段自动断开（暖机期不画点）。 */
function pathFor(values, { width, height, min, max, padTop = 0, padBottom = 0 }) {
  const span = max - min || 1
  const usable = height - padTop - padBottom
  const step = values.length > 1 ? width / (values.length - 1) : 0
  let path = ''
  let pen = false
  for (let i = 0; i < values.length; i += 1) {
    const value = values[i]
    if (value === null || value === undefined || !Number.isFinite(value)) { pen = false; continue }
    const x = i * step
    const y = padTop + usable - ((value - min) / span) * usable
    path += `${pen ? 'L' : 'M'}${x.toFixed(2)} ${y.toFixed(2)}`
    pen = true
  }
  return path
}

function extent(series) {
  let min = Infinity
  let max = -Infinity
  for (const values of series) {
    for (const value of values) {
      if (value === null || value === undefined || !Number.isFinite(value)) continue
      if (value < min) min = value
      if (value > max) max = value
    }
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) return { min: 0, max: 1 }
  if (min === max) return { min: min - 1, max: max + 1 }
  return { min, max }
}

/**
 * 主图：面积（渐变 18% → 2%）+ 折线。x = **数组下标**（不是日期），y = 收盘价。
 * 主色 = sign(最后收盘 − 第一根收盘) 的涨跌色。Y 轴 automatic(includesZero: false)。
 */
export function AreaLineChart({
  values, overlays = [], height = 200, color, upIsRed = true, baseline,
}) {
  const gradientID = useGradientID()
  const width = 1000                                   // viewBox 宽；实际宽度由 CSS 撑满
  const clean = values.filter((value) => Number.isFinite(value))
  if (clean.length < 2) return <div style={{ height }} />

  const first = clean[0]
  const last = clean[clean.length - 1]
  const rising = last >= first
  const trend = color || ((rising === upIsRed) ? C.red : C.green)

  const series = [values, ...overlays.map((row) => row.values)]
  if (Array.isArray(baseline)) series.push(baseline)
  const { min, max } = extent(series)
  const geometry = { width, height, min, max, padTop: 6, padBottom: 6 }

  const line = pathFor(values, geometry)
  const step = values.length > 1 ? width / (values.length - 1) : 0
  const area = `${line}L${((values.length - 1) * step).toFixed(2)} ${height}L0 ${height}Z`

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      width="100%"
      height={height}
      style={{ display: 'block', overflow: 'visible' }}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={gradientID} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={trend} stopOpacity="0.18" />
          <stop offset="100%" stopColor={trend} stopOpacity="0.02" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#${gradientID})`} />
      {Array.isArray(baseline) ? (
        <path
          d={pathFor(baseline, geometry)}
          fill="none"
          stroke={C.muted}
          strokeWidth="1.4"
          strokeDasharray="5 4"
          vectorEffect="non-scaling-stroke"
        />
      ) : null}
      <path d={line} fill="none" stroke={trend} strokeWidth="1.8" vectorEffect="non-scaling-stroke" strokeLinejoin="round" />
      {overlays.map((row) => (
        <path
          key={row.id}
          d={pathFor(row.values, geometry)}
          fill="none"
          stroke={row.color}
          strokeWidth="1"
          vectorEffect="non-scaling-stroke"
          strokeLinejoin="round"
        />
      ))}
    </svg>
  )
}

/**
 * 副图（100pt）：柱 + 若干条线。MACD / KDJ / VOL 共用。
 * `bars` 按正负着涨跌色（VOL 则由调用方直接给每根的颜色）。
 */
export function SubChart({ bars, barColors, lines = [], height = 100, upIsRed = true }) {
  const width = 1000
  const series = lines.map((row) => row.values)
  if (bars) series.push(bars)
  const { min, max } = extent(series)
  const geometry = { width, height, min, max, padTop: 4, padBottom: 4 }
  const span = max - min || 1
  const usable = height - 8
  const zeroY = 4 + usable - ((0 - min) / span) * usable
  const count = bars ? bars.length : (lines[0] ? lines[0].values.length : 0)
  const slot = count > 0 ? width / count : 0
  const barWidth = Math.max(0.8, slot * 0.62)

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      width="100%"
      height={height}
      style={{ display: 'block' }}
      aria-hidden="true"
    >
      {bars ? bars.map((value, index) => {
        if (!Number.isFinite(value)) return null
        const y = 4 + usable - ((value - min) / span) * usable
        const top = Math.min(y, zeroY)
        const barHeight = Math.max(0.6, Math.abs(y - zeroY))
        const fill = barColors ? barColors[index]
          : ((value >= 0) === upIsRed ? C.red : C.green)
        return (
          <rect
            key={index}
            x={index * slot + (slot - barWidth) / 2}
            y={top}
            width={barWidth}
            height={barHeight}
            fill={fill}
          />
        )
      }) : null}
      {lines.map((row) => (
        <path
          key={row.id}
          d={pathFor(row.values, geometry)}
          fill="none"
          stroke={row.color}
          strokeWidth="1"
          vectorEffect="non-scaling-stroke"
        />
      ))}
    </svg>
  )
}

/** 资金流柱状图：y 单位「亿元」，按正负着色，高 90，x 轴隐藏。 */
export function BarChart({ values, height = 90, upIsRed = true }) {
  if (!values || values.length === 0) return null
  return <SubChart bars={values} height={height} upIsRed={upIsRed} />
}

/**
 * 资产配置环形图：`innerRadius = 0.62`、`angularInset 1.5`、110×110。图例由调用方自己画。
 */
export function DonutChart({ slices, size = 110, colors }) {
  const total = slices.reduce((sum, row) => sum + Math.max(0, row.value), 0)
  if (total <= 0) return null
  const radius = size / 2
  const inner = radius * 0.62
  const gap = 1.5                                       // angularInset，单位度

  let angle = -90
  const paths = slices.map((row, index) => {
    const sweep = (Math.max(0, row.value) / total) * 360
    const from = angle + gap / 2
    const to = angle + sweep - gap / 2
    angle += sweep
    if (to <= from) return null
    const rad = (deg) => (deg * Math.PI) / 180
    const x1 = radius + radius * Math.cos(rad(from))
    const y1 = radius + radius * Math.sin(rad(from))
    const x2 = radius + radius * Math.cos(rad(to))
    const y2 = radius + radius * Math.sin(rad(to))
    const x3 = radius + inner * Math.cos(rad(to))
    const y3 = radius + inner * Math.sin(rad(to))
    const x4 = radius + inner * Math.cos(rad(from))
    const y4 = radius + inner * Math.sin(rad(from))
    const large = to - from > 180 ? 1 : 0
    return (
      <path
        key={row.id || index}
        d={`M${x1} ${y1}A${radius} ${radius} 0 ${large} 1 ${x2} ${y2}L${x3} ${y3}A${inner} ${inner} 0 ${large} 0 ${x4} ${y4}Z`}
        fill={colors[index % colors.length]}
      />
    )
  })

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ display: 'block', flex: '0 0 auto' }} aria-hidden="true">
      {paths}
    </svg>
  )
}

/** 环形图与图例共用的配色（brand 起头，其余取中性可辨识色）。 */
export const ALLOCATION_COLORS = [C.brand, C.blue, C.amber, C.green, C.muted]

/** 折线（持仓收益曲线 h140 / 策略曲线 h130）——无面积、Y 不含 0。 */
export function LineChart({ values, baseline, height = 140, color, upIsRed = true }) {
  return (
    <AreaLineChart values={values} baseline={baseline} height={height} color={color} upIsRed={upIsRed} />
  )
}

// 详情页 —— 规格 §3。
//
// 与自选行相反，这里的**现价按涨跌着色**（38pt medium）。行情时间是 **Provider 原始串直出**
// （腾讯 A 股是 `20260803150001` 这种），刻意不格式化——它是「这份数据到底多新」的唯一证据。

import React from 'react'
import Icon from './Icon.jsx'
import FundamentalsView from './FundamentalsView.jsx'
import { AreaLineChart, SubChart } from './Chart.jsx'
import { Card, Menu, PullRefresh, Spinner, Stat } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import {
  formatChange, formatCompact, formatCompactCurrency, formatPercent, formatPrice, toLots, trendColor,
} from '../lib/format.js'
import { boll, kdj, macd, sma } from '../lib/indicators.js'
import { decimalsFor } from '../lib/symbol.js'

const PERIODS = ['5m', '15m', '30m', '60m', 'day', 'week', 'month']
const INDICATORS = ['MA', 'BOLL', 'MACD', 'KDJ', 'VOL']
const CANDLE_COUNT = 160

function periodLabel(t, period) {
  // 分钟档**原样英文，不本地化**（与原生一致）。
  if (period === 'day' || period === 'week' || period === 'month') return t(`finance.period.${period}`)
  return period
}

/** 主图叠加线（MA / BOLL）。暖机期是 null，Chart 会自动断开不画点。 */
function overlaysFor(indicator, closes) {
  if (indicator === 'MA') {
    return [
      { id: 'ma5', values: sma(closes, 5), color: C.amber },
      { id: 'ma20', values: sma(closes, 20), color: C.blue },
    ]
  }
  if (indicator === 'BOLL') {
    const bands = boll(closes, 20, 2)
    return [
      { id: 'mid', values: bands.mid, color: C.muted },
      { id: 'upper', values: bands.upper, color: C.amber },
      { id: 'lower', values: bands.lower, color: C.blue },
    ]
  }
  return []
}

function SubIndicator({ indicator, candles, upIsRed }) {
  const closes = candles.map((row) => row.close)
  if (indicator === 'MACD') {
    const result = macd(closes)
    return (
      <SubChart
        bars={result.hist}
        upIsRed={upIsRed}
        lines={[
          { id: 'dif', values: result.dif, color: C.amber },
          { id: 'dea', values: result.dea, color: C.blue },
        ]}
      />
    )
  }
  if (indicator === 'KDJ') {
    const result = kdj(candles)
    return (
      <SubChart
        lines={[
          { id: 'k', values: result.k, color: C.amber },
          { id: 'd', values: result.d, color: C.blue },
          { id: 'j', values: result.j, color: C.brand },
        ]}
      />
    )
  }
  if (indicator === 'VOL') {
    return (
      <SubChart
        bars={candles.map((row) => row.volume)}
        barColors={candles.map((row) => ((row.close >= row.open) === upIsRed ? C.red : C.green))}
      />
    )
  }
  return null
}

/** 五档：先卖五→卖一（asks 取前 5 后 reverse），再买一→买五。量 = 原始量 ÷ 100（手）。 */
function OrderBook({ quote, t, upIsRed, decimals }) {
  const asks = quote.asks.slice(0, 5).reverse()
  const bids = quote.bids.slice(0, 5)
  const line = (row, kind, index) => (
    <div key={`${kind}-${index}`} style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: '3px 0' }}>
      <span style={{ fontSize: 12, color: C.muted, flex: '0 0 auto' }}>
        {t(kind === 'ask' ? 'finance.book.ask' : 'finance.book.bid')}
      </span>
      <span style={{ flex: '1 1 auto' }} />
      <span className="fin-mono" style={{ fontSize: 15, color: (kind === 'ask') === upIsRed ? C.green : C.red }}>
        {formatPrice(row.price, decimals)}
      </span>
      <span className="fin-mono" style={{ fontSize: 12, color: C.muted, width: 70, textAlign: 'right', flex: '0 0 auto' }}>
        {toLots(row.volume)}
      </span>
    </div>
  )
  return (
    <Card title={t('finance.orderbook')}>
      {asks.map((row, index) => line(row, 'ask', index))}
      {bids.map((row, index) => line(row, 'bid', index))}
    </Card>
  )
}

export default function DetailPage({ ctx, route }) {
  const { t, quotes, settings, store, actions } = ctx
  const { canonical, symbol } = route
  const decimals = decimalsFor(symbol.market)
  const upIsRed = settings.upIsRed

  const scrollRef = React.useRef(null)
  const [period, setPeriod] = React.useState('day')
  const [adjust, setAdjust] = React.useState('qfq')
  const [indicator, setIndicator] = React.useState('MA')
  const [candles, setCandles] = React.useState([])
  const [chartLoading, setChartLoading] = React.useState(true)
  const [quoteFailed, setQuoteFailed] = React.useState(false)
  const [refreshing, setRefreshing] = React.useState(false)

  const quote = quotes.quote(canonical)
  const isMinute = period !== 'day' && period !== 'week' && period !== 'month'
  // 复权菜单**只在「非分钟级 且 非基金」时出现**。
  const showsAdjust = !isMinute && symbol.market !== 'fund'

  // 进页：先用缓存秒显（避免价格闪 0），再拉行情。
  React.useEffect(() => {
    let cancelled = false
    const run = async () => {
      const result = await quotes.refresh([canonical], { force: false })
      if (cancelled) return
      setQuoteFailed(result.failed)
      const fresh = result.quotes[canonical]
      if (fresh) store.noteInstrument(canonical, fresh)
    }
    run()
    return () => { cancelled = true }
  }, [canonical, quotes, store])

  // K 线：拿到空结果时**保留上一份 candles**（不清空图）。
  React.useEffect(() => {
    let cancelled = false
    setChartLoading(true)
    const run = async () => {
      const rows = await quotes.candles(symbol, period, adjust, CANDLE_COUNT, { force: false })
      if (cancelled) return
      if (rows.length > 0) setCandles(rows)
      setChartLoading(false)
    }
    run()
    return () => { cancelled = true }
  }, [symbol, period, adjust, quotes])

  const refresh = React.useCallback(async () => {
    setRefreshing(true)
    const [result, rows] = await Promise.all([
      quotes.refresh([canonical], { force: true }),
      quotes.candles(symbol, period, adjust, CANDLE_COUNT, { force: true }),
    ])
    setQuoteFailed(result.failed)
    if (rows.length > 0) setCandles(rows)
    setRefreshing(false)
  }, [canonical, symbol, period, adjust, quotes])

  const closes = candles.map((row) => row.close)
  const name = (quote && quote.name) || store.instrumentName(canonical)
  const watched = store.isWatched(canonical)
  const hasSub = indicator === 'MACD' || indicator === 'KDJ' || indicator === 'VOL'

  const stats = [
    { key: 'open', label: t('finance.stat.open'), value: quote ? formatPrice(quote.open, decimals) : '—' },
    { key: 'high', label: t('finance.stat.high'), value: quote ? formatPrice(quote.high, decimals) : '—' },
    { key: 'low', label: t('finance.stat.low'), value: quote ? formatPrice(quote.low, decimals) : '—' },
    { key: 'prevClose', label: t('finance.stat.prevClose'), value: quote ? formatPrice(quote.prevClose, decimals) : '—' },
  ]
  if (quote) {
    // 条件格：数据存在才渲染（不要一排「—」占位）。
    if (quote.amount) stats.push({ key: 'amount', label: t('finance.stat.amount'), value: formatCompactCurrency(quote.amount, quote.currency) })
    if (quote.turnover) stats.push({ key: 'turnover', label: t('finance.stat.turnover'), value: formatPercent(quote.turnover, false) })
    if (quote.pe > 0) stats.push({ key: 'pe', label: t('finance.stat.pe'), value: formatPrice(quote.pe, 2) })
    if (quote.pb > 0) stats.push({ key: 'pb', label: t('finance.stat.pb'), value: formatPrice(quote.pb, 2) })
    // 总市值原始单位是「亿」。
    if (quote.marketCap > 0) stats.push({ key: 'mktcap', label: t('finance.stat.mktcap'), value: formatCompact(quote.marketCap * 1e8) })
    if (quote.amplitude) stats.push({ key: 'amplitude', label: t('finance.stat.amplitude'), value: formatPercent(quote.amplitude, false) })
  }

  // 提醒入口住在这一排，不住顶栏：详情页改由**宿主**画顶栏（原生子页栈接管返回），
  // 自绘顶栏只在没有宿主顶栏的形态下出现，把入口挂在那儿等于「有时有、有时没有」。
  const actionButtons = [
    { id: 'watch', icon: watched ? 'star.fill' : 'star', label: t(watched ? 'finance.action.watching' : 'finance.action.watch'), onClick: () => actions.toggleWatch(canonical, name) },
    { id: 'alert', icon: 'bell', label: t('finance.alert.title'), onClick: () => actions.openAlert(canonical, symbol, name) },
    { id: 'trade', icon: 'arrow.left.arrow.right', label: t('finance.action.trade'), disabled: !quote, onClick: () => actions.openTrade(canonical, symbol, name) },
    { id: 'strategy', icon: 'function', label: t('finance.action.strategy'), onClick: () => actions.openStrategy(canonical, symbol, name) },
  ]
  if (ctx.hasAI) {
    actionButtons.push({ id: 'ai', icon: 'sparkles', label: t('finance.action.ai'), onClick: () => actions.askAboutSymbol(canonical, name, quote) })
  }

  return (
    <PullRefresh scrollRef={scrollRef} refreshing={refreshing} onRefresh={refresh}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4 }}>
        {/* 头部 */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: SPACE.s2, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 22, fontWeight: 500 }}>{name}</span>
            <span className="fin-mono" style={{ fontSize: 13, color: C.muted }}>{canonical}</span>
            {quote && quote.isEstimate ? (
              <span style={{
                fontSize: 12, color: C.muted, padding: '1px 6px', borderRadius: RADIUS.pill,
                background: 'color-mix(in srgb, var(--fin-muted) 12%, transparent)',
              }}
              >
                {t('finance.estimate')}
              </span>
            ) : null}
          </div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>
            <span
              className="fin-mono"
              style={{ fontSize: 38, fontWeight: 500, color: quote ? trendColor(quote.changePct, upIsRed) : C.ink, lineHeight: 1.05 }}
            >
              {quote ? formatPrice(quote.price, decimals) : '—'}
            </span>
            {quote ? (
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                <span className="fin-mono" style={{ fontSize: 15, color: trendColor(quote.changePct, upIsRed) }}>
                  {formatChange(quote.change, decimals)}
                </span>
                <span className="fin-mono" style={{ fontSize: 15, color: trendColor(quote.changePct, upIsRed) }}>
                  {formatPercent(quote.changePct)}
                </span>
              </div>
            ) : null}
          </div>
          {quote && quote.time ? (
            <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>{quote.time}</span>
          ) : null}
          {quoteFailed ? (
            <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 12, color: C.muted }}>
              <Icon name="wifi.exclamationmark" size={11} />
              {t('finance.quote.stale')}
            </span>
          ) : null}
        </div>

        {/* 周期 / 复权 / 指标 */}
        <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s4, flexWrap: 'wrap' }}>
          <Menu
            icon="clock"
            label={periodLabel(t, period)}
            value={period}
            items={PERIODS.map((id) => ({ id, label: periodLabel(t, id) }))}
            onSelect={setPeriod}
          />
          {showsAdjust ? (
            <Menu
              icon="arrow.triangle.2.circlepath"
              label={t(`finance.chart.${adjust}`)}
              value={adjust}
              items={[
                { id: 'qfq', label: t('finance.chart.qfq') },
                { id: 'hfq', label: t('finance.chart.hfq') },
              ]}
              onSelect={setAdjust}
            />
          ) : null}
          <Menu
            icon="function"
            label={indicator}
            value={indicator}
            items={INDICATORS.map((id) => ({ id, label: id }))}
            onSelect={setIndicator}
          />
        </div>

        {/* 图表 */}
        {candles.length > 1 ? (
          <div>
            <AreaLineChart
              values={closes}
              overlays={overlaysFor(indicator, closes)}
              height={200}
              upIsRed={upIsRed}
            />
            {hasSub ? (
              <div style={{ marginTop: SPACE.s2 }}>
                <SubIndicator indicator={indicator} candles={candles} upIsRed={upIsRed} />
              </div>
            ) : null}
          </div>
        ) : chartLoading ? (
          <div style={{
            height: 200, background: C.surface, borderRadius: RADIUS.card,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
          >
            <Spinner size={22} color={C.muted} />
          </div>
        ) : (
          <div style={{
            height: 200, background: C.surface, borderRadius: RADIUS.card,
            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8,
          }}
          >
            <Icon name="chart.line.downtrend.xyaxis" size={28} color={C.muted} />
            <span style={{ fontSize: 15, color: C.muted }}>{t('finance.chart.unavailable')}</span>
            <button type="button" className="fin-btn fin-press" onClick={refresh} style={{ color: C.brand, fontSize: 15 }}>
              {t('finance.retry')}
            </button>
          </div>
        )}

        {/* 操作行（4 个等宽按钮，brand 前景色） */}
        <div style={{ display: 'flex', gap: SPACE.s2 }}>
          {actionButtons.map((button) => (
            <button
              key={button.id}
              type="button"
              className="fin-btn fin-press"
              disabled={button.disabled}
              onClick={button.onClick}
              style={{
                flex: '1 1 0', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
                padding: '8px 4px', background: C.surface, borderRadius: RADIUS.field,
                color: C.brand, opacity: button.disabled ? 0.4 : 1,
              }}
            >
              <Icon name={button.icon} size={17} weight="semibold" />
              <span style={{ fontSize: 12 }}>{button.label}</span>
            </button>
          ))}
        </div>

        {/* 指标网格：3 列 */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: SPACE.s3 }}>
          {stats.map((row) => <Stat key={row.key} label={row.label} value={row.value} />)}
        </div>

        {/* 五档盘口（仅 A 股有 bids/asks 时） */}
        {quote && quote.bids.length > 0 && quote.asks.length > 0 ? (
          <OrderBook quote={quote} t={t} upIsRed={upIsRed} decimals={decimals} />
        ) : null}

        {/* 基本面（**仅 A 股**渲染） */}
        <FundamentalsView ctx={ctx} symbol={symbol} />
      </div>
    </PullRefresh>
  )
}

// 基本面区块 —— 规格 §4。
//
// **仅 A 股渲染**：港股/美股/基金整个区块不出现，尽管底层财务接口支持港美股
// （UI 层写死了 market == ashare，§15 第 12 条）。
// 懒加载：同一 canonical 只拉一次；四张卡各自「无数据就整卡不渲染」。

import React from 'react'
import { BarChart } from './Chart.jsx'
import { Card, Spinner, Stat } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatCompactCurrency, formatPercent, formatPrice, trendColor } from '../lib/format.js'
import { fetchAnnouncements, fetchDividends, fetchFinancials } from '../lib/providers/eastmoney.js'
import { fetchFundFlow } from '../lib/providers/push2.js'
import { canonicalOf, secid } from '../lib/symbol.js'

const FLOW_DAYS = 20

export default function FundamentalsView({ ctx, symbol }) {
  const { t, settings } = ctx
  const canonical = canonicalOf(symbol)
  const [state, setState] = React.useState({ loading: true, financials: [], flows: [], dividends: [], announcements: [] })

  React.useEffect(() => {
    if (symbol.market !== 'ashare') return undefined
    let cancelled = false
    setState({ loading: true, financials: [], flows: [], dividends: [], announcements: [] })
    const run = async () => {
      // 四个接口串行 await（对齐原生；也避免一次打爆免费源的限频）。
      const financials = await fetchFinancials(symbol)
      const flows = await fetchFundFlow(secid(symbol), 60)
      const dividends = await fetchDividends(symbol)
      const announcements = await fetchAnnouncements(symbol, 20)
      if (cancelled) return
      setState({ loading: false, financials, flows, dividends, announcements })
    }
    run()
    return () => { cancelled = true }
  }, [canonical, symbol])

  if (symbol.market !== 'ashare') return null

  if (state.loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', padding: `${SPACE.s5}px 0` }}>
        <Spinner size={18} color={C.muted} />
      </div>
    )
  }

  const latest = state.financials[0]
  const recentFlows = state.flows.slice(-FLOW_DAYS)
  const cumulative = recentFlows.reduce((sum, row) => sum + row.mainNet, 0)
  const upIsRed = settings.upIsRed

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4 }}>
      {latest ? (
        <Card title={t('finance.fin.title')} subtitle={latest.periodName}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: SPACE.s3 }}>
            <Stat
              label={t('finance.fin.revenue')}
              value={(
                <span style={{ display: 'flex', alignItems: 'baseline', gap: 5 }}>
                  {formatCompactCurrency(latest.revenue, latest.currency)}
                  <span className="fin-mono" style={{ fontSize: 12, color: trendColor(latest.revenueYoY, upIsRed) }}>
                    {formatPercent(latest.revenueYoY)}
                  </span>
                </span>
              )}
            />
            <Stat
              label={t('finance.fin.netprofit')}
              value={(
                <span style={{ display: 'flex', alignItems: 'baseline', gap: 5 }}>
                  {formatCompactCurrency(latest.netProfit, latest.currency)}
                  <span className="fin-mono" style={{ fontSize: 12, color: trendColor(latest.netProfitYoY, upIsRed) }}>
                    {formatPercent(latest.netProfitYoY)}
                  </span>
                </span>
              )}
            />
            <Stat label={t('finance.fin.roe')} value={formatPercent(latest.roe, false)} />
            <Stat label={t('finance.fin.gross')} value={formatPercent(latest.grossMargin, false)} />
            <Stat label={t('finance.fin.eps')} value={formatPrice(latest.eps, 2)} />
            <Stat label={t('finance.fin.bps')} value={formatPrice(latest.bps, 2)} />
          </div>
        </Card>
      ) : null}

      {recentFlows.length > 0 ? (
        <Card title={t('finance.flow.title')}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: SPACE.s2, marginBottom: SPACE.s2 }}>
            <span style={{ fontSize: 12, color: C.muted }}>{t('finance.flow.mainCum')}</span>
            <span className="fin-mono" style={{ fontSize: 15, fontWeight: 500, color: trendColor(cumulative, upIsRed) }}>
              {formatCompactCurrency(cumulative, 'CNY')}
            </span>
          </div>
          {/* y = mainNet / 1e8（亿元） */}
          <BarChart values={recentFlows.map((row) => row.mainNet / 1e8)} height={90} upIsRed={upIsRed} />
        </Card>
      ) : null}

      {state.dividends.length > 0 ? (
        <Card title={t('finance.div.title')}>
          {state.dividends.slice(0, 5).map((row) => (
            <div key={`${row.reportDate}-${row.plan}`} style={{ display: 'flex', gap: SPACE.s2, padding: '4px 0' }}>
              <span className="fin-mono" style={{ fontSize: 12, color: C.muted, width: 82, flex: '0 0 auto' }}>
                {row.reportDate}
              </span>
              <span className="fin-clamp-2" style={{ fontSize: 12, color: C.ink }}>{row.plan}</span>
            </div>
          ))}
        </Card>
      ) : null}

      {state.announcements.length > 0 ? (
        <Card title={t('finance.news.annTitle')}>
          {state.announcements.slice(0, 6).map((row) => (
            <div key={row.id} style={{ display: 'flex', flexDirection: 'column', gap: 2, padding: '5px 0' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>{row.date}</span>
                {row.kind ? (
                  <span style={{
                    fontSize: 12, color: C.brand, padding: '1px 5px', borderRadius: RADIUS.pill,
                    background: 'color-mix(in srgb, var(--fin-brand) 10%, transparent)',
                  }}
                  >
                    {row.kind}
                  </span>
                ) : null}
              </div>
              <span className="fin-clamp-2" style={{ fontSize: 12, color: C.ink }}>{row.title}</span>
            </div>
          ))}
        </Card>
      ) : null}
    </div>
  )
}

// 行业页 —— 规格 §5。
//
// ⚠️ 这一页的数据源（push2 / push2ex）**只在中国大陆网络下通**。所以：
//  · 进页**先从磁盘快照 hydrate 当前段**再拉网络（stale-while-revalidate 的「先显缓存」半程）；
//  · 拉不到就优雅回退到缓存/空态，**不要转圈到超时**（§15 第 11 条）；
//  · 拉取中且无数据才显转圈——不要一进来就显「暂无数据」。
//
// 北向资金面板**不做**（§8.7：官方 2024-08 已停更，字段全 null，原生也放弃了）。

import React from 'react'
import { Chip, EmptyState, PullRefresh, Segmented, Sheet, SheetHeader, Spinner, Stat } from './primitives.jsx'
import Icon from './Icon.jsx'
import { C, SPACE } from './theme.js'
import { formatCompactCurrency, formatPercent, formatShortStamp, trendColor } from '../lib/format.js'
import { fetchBreadth, fetchConstituents, fetchMoneyRank, fetchSectors } from '../lib/providers/push2.js'
import { fetchDragonBoard } from '../lib/providers/eastmoney.js'
import { exchangeForAShare } from '../lib/symbol.js'

const SEGMENTS = ['sectors', 'money', 'dragon']

function Divider() {
  return <div style={{ height: 0.5, background: 'color-mix(in srgb, var(--fin-muted) 12%, transparent)' }} />
}

/** 通用两栏行：左（名 + 副标题）/ 右（主值 + 次值）。 */
function DataRow({ title, subtitle, primary, primaryColor, secondary, secondaryColor, onClick }) {
  return (
    <button
      type="button"
      className="fin-btn fin-press"
      onClick={onClick}
      style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: '9px 0' }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0, flex: '1 1 auto' }}>
        <span className="fin-clamp-1" style={{ fontSize: 15, color: C.ink }}>{title}</span>
        {subtitle ? <span className="fin-clamp-1" style={{ fontSize: 12, color: C.muted }}>{subtitle}</span> : null}
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 2, flex: '0 0 auto' }}>
        <span className="fin-mono" style={{ fontSize: 15, fontWeight: 500, color: primaryColor }}>{primary}</span>
        <span className="fin-mono" style={{ fontSize: 12, color: secondaryColor || C.muted }}>{secondary}</span>
      </div>
    </button>
  )
}

export default function IndustryPage({ ctx }) {
  const { t, settings, store, actions } = ctx
  const upIsRed = settings.upIsRed
  const scrollRef = React.useRef(null)

  const [segment, setSegment] = React.useState('sectors')
  const [kind, setKind] = React.useState('industry')
  const [sort, setSort] = React.useState('change')
  const [inflow, setInflow] = React.useState(true)
  const [rows, setRows] = React.useState([])
  const [breadth, setBreadth] = React.useState(null)
  const [loading, setLoading] = React.useState(true)
  const [stale, setStale] = React.useState(false)
  const [updatedAt, setUpdatedAt] = React.useState(null)
  const [sector, setSector] = React.useState(null)

  const cacheKey = `${segment}:${kind}:${sort}:${inflow}`
  const busy = React.useRef(false)

  const load = React.useCallback(async (force) => {
    if (busy.current) return                       // 并发保护：loading 时直接返回
    busy.current = true
    setLoading(true)
    try {
      let fresh = []
      if (segment === 'sectors') fresh = await fetchSectors({ kind, sort, limit: 60 })
      else if (segment === 'money') fresh = await fetchMoneyRank({ inflow, limit: 30 })
      else fresh = await fetchDragonBoard(40)

      if (fresh.length > 0) {
        setRows(fresh)
        setStale(false)
        setUpdatedAt(Date.now())
        store.persistIndustry(cacheKey, fresh)
      } else {
        // 空 → 回退磁盘快照并标 stale；都没有才显空态。
        const cached = await store.loadIndustry(cacheKey)
        if (cached && Array.isArray(cached.payload) && cached.payload.length > 0) {
          setRows(cached.payload)
          setStale(true)
          setUpdatedAt(cached.at)
        } else {
          setRows([])
        }
      }
      // 情绪横幅只在「首次为空」或 force 时重拉。
      if (breadth === null || force) {
        const sentiment = await fetchBreadth(Date.now())
        if (sentiment) setBreadth(sentiment)
      }
    } finally {
      busy.current = false
      setLoading(false)
    }
  }, [segment, kind, sort, inflow, cacheKey, store, breadth])

  // 先 hydrate 当前段的磁盘快照秒显，再拉网络。
  React.useEffect(() => {
    let cancelled = false
    const run = async () => {
      const cached = await store.loadIndustry(cacheKey)
      if (!cancelled && cached && Array.isArray(cached.payload)) {
        setRows(cached.payload)
        setStale(true)
        setUpdatedAt(cached.at)
      }
      if (!cancelled) load(false)
    }
    run()
    return () => { cancelled = true }
  }, [cacheKey]) // eslint-disable-line react-hooks/exhaustive-deps

  // 自动刷新（默认**关**）：间隔 = max(60, refreshInterval)，循环内用 force=true。
  React.useEffect(() => {
    if (!settings.industryAutoRefresh) return undefined
    const interval = Math.max(60, settings.refreshInterval || 60) * 1000
    const timer = window.setInterval(() => load(true), interval)
    return () => window.clearInterval(timer)
  }, [settings.industryAutoRefresh, settings.refreshInterval, load])

  const openSector = React.useCallback((row) => setSector(row), [])

  const openStock = React.useCallback((code, marketFlag) => {
    const exchange = marketFlag === 1 ? 'sh' : marketFlag === 0 ? 'sz' : exchangeForAShare(code)
    actions.openDetail(`${exchange}${code}`)
  }, [actions])

  return (
    <>
      <PullRefresh scrollRef={scrollRef} refreshing={loading && rows.length > 0} onRefresh={() => load(true)}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4 }}>
          {breadth ? (
            <div style={{ background: C.surface, borderRadius: 16, padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
              <div style={{ display: 'flex', alignItems: 'baseline' }}>
                <span style={{ fontSize: 13, color: C.muted, flex: '1 1 auto' }}>{t('finance.senti.title')}</span>
                <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>{breadth.tradeDate}</span>
              </div>
              <div style={{ display: 'flex', gap: SPACE.s4, flexWrap: 'wrap' }}>
                <Stat label={t('finance.senti.limitup')} value={breadth.limitUp} valueSize={17} color={upIsRed ? C.red : C.green} />
                <Stat label={t('finance.senti.limitdown')} value={breadth.limitDown} valueSize={17} color={upIsRed ? C.green : C.red} />
                <Stat label={t('finance.senti.broken')} value={breadth.brokenBoard} valueSize={17} />
                <Stat label={t('finance.senti.sealrate')} value={formatPercent(breadth.limitUpRatio, false)} valueSize={17} />
                {breadth.maxContBoards > 0 ? (
                  <Stat label={t('finance.senti.contboards')} value={breadth.maxContBoards} valueSize={17} color={upIsRed ? C.red : C.green} />
                ) : null}
              </div>
            </div>
          ) : null}

          <Segmented
            value={segment}
            onChange={setSegment}
            items={SEGMENTS.map((id) => ({ id, label: t(`finance.ind.seg.${id}`) }))}
          />

          {segment === 'sectors' ? (
            <div style={{ display: 'flex', gap: SPACE.s2, flexWrap: 'wrap' }}>
              <Chip label={t('finance.ind.kind.industry')} selected={kind === 'industry'} onClick={() => setKind('industry')} />
              <Chip label={t('finance.ind.kind.concept')} selected={kind === 'concept'} onClick={() => setKind('concept')} />
              <span style={{ flex: '1 1 auto' }} />
              <Chip label={t('finance.ind.sort.change')} selected={sort === 'change'} onClick={() => setSort('change')} />
              <Chip label={t('finance.ind.sort.money')} selected={sort === 'moneyflow'} onClick={() => setSort('moneyflow')} />
            </div>
          ) : null}

          {segment === 'money' ? (
            <div style={{ display: 'flex', gap: SPACE.s2 }}>
              <Chip label={t('finance.ind.money.inflow')} selected={inflow} onClick={() => setInflow(true)} />
              <Chip label={t('finance.ind.money.outflow')} selected={!inflow} onClick={() => setInflow(false)} />
            </div>
          ) : null}

          {segment === 'dragon' && rows.length > 0 ? (
            <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>{rows[0].tradeDate}</span>
          ) : null}

          {loading && rows.length === 0 ? (
            <div style={{ display: 'flex', justifyContent: 'center', padding: '40px 0' }}>
              <Spinner size={22} color={C.muted} />
            </div>
          ) : rows.length === 0 ? (
            <EmptyState text={t('finance.ind.empty')} padding={40} />
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              {rows.map((row, index) => (
                <React.Fragment key={`${row.code}-${index}`}>
                  {index > 0 ? <Divider /> : null}
                  {segment === 'sectors' ? (
                    <DataRow
                      title={row.name}
                      subtitle={row.leaderName ? `${t('finance.ind.leader')} ${row.leaderName}` : null}
                      primary={formatPercent(row.changePct)}
                      primaryColor={trendColor(row.changePct, upIsRed)}
                      secondary={formatCompactCurrency(row.mainNet, 'CNY')}
                      secondaryColor={trendColor(row.mainNet, upIsRed)}
                      onClick={() => openSector(row)}
                    />
                  ) : segment === 'money' ? (
                    <DataRow
                      title={row.name}
                      subtitle={row.sector ? `${row.code} · ${row.sector}` : row.code}
                      primary={formatCompactCurrency(row.mainNet, 'CNY')}
                      primaryColor={trendColor(row.mainNet, upIsRed)}
                      secondary={formatPercent(row.changePct)}
                      secondaryColor={trendColor(row.changePct, upIsRed)}
                      onClick={() => openStock(row.code, row.marketFlag)}
                    />
                  ) : (
                    <DataRow
                      title={row.name}
                      subtitle={row.reason}
                      primary={formatCompactCurrency(row.netBuy, 'CNY')}
                      primaryColor={trendColor(row.netBuy, upIsRed)}
                      secondary={formatPercent(row.changePct)}
                      secondaryColor={trendColor(row.changePct, upIsRed)}
                      onClick={() => openStock(row.code)}
                    />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}

          {rows.length > 0 ? (
            <div style={{
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              fontSize: 12, color: C.muted, paddingBottom: SPACE.s4,
            }}
            >
              {loading ? <Spinner size={12} color={C.muted} /> : null}
              {updatedAt
                ? (stale
                  ? t('finance.updated.cached', formatShortStamp(updatedAt))
                  : t('finance.updated', formatShortStamp(updatedAt)))
                : null}
            </div>
          ) : null}
        </div>
      </PullRefresh>

      <ConstituentsSheet ctx={ctx} sector={sector} onClose={() => setSector(null)} onOpenStock={openStock} />
    </>
  )
}

/** 成分股弹层（§5.5）：点板块行进这里，不是详情页。 */
function ConstituentsSheet({ ctx, sector, onClose, onOpenStock }) {
  const { t, settings } = ctx
  const [rows, setRows] = React.useState([])
  const [loading, setLoading] = React.useState(false)

  React.useEffect(() => {
    if (!sector) return undefined
    let cancelled = false
    setLoading(true)
    setRows([])
    fetchConstituents(sector.code, 40).then((result) => {
      if (cancelled) return
      setRows(result)
      setLoading(false)
    })
    return () => { cancelled = true }
  }, [sector])

  return (
    <Sheet visible={!!sector} onClose={onClose}>
      <SheetHeader
        title={sector ? sector.name : ''}
        onClose={onClose}
        closeLabel={<Icon name="xmark" size={14} weight="semibold" />}
      />
      <div className="fin-scroll" style={{ padding: `0 ${SPACE.s4}px` }}>
        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '40px 0' }}>
            <Spinner size={20} color={C.muted} />
          </div>
        ) : rows.length === 0 ? (
          <EmptyState text={t('finance.ind.empty')} padding={40} />
        ) : rows.map((row, index) => (
          <React.Fragment key={row.code}>
            {index > 0 ? <Divider /> : null}
            <button
              type="button"
              className="fin-btn fin-press"
              onClick={() => { onClose(); onOpenStock(row.code, row.marketFlag) }}
              style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, width: '100%', padding: '10px 0' }}
            >
              <span className="fin-clamp-1" style={{ fontSize: 15, color: C.ink, flex: '1 1 auto', textAlign: 'left' }}>
                {row.name}
              </span>
              <span
                className="fin-mono"
                style={{ fontSize: 14, width: 72, textAlign: 'right', color: trendColor(row.changePct, settings.upIsRed) }}
              >
                {formatPercent(row.changePct)}
              </span>
              {/* 这里的主力净流入刻意**不着色**（与板块行不同）。 */}
              <span className="fin-mono" style={{ fontSize: 13, width: 72, textAlign: 'right', color: C.muted }}>
                {formatCompactCurrency(row.mainNet, 'CNY')}
              </span>
            </button>
          </React.Fragment>
        ))}
        <div style={{ height: SPACE.s6 }} />
      </div>
    </Sheet>
  )
}

// 持仓页 —— 规格 §10 的可视化面。
//
// 数据诚实性底线（§15 第 7 条）：缺行情或缺汇率的持仓一律**按 0 计并打标**，
// 账户显「当前估值不完整 + 缺失清单」；**诊断/快照/绩效只消费完整估值**——
// 不完整时不出健康分、不写快照，而不是拿半份数据凑一个看起来很像的数字。

import React from 'react'
import Icon from './Icon.jsx'
import { ALLOCATION_COLORS, DonutChart, LineChart } from './Chart.jsx'
import { Card, Chip, ChipRow, EmptyState, PullRefresh, Spinner, Stat } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import {
  formatMinor, formatPercent, formatPrice, formatQuantity, trendColor,
} from '../lib/format.js'
import { accountLabel } from '../i18n/index.js'
import { decimalsFor, resolveSymbol } from '../lib/symbol.js'

function PositionRow({ row, t, upIsRed, onOpen }) {
  const symbol = resolveSymbol(row.position.instrumentSymbol)
  const decimals = symbol ? decimalsFor(symbol.market) : 2
  const currency = row.position.currency
  return (
    <button
      type="button"
      className="fin-btn fin-press"
      onClick={() => onOpen(row.position.instrumentSymbol)}
      style={{
        display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%', padding: '9px 0',
        borderBottom: `0.5px solid ${C.line}`,
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0, flex: '1 1 auto' }}>
        <span className="fin-clamp-1" style={{ fontSize: 15, color: C.ink }}>{row.position.name}</span>
        <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>
          {formatQuantity(row.position.quantity)} × {formatPrice(row.position.avgCost, decimals)} {currency}
        </span>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 2, flex: '0 0 auto' }}>
        <span className="fin-mono" style={{ fontSize: 15, fontWeight: 500 }}>
          {row.priced ? formatMinor(row.marketValueMinor, row.accountCurrency) : '—'}
        </span>
        <span className="fin-mono" style={{ fontSize: 12, color: trendColor(row.unrealizedMinor, upIsRed) }}>
          {row.priced
            ? `${formatMinor(row.unrealizedMinor, row.accountCurrency, { signed: true })} ${formatPercent(row.unrealizedPct)}`
            : t(row.missingQuote ? 'finance.valuation.missingQuote' : 'finance.valuation.missingFX')}
        </span>
      </div>
    </button>
  )
}

export default function PortfolioPage({ ctx }) {
  const { t, ledger, settings, actions, valuation, perf } = ctx
  const scrollRef = React.useRef(null)
  const upIsRed = settings.upIsRed

  const accounts = ledger.accounts.filter((row) => !row.isArchived)
  const account = valuation ? valuation.account : null

  if (accounts.length === 0) {
    return <EmptyState icon="wallet.pass" text={t('finance.portfolio.noAccount')} />
  }
  if (!valuation) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', padding: '40px 0' }}>
        <Spinner size={20} color={C.muted} />
      </div>
    )
  }

  const currency = account.currency
  const rows = valuation.rows.map((row) => ({ ...row, accountCurrency: currency }))
  const allocation = ledger.allocation(valuation)
  const diagnosis = ledger.diagnose(valuation, perf)
  const snapshots = ledger.snapshotsOf(account.id)
  const orders = ledger.ordersOf(account.id, 8)

  const contributor = diagnosis.contributor
  const detractor = diagnosis.detractor

  return (
    <PullRefresh scrollRef={scrollRef} refreshing={ctx.refreshing} onRefresh={() => actions.refresh(true)}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s4, padding: SPACE.s4 }}>
        {accounts.length > 1 ? (
          <ChipRow padding={0}>
            {accounts.map((row) => (
              <Chip
                key={row.id}
                label={accountLabel(t, row.name)}
                selected={row.id === account.id}
                onClick={() => actions.selectAccount(row.id)}
              />
            ))}
          </ChipRow>
        ) : null}

        {/* 总览 */}
        <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <span style={{ fontSize: 12, color: C.muted }}>{t('finance.portfolio.total')}</span>
            <span className="fin-mono" style={{ fontSize: 32, fontWeight: 500 }}>
              {formatMinor(valuation.totalMinor, currency)}
            </span>
          </div>
          <div style={{ display: 'flex', gap: SPACE.s5, flexWrap: 'wrap' }}>
            <Stat
              label={t('finance.portfolio.pnl')}
              value={formatMinor(valuation.totalPnlMinor, currency, { signed: true })}
              color={trendColor(valuation.totalPnlMinor, upIsRed)}
            />
            <Stat
              label={t('finance.portfolio.return')}
              value={formatPercent(valuation.returnRate)}
              color={trendColor(valuation.returnRate, upIsRed)}
            />
            <Stat
              label={t('finance.portfolio.today')}
              value={formatMinor(valuation.dayMinor, currency, { signed: true })}
              color={trendColor(valuation.dayMinor, upIsRed)}
            />
          </div>
          <div style={{ display: 'flex', gap: SPACE.s5, flexWrap: 'wrap' }}>
            <Stat label={t('finance.portfolio.cash')} value={formatMinor(valuation.cashMinor, currency)} />
            <Stat label={t('finance.portfolio.holdings')} value={formatMinor(valuation.marketValueMinor, currency)} />
            <Stat
              label={t('finance.card.realized')}
              value={formatMinor(valuation.realizedMinor, currency, { signed: true })}
              color={trendColor(valuation.realizedMinor, upIsRed)}
            />
          </div>

          {!valuation.isComplete ? (
            <div style={{
              display: 'flex', flexDirection: 'column', gap: 3, padding: `${SPACE.s2}px ${SPACE.s3}px`,
              borderRadius: 10, background: 'color-mix(in srgb, var(--fin-warning) 12%, transparent)',
            }}
            >
              <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12, color: C.warning }}>
                <Icon name="exclamationmark.triangle" size={11} />
                {t('finance.valuation.incomplete')}
              </span>
              {valuation.missingQuotes.length > 0 ? (
                <span style={{ fontSize: 12, color: C.muted }}>
                  {t('finance.valuation.missingQuoteList', valuation.missingQuotes.join(', '))}
                </span>
              ) : null}
              {valuation.missingFX.length > 0 ? (
                <span style={{ fontSize: 12, color: C.muted }}>
                  {t('finance.valuation.missingFXList', valuation.missingFX.join(', '))}
                </span>
              ) : null}
            </div>
          ) : null}
        </div>

        {/* 操作 */}
        <div style={{ display: 'flex', gap: SPACE.s2 }}>
          {[
            { id: 'cash', icon: 'dollarsign.circle', label: t('finance.cashflow.title'), onClick: actions.openCashFlow },
            { id: 'accounts', icon: 'creditcard', label: t('finance.account.manage'), onClick: actions.openAccounts },
            { id: 'history', icon: 'list.bullet', label: t('finance.portfolio.history'), onClick: actions.openHistory },
          ].map((button) => (
            <button
              key={button.id}
              type="button"
              className="fin-btn fin-press"
              onClick={button.onClick}
              style={{
                flex: '1 1 0', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
                padding: '8px 4px', background: C.surface, borderRadius: RADIUS.field, color: C.brand,
              }}
            >
              <Icon name={button.icon} size={17} weight="semibold" />
              <span style={{ fontSize: 12 }}>{button.label}</span>
            </button>
          ))}
        </div>

        {/* 收益曲线（快照 ≥ 2 才有意义） */}
        {snapshots.length >= 2 ? (
          <Card title={t('finance.portfolio.curve')}>
            <LineChart values={snapshots.map((row) => row.totalValueMinor / 100)} height={140} upIsRed={upIsRed} />
          </Card>
        ) : null}

        {/* 持仓 */}
        <Card title={t('finance.portfolio.positions')}>
          {rows.length === 0 ? (
            <EmptyState text={t('finance.portfolio.noPositions')} padding={24} />
          ) : rows.map((row) => (
            <PositionRow
              key={row.position.id || row.position.instrumentSymbol}
              row={row}
              t={t}
              upIsRed={upIsRed}
              onOpen={actions.openDetail}
            />
          ))}
        </Card>

        {/* 资产配置 */}
        {allocation.length > 0 ? (
          <Card title={t('finance.alloc.title')}>
            <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s4 }}>
              <DonutChart
                size={110}
                colors={ALLOCATION_COLORS}
                slices={allocation.map((row) => ({ id: row.market, value: row.marketValueMinor }))}
              />
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6, flex: '1 1 auto', minWidth: 0 }}>
                {allocation.map((row, index) => (
                  <div key={row.market} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{
                      width: 8, height: 8, borderRadius: 2, flex: '0 0 auto',
                      background: ALLOCATION_COLORS[index % ALLOCATION_COLORS.length],
                    }}
                    />
                    <span style={{ fontSize: 13, color: C.ink, flex: '1 1 auto' }}>{t(`market.${row.market}`)}</span>
                    <span className="fin-mono" style={{ fontSize: 13, color: C.muted }}>
                      {formatPercent(row.ratio * 100, false)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </Card>
        ) : null}

        {/* 绩效 */}
        <Card title={t('finance.perf.title')}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: SPACE.s3 }}>
            <Stat label={t('finance.perf.annualized')} value={formatPercent(perf.annualized)} color={trendColor(perf.annualized, upIsRed)} />
            <Stat label={t('finance.perf.maxdd')} value={formatPercent(perf.maxDrawdown, false)} />
            <Stat label={t('finance.perf.sharpe')} value={formatPrice(perf.sharpe, 2)} />
            <Stat label={t('finance.perf.vol')} value={formatPercent(perf.volatility, false)} />
            <Stat label={t('finance.perf.winrate')} value={formatPercent(perf.winRate, false)} />
            <Stat label={t('finance.perf.trades')} value={perf.closed} />
          </div>
          {!perf.hasEnoughData ? (
            <span style={{ display: 'block', fontSize: 12, color: C.muted, marginTop: SPACE.s2, lineHeight: 1.4 }}>
              {t('finance.perf.accruing')}
            </span>
          ) : null}
        </Card>

        {/* 业绩归因 */}
        {(contributor || detractor) ? (
          <Card title={t('finance.attr.title')}>
            {contributor ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: '4px 0' }}>
                <span className="fin-clamp-1" style={{ fontSize: 15, flex: '1 1 auto' }}>{contributor.position.name}</span>
                <span className="fin-mono" style={{ fontSize: 15, color: trendColor(1, upIsRed) }}>
                  {formatPercent(contributor.unrealizedPct)}
                </span>
              </div>
            ) : null}
            {detractor ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: '4px 0' }}>
                <span className="fin-clamp-1" style={{ fontSize: 15, flex: '1 1 auto' }}>{detractor.position.name}</span>
                <span className="fin-mono" style={{ fontSize: 15, color: trendColor(-1, upIsRed) }}>
                  {formatPercent(detractor.unrealizedPct)}
                </span>
              </div>
            ) : null}
          </Card>
        ) : null}

        {/* 组合诊断：**估值不完整时不展示分数** */}
        <Card title={t('finance.diag.title')}>
          {!diagnosis.isComplete ? (
            <span style={{ fontSize: 13, color: C.muted, lineHeight: 1.45 }}>{t('finance.diag.incomplete')}</span>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 }}>
                <span className="fin-mono" style={{ fontSize: 34, fontWeight: 500, color: C.brand }}>{diagnosis.score}</span>
                <span style={{ fontSize: 13, color: C.muted }}>{t('finance.diag.scoreUnit')}</span>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: SPACE.s3 }}>
                <Stat label={t('finance.diag.cash')} value={formatPercent(diagnosis.cashPct, false)} />
                <Stat label={t('finance.diag.hhi')} value={formatPrice(diagnosis.hhi, 2)} />
                <Stat label={t('finance.diag.topweight')} value={formatPercent(diagnosis.topWeight * 100, false)} />
              </div>
              {diagnosis.flags.length === 0 ? (
                <span style={{ fontSize: 13, color: C.muted }}>{t('finance.diag.healthy')}</span>
              ) : diagnosis.flags.map((flag) => (
                <span key={flag} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 13, color: C.warning }}>
                  <Icon name="exclamationmark.triangle" size={12} />
                  {t(`finance.diag.flag.${flag}`)}
                </span>
              ))}
            </div>
          )}
        </Card>

        {/* 最近成交 */}
        {orders.length > 0 ? (
          <Card
            title={t('finance.portfolio.history')}
            trailing={(
              <button type="button" className="fin-btn fin-press" onClick={actions.openHistory} style={{ fontSize: 12, color: C.brand }}>
                {t('finance.history.viewAll')}
              </button>
            )}
          >
            {orders.map((order) => (
              <div key={order.id} style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: '6px 0' }}>
                <span style={{
                  fontSize: 12, color: C.onAccent, padding: '1px 6px', borderRadius: 4, flex: '0 0 auto',
                  background: (order.sideRaw === 'buy') === upIsRed ? C.red : C.green,
                }}
                >
                  {t(order.sideRaw === 'buy' ? 'finance.trade.buy' : 'finance.trade.sell')}
                </span>
                <span className="fin-clamp-1" style={{ fontSize: 14, flex: '1 1 auto' }}>{order.name}</span>
                <span className="fin-mono" style={{ fontSize: 13, color: C.muted }}>
                  {formatQuantity(order.quantity)} × {formatPrice(order.price, 2)}
                </span>
              </div>
            ))}
          </Card>
        ) : null}

        <span style={{ fontSize: 12, color: C.muted, textAlign: 'center', paddingBottom: SPACE.s4 }}>
          {t('finance.settings.disclaimer')}
        </span>
      </div>
    </PullRefresh>
  )
}

// 页面通用零件：空态 / 分段 / chip / 下拉菜单 / 底部面板 / 左滑删除 / 下拉刷新 / 数字输入。
//
// 弹层刻意自绘（不用 antd-mobile 的 Popup / ActionSheet / Toast）——运行时已知
// `Toast.show` 渲染为空，同族命令式弹层风险相同；自绘的 fixed 覆盖层在 WebView 里行为确定。

import React from 'react'
import Icon from './Icon.jsx'
import { C, RADIUS, SPACE } from './theme.js'

export function Spinner({ size = 16, color = 'currentColor' }) {
  return (
    <svg className="fin-spin" viewBox="0 0 24 24" width={size} height={size} style={{ display: 'block', color }}>
      <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="2.4" strokeOpacity="0.22" />
      <path d="M21 12a9 9 0 0 0-9-9" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" />
    </svg>
  )
}

export function EmptyState({ icon, text, actionLabel, onAction, padding = 48 }) {
  return (
    <div style={{
      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10,
      padding: `${padding}px 32px`, textAlign: 'center',
    }}
    >
      {icon ? <Icon name={icon} size={34} color={C.muted} /> : null}
      <span style={{ fontSize: 15, color: C.muted, lineHeight: 1.4 }}>{text}</span>
      {actionLabel ? (
        <button type="button" className="fin-btn fin-press" onClick={onAction} style={{ color: C.brand, fontSize: 15 }}>
          {actionLabel}
        </button>
      ) : null}
    </div>
