}

/** 设置/列表里的一行。 */
export function Row({ icon, title, subtitle, detail, detailColor, accessory, onClick, danger, last }) {
  const Element = onClick ? 'button' : 'div'
  return (
    <Element
      className={onClick ? 'fin-btn fin-press' : undefined}
