// MARK: - 左滑删除（自选行始终可用）

export function SwipeRow({ children, actionLabel, onAction, disabled }) {
  const [offset, setOffset] = React.useState(0)
  const [animating, setAnimating] = React.useState(false)
  const state = React.useRef({ active: false, startX: 0, startY: 0, base: 0, lock: null })
  const WIDTH = 82

  if (disabled) return children

  const settle = (value) => {
    setAnimating(true)
    setOffset(value)
    window.setTimeout(() => setAnimating(false), 200)
  }

  return (
    <div style={{ position: 'relative', overflow: 'hidden' }}>
      <button
        type="button"
        className="fin-btn fin-press"
        onClick={() => { settle(0); onAction() }}
        style={{
          position: 'absolute', top: 0, right: 0, bottom: 0, width: WIDTH,
          background: C.danger, color: '#fff', fontSize: 15,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}
      >
        {actionLabel}
      </button>
      <div
        style={{
          transform: `translate3d(${offset}px, 0, 0)`,
          transition: animating ? 'transform 200ms ease' : 'none',
          background: C.bg,
          position: 'relative',
        }}
        onTouchStart={(event) => {
          const touch = event.touches[0]
          state.current = { active: true, startX: touch.clientX, startY: touch.clientY, base: offset, lock: null }
        }}
        onTouchMove={(event) => {
          if (!state.current.active) return
          const touch = event.touches[0]
          const dx = touch.clientX - state.current.startX
          const dy = touch.clientY - state.current.startY
          if (state.current.lock === null) {
            if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return
            state.current.lock = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v'
          }
          if (state.current.lock !== 'h') return
          if (event.cancelable) event.preventDefault()
          setOffset(Math.max(-WIDTH, Math.min(0, state.current.base + dx)))
        }}
        onTouchEnd={() => {
          if (!state.current.active) return
          state.current.active = false
          if (state.current.lock !== 'h') return
          settle(offset < -WIDTH / 2 ? -WIDTH : 0)
        }}
      >
        {children}
      </div>
    </div>
  )
}

// MARK: - 下拉刷新

export function PullRefresh({ onRefresh, refreshing, children, scrollRef, style }) {
  const [pull, setPull] = React.useState(0)
  const state = React.useRef({ active: false, startY: 0 })
  const THRESHOLD = 64

  return (
    <div
      ref={scrollRef}
      className="fin-scroll"
      style={style}
      onTouchStart={(event) => {
        const node = scrollRef.current
        if (!node || node.scrollTop > 0 || refreshing) return
        state.current = { active: true, startY: event.touches[0].clientY }
      }}
      onTouchMove={(event) => {
        if (!state.current.active) return
        const dy = event.touches[0].clientY - state.current.startY
        if (dy <= 0) { setPull(0); return }
        setPull(Math.min(96, dy * 0.5))
      }}
      onTouchEnd={() => {
        if (!state.current.active) return
        state.current.active = false
        if (pull >= THRESHOLD) onRefresh()
        setPull(0)
      }}
    >
      <div style={{
        height: refreshing ? 40 : pull,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        transition: state.current.active ? 'none' : 'height 200ms ease',
        overflow: 'hidden', color: C.muted,
      }}
      >
        {refreshing || pull > 8 ? <Spinner size={18} color={C.brand} /> : null}
      </div>
      {children}
    </div>
  )
}

// 搜索页（sheet）—— 规格 §6。
//
// 两条容易做错的时序：
//  · query 变化后**防抖 300ms** 才发请求，结果落地后再批量拉这些结果的行情；
//  · **搜索历史在「点开详情」时记入**，不是敲键时，也不是点加自选时（§15 第 10 条）。

import React from 'react'
import Icon from './Icon.jsx'
import { VirtualList } from './VirtualList.jsx'
import { EmptyState, Sheet, SheetHeader, Spinner } from './primitives.jsx'
import { SearchField } from './Shell.jsx'
import { C, SPACE } from './theme.js'
import { formatPercent, formatPriceFor, trendColor } from '../lib/format.js'
import { HOT_SEEDS } from '../lib/store.js'
import { parseStrict, resolveSymbol } from '../lib/symbol.js'
import * as tencent from '../lib/providers/tencent.js'
import * as fund from '../lib/providers/fund.js'

const DEBOUNCE_MS = 300
const MARKET_ORDER = ['ashare', 'hk', 'us', 'fund']

/** 股票/场内基金走腾讯联想；场外基金走本地全量目录过滤。结果按 canonical 去重。 */
export async function searchInstruments(query) {
  const text = String(query || '').trim()
  if (!text) return []
  const [listed, funds] = await Promise.all([tencent.search(text), fund.search(text, 20)])
  const seen = new Set()
  const out = []
  for (const row of [...listed, ...funds]) {
    if (seen.has(row.symbol)) continue
    seen.add(row.symbol)
    out.push(row)
  }
  return out
}

function ResultRow({ hit, ctx, onOpen }) {
  const { t, store, quotes, settings } = ctx
  const quote = quotes.quote(hit.symbol)
  const watched = store.isWatched(hit.symbol)
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, padding: `8px ${SPACE.s4}px`, minHeight: 52 }}>
