          <span className="fin-clamp-1" style={{ fontSize: 15, color: C.ink }}>{hit.name}</span>
          <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>
            {hit.symbol} · {t(`market.${hit.market}`)}
          </span>
