// 交易面板 —— 规格 §10.1 / §10.2 的输入面。
//
// 跨币种时**必须显示成交汇率与折算金额**：这是「为什么扣了这么多钱」的唯一解释。
// 拿不到汇率就**不允许下单**（绝不用 1 兜底），按钮禁用并说明缺汇率。

import React from 'react'
import { Field, Segmented, Sheet, SheetHeader, Stat } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatMinor, formatPrice } from '../lib/format.js'
import { grossMinorOf, parseNumberInput, roundHalfAway, toMinor } from '../lib/money.js'
import { currencyOf, decimalsFor } from '../lib/symbol.js'
import { accountLabel } from '../i18n/index.js'

export default function TradePanel({ ctx, route, visible, onClose }) {
  const { t, ledger, quotes, settings } = ctx
  const { canonical, symbol, name } = route || {}
  const [side, setSide] = React.useState('buy')
  const [accountID, setAccountID] = React.useState(null)
  const [qty, setQty] = React.useState('')
  const [price, setPrice] = React.useState('')
  const [fee, setFee] = React.useState('')
  const [error, setError] = React.useState(null)
  const [busy, setBusy] = React.useState(false)

  const quote = canonical ? quotes.quote(canonical) : null
  const accounts = ledger.accounts.filter((row) => !row.isArchived)
  const account = ledger.accountByID(accountID) || accounts[0] || null
  const instrumentCurrency = symbol ? currencyOf(symbol) : 'CNY'
  const decimals = symbol ? decimalsFor(symbol.market) : 2

  // 价格默认取现价。
  React.useEffect(() => {
    if (!visible) return
    setSide('buy')
    setError(null)
    setQty('')
    setFee('')
    setPrice(quote ? String(formatPrice(quote.price, decimals)) : '')
    setAccountID((current) => current || (accounts[0] ? accounts[0].id : null))
  }, [visible, canonical]) // eslint-disable-line react-hooks/exhaustive-deps

  const rate = account
    ? ledger.fxRateFor(instrumentCurrency, account.currency, quotes.fx)
    : null
  const quantity = parseNumberInput(qty)
  const unitPrice = parseNumberInput(price)
  const feeMinor = Math.max(0, toMinor(parseNumberInput(fee) || 0))

  let grossMinor = null
  let settledMinor = null
  let cashAfter = null
  if (quantity > 0 && unitPrice > 0 && rate) {
    try {
      grossMinor = grossMinorOf(quantity, unitPrice)
      settledMinor = roundHalfAway(grossMinor * rate)
      cashAfter = side === 'buy'
        ? account.cashMinor - settledMinor - feeMinor
        : account.cashMinor + settledMinor - feeMinor
    } catch (caught) {
      grossMinor = null
    }
  }

  const position = account
    ? ledger.positions.find((row) => row.accountID === account.id && row.instrumentSymbol === canonical)
    : null
  const canSubmit = !!account && !!rate && quantity > 0 && unitPrice > 0 && !busy
    && (side === 'buy' ? (cashAfter !== null && cashAfter >= 0) : (position && position.quantity >= quantity - 1e-9))

  const submit = async () => {
    if (!canSubmit) return
    setBusy(true)
    setError(null)
    const payload = {
      accountID: account.id,
      symbol: canonical,
      name,
      market: symbol.market,
      currency: instrumentCurrency,
      quantity,
      price: unitPrice,
      fxRate: rate,
      feeMinor,
      source: 'manual',
    }
    const result = side === 'buy' ? await ledger.buy(payload) : await ledger.sell(payload)
    setBusy(false)
    if (result.ok) { onClose(); return }
    setError(result.error)
  }

  return (
    <Sheet visible={visible} onClose={onClose}>
      <SheetHeader title={name || ''} onClose={onClose} closeLabel={t('finance.cancel')} />
      <div className="fin-scroll" style={{ padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s4 }}>
        <Segmented
          value={side}
          onChange={(next) => { setSide(next); setError(null) }}
          items={[
            { id: 'buy', label: t('finance.trade.buy') },
            { id: 'sell', label: t('finance.trade.sell') },
          ]}
        />

        {accounts.length > 1 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: SPACE.s2 }}>
            {accounts.map((row) => (
              <button
                key={row.id}
                type="button"
                className="fin-btn fin-press"
                onClick={() => setAccountID(row.id)}
                style={{
                  padding: '5px 10px', borderRadius: RADIUS.pill, fontSize: 12,
                  color: row.id === account.id ? C.brand : C.muted,
                  background: row.id === account.id
                    ? 'color-mix(in srgb, var(--fin-brand) 12%, transparent)' : C.surface,
                }}
              >
                {accountLabel(t, row.name)}
              </button>
            ))}
          </div>
        ) : null}

        <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: `0 ${SPACE.s3}px` }}>
          <Field label={t('finance.trade.qty')} value={qty} onChange={setQty} placeholder="0" autoFocus />
          <Field label={t('finance.trade.price')} value={price} onChange={setPrice} placeholder="0" suffix={instrumentCurrency} />
          <Field label={t('finance.trade.fee')} value={fee} onChange={setFee} placeholder="0" suffix={account ? account.currency : ''} />
        </div>

        {account ? (
          <div style={{ background: C.surface, borderRadius: RADIUS.card, padding: SPACE.s3, display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
            {instrumentCurrency !== account.currency ? (
              <div style={{ display: 'flex', gap: SPACE.s5, flexWrap: 'wrap' }}>
                <Stat label={t('finance.trade.settleCcy')} value={account.currency} />
                <Stat label={t('finance.trade.fxRate')} value={rate ? formatPrice(rate, 4) : '—'} />
                <Stat
                  label={t('finance.trade.settledAmount')}
                  value={settledMinor !== null ? formatMinor(settledMinor, account.currency) : '—'}
                />
              </div>
            ) : null}
            <div style={{ display: 'flex', gap: SPACE.s5, flexWrap: 'wrap' }}>
              <Stat
                label={t(side === 'buy' ? 'finance.trade.cost' : 'finance.trade.proceeds')}
                value={settledMinor !== null
                  ? formatMinor(side === 'buy' ? settledMinor + feeMinor : settledMinor - feeMinor, account.currency)
                  : '—'}
              />
              <Stat label={t('finance.trade.cash')} value={formatMinor(account.cashMinor, account.currency)} />
              <Stat
                label={t('finance.trade.cashAfter')}
                value={cashAfter !== null ? formatMinor(cashAfter, account.currency) : '—'}
                color={cashAfter !== null && cashAfter < 0 ? C.danger : undefined}
              />
            </div>
            {side === 'sell' && position ? (
              <span style={{ fontSize: 12, color: C.muted }}>
                {t('finance.portfolio.positions')} {position.quantity}
              </span>
            ) : null}
          </div>
        ) : null}

        {!rate ? (
          <span style={{ fontSize: 13, color: C.warning }}>{t('finance.trade.error.invalidRate')}</span>
        ) : null}
        {error ? (
          <span style={{ fontSize: 13, color: C.danger }}>
            {t(`finance.trade.error.${error}`)}
          </span>
        ) : null}

        <button
          type="button"
          className="fin-btn fin-press"
          disabled={!canSubmit}
          onClick={submit}
          style={{
            textAlign: 'center', padding: '13px 0', borderRadius: RADIUS.field, fontSize: 16, fontWeight: 600,
            color: C.onAccent, opacity: canSubmit ? 1 : 0.4,
            background: (side === 'buy') === settings.upIsRed ? C.red : C.green,
          }}
        >
          {t('finance.trade.confirm')}
        </button>
        <span style={{ fontSize: 12, color: C.muted, textAlign: 'center' }}>{t('finance.settings.disclaimer')}</span>
      </div>
    </Sheet>
  )
}

// 虚拟长列表 —— **`aibox/ui` 的同接口本地兜底**。
//
// 为什么不直接 `import { VirtualList } from 'aibox/ui'`：该资产在
// `WebAssets/applet-runtime/src/aibox-ui/` 里已经存在，但**说明符还没进
// `AppletImportRules.bareWhitelist`（Swift 侧）与 market 的 `BARE_IMPORT_ALLOWLIST`**，
// 现在写裸 import 会转译期被拒 / validate 报错 → 整个模块白屏。
// 所以这里实现一份 props 完全对齐的兜底；等 `aibox/ui` 上架后，把本文件换成
// `export { VirtualList } from 'aibox/ui'` 即可，调用方一行不用改。
//
// 与框架版的差异：不接 §3.1 的原生手势层（宿主还没有），`onVisibleRowsChange` 照常回调；
// 滚动位置恢复用 sessionStorage，键前缀与框架版一致。

import React from 'react'

const RESTORE_PREFIX = 'aibox.vlist:'

function defaultKeyExtractor(item, index) {
  if (item && typeof item === 'object') {
    if (item.id !== undefined && item.id !== null) return String(item.id)
    if (item.key !== undefined && item.key !== null) return String(item.key)
  }
  return String(index)
}

/** 量化到 0.5px —— 消除浮点抖动导致的「高度变了」误判（否则会无限重渲）。 */
function quantize(value) {
  return Math.round(value * 2) / 2
}

function indexAtOffset(offsets, count, y) {
  if (count <= 0) return 0
  let lo = 0
  let hi = count - 1
  let ans = 0
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    if (offsets[mid] <= y) { ans = mid; lo = mid + 1 } else { hi = mid - 1 }
  }
  return ans
}

export function VirtualList({
  items,
  renderRow,
  keyExtractor,
  estimatedRowHeight = 64,
  overscan = 6,
  overscanPx = 240,
  header = null,
  footer = null,
  empty = null,
  onEndReached,
  endReachedThreshold = 400,
  onVisibleRowsChange,
  onScroll,
  restoreKey,
  className,
  style,
  rowStyle,
  scrollParentRef,
}) {
  const list = Array.isArray(items) ? items : []
  const count = list.length
  const estimate = estimatedRowHeight > 0 ? estimatedRowHeight : 64

  const ownRef = React.useRef(null)
  const regionRef = React.useRef(null)
  // 列表**不一定是自己滚**：包在 PullRefresh 里时真正滚动的是外层容器。
  // 那种情况下必须监听外层的 scroll，否则 viewport 永远是 0 高，
  // 只渲染 overscan 那几行 —— 列表看起来「被截断了」。
  const scrollRef = scrollParentRef || ownRef
  const measured = React.useRef(null)
  if (measured.current === null) measured.current = new Map()
  const endArmed = React.useRef(true)
  const [viewport, setViewport] = React.useState({ top: 0, height: 0 })
  const [, forceRender] = React.useReducer((n) => n + 1, 0)

  const keyOf = React.useRef(keyExtractor || defaultKeyExtractor)

  // 偏移表：measured 里有实测就用实测，否则用估算。
  const { offsets, total } = React.useMemo(() => {
    const rows = new Float64Array(count)
    let running = 0
    for (let i = 0; i < count; i += 1) {
      rows[i] = running
      running += measured.current.get(keyOf.current(list[i], i)) || estimate
    }
    return { offsets: rows, total: running }
    // measured 的变化通过 forceRender 触发重算，故此处不进依赖表。
  }, [list, count, estimate]) // eslint-disable-line react-hooks/exhaustive-deps

  const start = Math.max(0, indexAtOffset(offsets, count, viewport.top - overscanPx) - overscan)
  const endOffset = viewport.top + viewport.height + overscanPx
  let end = start
  while (end < count && offsets[end] < endOffset) end += 1
  end = Math.min(count, end + overscan)

  /** 虚拟区顶端相对滚动容器内容原点的偏移（header 高度、外层 padding 都算在内）。 */
  const regionOffset = React.useCallback(() => {
    const scroller = scrollRef.current
    const region = regionRef.current
    if (!scroller || !region) return 0
    return region.getBoundingClientRect().top - scroller.getBoundingClientRect().top + scroller.scrollTop
  }, [scrollRef])

  const sync = React.useCallback(() => {
    const node = scrollRef.current
    if (!node) return
    setViewport({ top: node.scrollTop - regionOffset(), height: node.clientHeight })
    if (restoreKey) {
      try { window.sessionStorage.setItem(RESTORE_PREFIX + restoreKey, String(node.scrollTop)) } catch (error) { /* 配额满不影响列表 */ }
    }
    if (onEndReached) {
      const remaining = node.scrollHeight - node.scrollTop - node.clientHeight
      if (remaining < endReachedThreshold) {
        if (endArmed.current) { endArmed.current = false; onEndReached() }
      } else {
        endArmed.current = true
      }
    }
  }, [scrollRef, regionOffset, restoreKey, onEndReached, endReachedThreshold])

  const onScrollEvent = React.useCallback((event) => {
    sync()
    if (onScroll) onScroll(event)
  }, [sync, onScroll])

  // 自己不是滚动容器时，事件要挂到外层；同时用 RO 跟踪容器尺寸变化（键盘弹起、下拉刷新头展开）。
  React.useEffect(() => {
    if (!scrollParentRef) return undefined
    const node = scrollParentRef.current
    if (!node) return undefined
    node.addEventListener('scroll', sync, { passive: true })
    let observer = null
    if (typeof ResizeObserver !== 'undefined') {
      observer = new ResizeObserver(sync)
      observer.observe(node)
    }
    return () => {
      node.removeEventListener('scroll', sync)
      if (observer) observer.disconnect()
    }
  }, [scrollParentRef, sync])

  React.useLayoutEffect(() => { sync() }, [sync, count])

  // 滚动位置恢复（等首屏行挂载完再还原）。
  React.useEffect(() => {
    if (!restoreKey) return undefined
    const node = scrollRef.current
    if (!node) return undefined
    let raw = null
    try { raw = window.sessionStorage.getItem(RESTORE_PREFIX + restoreKey) } catch (error) { raw = null }
    const value = Number(raw)
    if (!Number.isFinite(value) || value <= 0) return undefined
    const timer = window.setTimeout(() => { node.scrollTop = value }, 0)
    return () => window.clearTimeout(timer)
  }, [restoreKey])

  // 实测回填：只观测在窗口内的行；离开窗口显式 unobserve
  // ——ResizeObserver 对目标是**强引用**，不解绑就是持续泄漏。
  const observer = React.useRef(null)
  const observed = React.useRef(null)
  if (observed.current === null) observed.current = new Map()

  React.useEffect(() => {
    if (typeof ResizeObserver === 'undefined') return undefined
    observer.current = new ResizeObserver((entries) => {
      let changed = false
      for (const entry of entries) {
        const key = observed.current.get(entry.target)
        if (!key) continue
        const height = quantize(entry.contentRect.height + 0)
        if (height > 0 && measured.current.get(key) !== height) {
          measured.current.set(key, height)
          changed = true
        }
      }
      if (changed) forceRender()
    })
    return () => {
      observer.current.disconnect()
      observed.current.clear()
    }
  }, [])

  const attachRow = React.useCallback((key) => (node) => {
    const ro = observer.current
    if (!node) return
    const height = quantize(node.getBoundingClientRect().height)
    if (height > 0 && measured.current.get(key) !== height) {
      measured.current.set(key, height)
      forceRender()
    }
    if (ro && !observed.current.has(node)) {
      observed.current.set(node, key)
      ro.observe(node)
    }
  }, [])

  // 上报可见行（框架版在这里喂原生手势层；兜底版只透出给调用方）。
  const reported = React.useRef('')
  React.useEffect(() => {
    if (!onVisibleRowsChange) return
    const rows = []
    for (let i = start; i < end; i += 1) {
      const key = keyOf.current(list[i], i)
      rows.push({ id: key, index: i, top: offsets[i], height: measured.current.get(key) || estimate })
    }
    const signature = `${start}-${end}-${count}`
    if (signature === reported.current) return
    reported.current = signature
    onVisibleRowsChange(rows)
  }, [start, end, count, list, offsets, estimate, onVisibleRowsChange])

  // 自己是滚动容器时才挂 ref / onScroll；否则监听已经挂在外层（见上面的 effect）。
  const shellProps = scrollParentRef
    ? { className, style }
    : { ref: ownRef, className, style, onScroll: onScrollEvent }

  if (count === 0 && empty) {
    return (
      <div {...shellProps}>
        {header}
        {empty}
        {footer}
      </div>
    )
  }

  const slice = []
  for (let i = start; i < end; i += 1) {
    const key = keyOf.current(list[i], i)
    slice.push(
      <div
        key={key}
        ref={attachRow(key)}
        style={{ position: 'absolute', top: offsets[i], left: 0, right: 0, ...rowStyle }}
      >
        {renderRow(list[i], i)}
      </div>,
    )
  }

  return (
    <div {...shellProps}>
      {header}
      <div ref={regionRef} style={{ position: 'relative', height: total }}>{slice}</div>
      {footer}
    </div>
  )
}

export default VirtualList

// 行情页（自选）—— 规格 §2。
//
// 三处刻意的视觉细节，别"顺手统一"：
//  · 自选行的**现价是中性 ink 色**，只有涨跌幅 pill 带 13% 半透明底（§15 第 2 条）；
//  · 涨跌幅为 0 用**中性灰**，不是红也不是绿（§15 第 3 条）；
//  · 页脚时间戳带**日期 + 时区缩写**，避免把昨天的快照当今天。

import React from 'react'
import Icon from './Icon.jsx'
import { VirtualList } from './VirtualList.jsx'
import {
  Chip, ChipRow, EmptyState, Menu, PullRefresh, Spinner, SwipeRow,
} from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import { formatPercent, formatPrice, formatPriceFor, formatStamp, trendColor, trendTint } from '../lib/format.js'
import { INDEX_ROWS, decimalsFor, resolveSymbol } from '../lib/symbol.js'
import { quoteTTL, resolveDataState, showsCachedBadge } from '../lib/quotes.js'
import { groupLabel } from '../i18n/index.js'

const SORTS = ['manual', 'changeDescending', 'changeAscending']

/** 指数卡：宽 104、padding 12、surface 底、圆角 16。无数据时点位显 `—`、涨跌幅留空。 */
function IndexCard({ row, quote, t, upIsRed, onOpen }) {
  return (
    <button
      type="button"
      className="fin-btn fin-press"
      onClick={() => onOpen(row.canonical)}
      style={{
        width: 104, flex: '0 0 auto', padding: SPACE.s3, background: C.surface,
        borderRadius: RADIUS.card, display: 'flex', flexDirection: 'column', gap: 3,
      }}
    >
      <span className="fin-clamp-1" style={{ fontSize: 12, color: C.muted }}>{t(row.key)}</span>
      <span className="fin-mono" style={{ fontSize: 17, fontWeight: 500, color: C.ink }}>
        {quote ? formatPrice(quote.price, 2) : '—'}
      </span>
      <span className="fin-mono" style={{ fontSize: 12, color: quote ? trendColor(quote.changePct, upIsRed) : 'transparent' }}>
        {quote ? formatPercent(quote.changePct) : ' '}
      </span>
    </button>
  )
}

/** 自选行。现价中性、pill 半透明。 */
function WatchRow({ canonical, name, quote, upIsRed, onOpen }) {
  const symbol = resolveSymbol(canonical)
  const decimals = symbol ? decimalsFor(symbol.market) : 2
  return (
    <button
      type="button"
      className="fin-btn fin-press"
      onClick={() => onOpen(canonical)}
      style={{
        display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%',
        padding: `6px ${SPACE.s4}px`, minHeight: 52, background: C.bg,
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0, flex: '1 1 auto' }}>
        <span className="fin-clamp-1" style={{ fontSize: 16, fontWeight: 500, color: C.ink }}>{name}</span>
        <span className="fin-mono" style={{ fontSize: 12, color: C.muted }}>{canonical}</span>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 4, flex: '0 0 auto' }}>
        <span className="fin-mono" style={{ fontSize: 16, fontWeight: 500, color: C.ink }}>
          {quote ? formatPrice(quote.price, decimals) : '—'}
        </span>
        <span
          className="fin-mono"
          style={{
            fontSize: 13, fontWeight: 500, color: C.ink,
            padding: '2px 7px', minWidth: 66, textAlign: 'center', borderRadius: 6,
            background: trendTint(quote ? quote.changePct : null, upIsRed),
          }}
        >
          {quote ? formatPercent(quote.changePct) : '—'}
        </span>
      </div>
    </button>
  )
}

/** 页脚「更新于…」。三行互斥语义见 §2.6。 */
function Footer({ ctx, state }) {
  const { t, locale, quotes } = ctx
  const cached = showsCachedBadge(state)
  const stamp = quotes.lastUpdated ? formatStamp(quotes.lastUpdated, locale) : null
  const sourceLabel = quotes.source === 'automatic' ? t('finance.settings.sourceAuto')
    : quotes.source === 'sina' ? 'Sina' : 'Tencent'

  return (
    <div style={{
      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5,
      padding: `${SPACE.s5}px ${SPACE.s4}px ${SPACE.s6}px`, fontSize: 12, color: C.muted, textAlign: 'center',
    }}
    >
      <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        {ctx.refreshing ? <Spinner size={12} color={C.muted} /> : null}
        {stamp ? (cached ? t('finance.updated.cached', stamp) : t('finance.updated', stamp)) : null}
      </span>
      <span>{t('finance.watch.source', sourceLabel)}</span>
      {state === 'partial' ? (
        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <Icon name="exclamationmark.triangle" size={11} />
          {t('finance.quote.partial')}
        </span>
      ) : state === 'failedWithoutData' ? (
        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <Icon name="wifi.exclamationmark" size={11} />
          {t('finance.quote.failed')}
        </span>
      ) : state === 'failedWithCache' ? (
        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <Icon name="wifi.exclamationmark" size={11} />
          {t('finance.quote.stale')}
        </span>
      ) : null}
    </div>
  )
}

export default function WatchlistPage({ ctx }) {
  const { t, store, quotes, settings, actions } = ctx
  const scrollRef = React.useRef(null)
  const [group, setGroup] = React.useState(null)          // null = 全部
  const [sort, setSort] = React.useState('manual')

  // 分组被删时选中态自动回落到「全部」。
  React.useEffect(() => {
    if (group && !store.groups.some((row) => row.id === group)) setGroup(null)
  }, [group, store.groups, store.version])

  const visibleGroups = React.useMemo(() => {
    const withItems = store.groups
      .filter((row) => store.items.some((item) => item.groupID === row.id))
      .sort((a, b) => a.sortOrder - b.sortOrder)
    return group ? withItems.filter((row) => row.id === group) : withItems
  }, [store.groups, store.items, store.version, group]) // eslint-disable-line react-hooks/exhaustive-deps

  /** 非手动排序：按 changePct 降/升；**有行情的一律排在无行情之前**；都无行情按 sortOrder。 */
  const sortRows = React.useCallback((rows) => {
    if (sort === 'manual') return rows.slice().sort((a, b) => a.sortOrder - b.sortOrder)
    const descending = sort === 'changeDescending'
    return rows.slice().sort((a, b) => {
      const qa = quotes.quote(a.instrumentSymbol)
      const qb = quotes.quote(b.instrumentSymbol)
      if (!qa && !qb) return a.sortOrder - b.sortOrder
      if (!qa) return 1
      if (!qb) return -1
      return descending ? qb.changePct - qa.changePct : qa.changePct - qb.changePct
    })
  }, [sort, quotes, ctx.quoteVersion]) // eslint-disable-line react-hooks/exhaustive-deps

  // 扁平化成 VirtualList 的行（分组头也是一行，让长自选也能虚拟滚动）。
  const rows = React.useMemo(() => {
    const out = []
    for (const groupRow of visibleGroups) {
      const items = sortRows(store.items.filter((item) => item.groupID === groupRow.id))
      if (items.length === 0) continue
      out.push({ kind: 'header', id: `h-${groupRow.id}`, label: groupLabel(t, groupRow.name) })
      for (const item of items) out.push({ kind: 'item', id: item.id, item })
    }
    // 没有分组归属的孤儿项也要显示，否则用户会觉得自选丢了。
    const orphans = sortRows(store.items.filter(
      (item) => !store.groups.some((row) => row.id === item.groupID),
    ))
    if (orphans.length > 0 && !group) {
      for (const item of orphans) out.push({ kind: 'item', id: item.id, item })
    }
    return out
  }, [visibleGroups, store.items, store.groups, store.version, sortRows, group, t]) // eslint-disable-line react-hooks/exhaustive-deps

  const dataState = resolveDataState({
    failed: quotes.lastFailed,
    lastUpdated: quotes.lastUpdated,
    refreshing: ctx.refreshing,
    missingCount: quotes.missingSymbols.length,
    ttlMs: quoteTTL(settings.refreshInterval),
    now: Date.now(),
  })

  const header = (
    <>
      <ChipRow style={{ paddingTop: SPACE.s1, paddingBottom: SPACE.s2 }}>
        {INDEX_ROWS.map((row) => (
          <IndexCard
            key={row.canonical}
            row={row}
            quote={quotes.quote(row.canonical)}
            t={t}
            upIsRed={settings.upIsRed}
            onOpen={actions.openDetail}
          />
        ))}
      </ChipRow>
      {store.groups.length > 0 ? (
        <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, paddingBottom: SPACE.s2 }}>
          <ChipRow style={{ flex: '1 1 auto', minWidth: 0, paddingRight: 0 }}>
            <Chip
              variant="plain"
              label={t('finance.watch.group.all')}
              selected={group === null}
              onClick={() => setGroup(null)}
            />
            {store.groups.slice().sort((a, b) => a.sortOrder - b.sortOrder).map((row) => (
              <Chip
                key={row.id}
                variant="plain"
                label={groupLabel(t, row.name)}
                selected={group === row.id}
                onClick={() => setGroup(row.id)}
              />
            ))}
          </ChipRow>
          {/* 原生把排序放在导航栏 `ellipsis.circle` 菜单里；宿主 toolbar 的 trailing 已被
              ✨/搜索占满（上限 3 项且身份静态），所以这里就近放在分组条右端。 */}
          <div style={{ flex: '0 0 auto', paddingRight: SPACE.s4 }}>
            <Menu
              icon="ellipsis.circle"
              label=""
              trailing={null}
              value={sort}
              items={SORTS.map((id) => ({ id, label: t(`finance.watch.sort.${id}`) }))}
              onSelect={setSort}
              align="right"
            />
          </div>
        </div>
      ) : null}
    </>
  )

  const empty = (
    <EmptyState
      icon="star"
      text={t('finance.watch.empty')}
      actionLabel={t('finance.watch.add')}
      onAction={actions.openSearch}
    />
  )

  return (
    <PullRefresh
      scrollRef={scrollRef}
      refreshing={ctx.refreshing}
      onRefresh={() => actions.refresh(true)}
      style={{ display: 'flex', flexDirection: 'column' }}
    >
      <VirtualList
        items={rows}
        estimatedRowHeight={52}
        restoreKey="watchlist"
        scrollParentRef={scrollRef}
        header={header}
        footer={(quotes.lastUpdated || ctx.refreshing || quotes.lastFailed)
          ? <Footer ctx={ctx} state={dataState} /> : <div style={{ height: SPACE.s6 }} />}
        empty={rows.length === 0 ? empty : null}
        renderRow={(row) => {
          if (row.kind === 'header') {
            return (
              <div style={{ padding: `${SPACE.s3}px ${SPACE.s4}px 4px`, fontSize: 13, color: C.muted }}>
                {row.label}
              </div>
            )
          }
          const canonical = row.item.instrumentSymbol
          return (
            <SwipeRow actionLabel={t('finance.delete')} onAction={() => actions.removeWatch(canonical)}>
              <WatchRow
                canonical={canonical}
                name={store.instrumentName(canonical)}
                quote={quotes.quote(canonical)}
                upIsRed={settings.upIsRed}
                onOpen={actions.openDetail}
              />
            </SwipeRow>
          )
        }}
      />
    </PullRefresh>
  )
}

// 语言：跟随宿主有效 UI 语言（documentStart 就写好的 `window.__aiboxEnvironment`），
// 并监听 `environment.localeChanged` 重渲染（不重载 WebView）。

import { STRINGS } from './strings.js'

export function normalizeLocale(locale) {
  const raw = String(locale || 'en').toLowerCase()
  return raw.startsWith('zh') ? 'zh-Hans' : 'en'
}

export function currentLocale() {
  const env = typeof window !== 'undefined' ? window.__aiboxEnvironment : null
  return normalizeLocale(env && (env.locale || env.language))
}

export function onLocaleChanged(handler) {
  const bus = typeof window !== 'undefined' && window.aibox && window.aibox.events
  if (!bus || typeof bus.on !== 'function') return () => {}
  return bus.on('environment.localeChanged', (payload) => {
    handler(normalizeLocale(payload && (payload.locale || payload.language)))
  })
}

export function translate(locale, key) {
  const table = STRINGS[locale] || STRINGS.en
  if (table[key] !== undefined) return table[key]
  if (STRINGS.en[key] !== undefined) return STRINGS.en[key]
  return key
}

/** 位置占位符：fmt('更新于 {0}', '15:04')。 */
export function fmt(template, ...args) {
  return String(template).replace(/\{(\d+)\}/g, (whole, index) => {
    const value = args[Number(index)]
    return value === undefined || value === null ? whole : String(value)
  })
}

export function makeT(locale) {
  return (key, ...args) => {
    const value = translate(locale, key)
    return args.length > 0 ? fmt(value, ...args) : value
  }
}

export function bcp47(locale) {
  return locale === 'zh-Hans' ? 'zh-CN' : 'en-US'
}

/**
 * 分组名解析：以 `group.` 开头（或等于 `finance.watch.group.all`）→ 走本地化；
 * 否则原样显示（用户自建名）。
 */
export function groupLabel(t, name) {
  if (!name) return ''
  if (name === 'finance.watch.group.all' || name.startsWith('group.')) return t(name)
  return name
}

/** 账户名同理：种子账户名是键，用户改过的是字面量。 */
export function accountLabel(t, name) {
  if (name === 'account.default.name') return t(name)
  return name
}

// 文案表（规格 §12，逐字取自原生 `FinancePluginKit/Resources/Localizable.xcstrings`）。
// 键名保持与原生一致，便于两边对照与后续差分。
//
// 注意：**大数字缩写「万/亿」不在这里**——它在 lib/format.js 里对中英文一视同仁（原生标了 i18n:ignore）。

import { ZH } from './strings.zh.js'
import { EN } from './strings.en.js'

export const STRINGS = { 'zh-Hans': ZH, en: EN }

// 到价提醒（规格 §9.3 FinPriceAlert + §14.2）。
//
// **诚实降级**：容器有 `aibox.notifications.schedule`，但**没有后台唤醒**。
// 所以照原生的做法——**前台刷新时检查并推送**，UI 文案如实说明「App 活跃时生效」，
// 不假装能后台盯盘。触发判定 `shouldFire` 是纯函数，容器日后补了后台能力可直接复用。

import { storage } from './host.js'
import { KEYS, newID } from './store.js'

/** 命中后 4 小时冷却，防同一条提醒反复推。 */
export const COOLDOWN_MS = 4 * 3600 * 1000

export const CONDITIONS = ['above', 'below', 'up_pct', 'down_pct']

export function isPercentCondition(condition) {
  return condition === 'up_pct' || condition === 'down_pct'
}

export function isUpwardCondition(condition) {
  return condition === 'above' || condition === 'up_pct'
}

/**
 * 纯判定：给一条提醒与一份行情，判断此刻是否该推。
 * 百分比档比的是 `changePct`，价格档比的是 `price`。
 */
export function shouldFire(alert, quote, now) {
  if (!alert || !alert.enabled || !quote) return false
  if (alert.lastFiredAt && (now - alert.lastFiredAt) < COOLDOWN_MS) return false
  const target = Number(alert.targetPrice)
  if (!Number.isFinite(target)) return false
  const value = isPercentCondition(alert.conditionRaw) ? Number(quote.changePct) : Number(quote.price)
  if (!Number.isFinite(value)) return false
  return isUpwardCondition(alert.conditionRaw) ? value >= target : value <= target
}

export class AlertStore {
  constructor(store) {
    this.store = store
  }

  all() {
    return this.store.alerts
  }

  forSymbol(canonical) {
    return this.store.alerts.filter((row) => row.instrumentSymbol === canonical)
  }

  async persist() {
    const ok = await storage.set(KEYS.alerts, this.store.alerts)
    this.store.storageHealthy = ok
    this.store.bump()
    return ok
  }

  /**
   * 去重规则（§9.3）：同 symbol + 同 condition 已存在 → 改阈值/备注 + 重新启用 +
   * **清空 `lastFiredAt`**（让新阈值能再次触发），不新建。
   */
  async set({ symbol, name, condition, targetPrice, note }) {
    if (!CONDITIONS.includes(condition)) return { ok: false, error: 'invalidCondition' }
    if (!Number.isFinite(targetPrice)) return { ok: false, error: 'invalidTarget' }
    const existing = this.store.alerts.find(
      (row) => row.instrumentSymbol === symbol && row.conditionRaw === condition,
    )
    if (existing) {
      this.store.alerts = this.store.alerts.map((row) => (row === existing ? {
        ...row, targetPrice, note: note || '', enabled: true, lastFiredAt: null,
      } : row))
    } else {
      this.store.alerts = [...this.store.alerts, {
        id: newID('al'),
        instrumentSymbol: symbol,
        name: name || symbol,
        conditionRaw: condition,
        targetPrice,
        enabled: true,
        note: note || '',
        createdAt: Date.now(),
        lastFiredAt: null,
      }]
    }
    const ok = await this.persist()
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  async remove(id) {
    this.store.alerts = this.store.alerts.filter((row) => row.id !== id)
    const ok = await this.persist()
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  async setEnabled(id, enabled) {
    this.store.alerts = this.store.alerts.map((row) => (row.id === id ? { ...row, enabled } : row))
    const ok = await this.persist()
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  /**
   * 每轮刷新后调用：找出命中的提醒，标记 lastFiredAt 并返回待推送列表。
   * **不在这里发通知**——发送交给调用方（页面），便于在没有通知权限时降级成 App 内提示条。
   */
  async check(quotes, now = Date.now()) {
    const fired = []
    let changed = false
    this.store.alerts = this.store.alerts.map((row) => {
      const quote = quotes ? quotes[row.instrumentSymbol] : null
      if (!shouldFire(row, quote, now)) return row
      fired.push({ alert: row, quote })
      changed = true
      return { ...row, lastFiredAt: now }
    })
    if (changed) await this.persist()
    return fired
  }
}

// 数字 / 涨跌 / 货币格式（规格 §11）。
//
// 两条刻意的反直觉规则，别"修"：
//  · **大数字缩写在英文界面也是「万/亿」**，不会变 K/M/B（原生源码显式标了 i18n:ignore）；
//  · **涨跌幅为 0 用中性灰**，不是红也不是绿。

import { decimalsFor } from './symbol.js'

export const CURRENCY_SYMBOL = {
  CNY: '¥', RMB: '¥', HKD: 'HK$', USD: '$', EUR: '€', GBP: '£', JPY: 'JP¥',
}

export function currencySymbol(code) {
  return CURRENCY_SYMBOL[code] || `${code} `
}

/** 价格：`%.{d}f`，d 钳到 0..4，**无千分位**。 */
export function formatPrice(value, decimals = 2) {
  if (value === null || value === undefined || !Number.isFinite(value)) return '—'
  const digits = Math.max(0, Math.min(4, decimals))
  return value.toFixed(digits)
}

export function formatPriceFor(value, market) {
  return formatPrice(value, decimalsFor(market))
}

/** 涨跌额：价格格式 + 正数补 `+`。 */
export function formatChange(value, decimals = 2) {
  if (value === null || value === undefined || !Number.isFinite(value)) return '—'
  const text = formatPrice(Math.abs(value), decimals)
  if (value > 0) return `+${text}`
  if (value < 0) return `-${text}`
  return text
}

/** 百分比：signed 且 > 0 时补 `+`；固定 2 位。 */
export function formatPercent(value, signed = true) {
  if (value === null || value === undefined || !Number.isFinite(value)) return '—'
  const sign = signed && value > 0 ? '+' : ''
  return `${sign}${value.toFixed(2)}%`
}

/** 份额：整数 `%.0f`；含小数 `%.4f` 去尾零去尾点。 */
export function formatQuantity(value) {
  if (!Number.isFinite(value)) return '—'
  if (Number.isInteger(value)) return value.toFixed(0)
  return value.toFixed(4).replace(/0+$/, '').replace(/\.$/, '')
}

/** 大数字缩写：|v| ≥ 1e8 → `%.2f亿`；≥ 1e4 → `%.2f万`；否则 `%.0f`。中英文都是「万/亿」。 */
export function formatCompact(value) {
  if (!Number.isFinite(value)) return '—'
  const abs = Math.abs(value)
  if (abs >= 1e8) return `${(value / 1e8).toFixed(2)}亿`
  if (abs >= 1e4) return `${(value / 1e4).toFixed(2)}万`
  return value.toFixed(0)
}

/** 带货币符号的大数字（compactCNY 的通用形态）。 */
export function formatCompactCurrency(value, currency = 'CNY') {
  if (!Number.isFinite(value)) return '—'
  const sign = value < 0 ? '-' : ''
  return `${sign}${currencySymbol(currency)}${formatCompact(Math.abs(value))}`
}

/** 千分位只加在整数部分，小数部分原样。 */
export function groupInteger(text) {
  const [whole, fraction] = String(text).split('.')
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return fraction === undefined ? grouped : `${grouped}.${fraction}`
}

/** 金额（分）：`符号 + 货币符号 + 千分位("%.2f" of 绝对值)`。 */
export function formatMinor(minor, currency = 'CNY', { signed = false } = {}) {
  const value = (Number(minor) || 0) / 100
  const sign = value < 0 ? '-' : (signed && value > 0 ? '+' : '')
  return `${sign}${currencySymbol(currency)}${groupInteger(Math.abs(value).toFixed(2))}`
}

/** 成交量 → 手（÷100）。五档盘口与新浪 A 股成交量都用它。 */
export function toLots(volume) {
  if (!Number.isFinite(volume)) return '—'
  return formatCompact(volume / 100)
}

// —— 涨跌语义 ——

export const UP_RED = { up: '#E64340', down: '#0FA968' }
export const UP_RED_DARK = { up: '#FF5B57', down: '#30D158' }

/**
 * 涨跌色。`upIsRed` 默认 true（红涨绿跌）；**changePct === 0 一律返回 null**
 * ——调用方据此落到中性 muted 灰。
 */
export function trendKey(value) {
  if (value === null || value === undefined || !Number.isFinite(value) || value === 0) return 'flat'
  return value > 0 ? 'up' : 'down'
}

export function trendColor(value, upIsRed = true) {
  const key = trendKey(value)
  if (key === 'flat') return 'var(--fin-muted)'
  const rising = key === 'up'
  return (rising === upIsRed) ? 'var(--fin-red)' : 'var(--fin-green)'
}

/** 半透明底（自选行的涨跌 pill 用 13%）。 */
export function trendTint(value, upIsRed = true, alpha = 0.13) {
  const key = trendKey(value)
  if (key === 'flat') return `color-mix(in srgb, var(--fin-muted) ${alpha * 100}%, transparent)`
  const rising = key === 'up'
  const token = (rising === upIsRed) ? 'var(--fin-red)' : 'var(--fin-green)'
  return `color-mix(in srgb, ${token} ${alpha * 100}%, transparent)`
}

// —— 时间 ——

/** 固定 `yyyy-MM-dd`，**不随界面语言变**（工具文本与端点参数都用它）。 */
export function isoDate(timestamp) {
  const date = new Date(timestamp)
  const pad = (value) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/** 上海时区的 yyyyMMdd（涨跌停池 date 参数专用）。 */
export function shanghaiYMD(timestamp) {
  const date = new Date(timestamp || Date.now())
  const shanghai = new Date(date.getTime() + (date.getTimezoneOffset() + 480) * 60000)
  const pad = (value) => String(value).padStart(2, '0')
  return `${shanghai.getFullYear()}${pad(shanghai.getMonth() + 1)}${pad(shanghai.getDate())}`
}

/**
 * 自选页页脚时间戳：**medium 日期 + short 时间 + 时区缩写**。
 * 刻意带日期与时区——避免把昨天的快照当今天看。
 */
export function formatStamp(timestamp, locale) {
  if (!timestamp) return '—'
  const tag = locale === 'zh-Hans' ? 'zh-CN' : 'en-US'
  try {
    const text = new Intl.DateTimeFormat(tag, {
      dateStyle: 'medium', timeStyle: 'short', timeZoneName: 'short',
    }).format(new Date(timestamp))
    return text
  } catch (error) {
    return new Date(timestamp).toISOString()
  }
}

/** 行业页页脚：当天 `HH:mm`，隔日 `MM-dd HH:mm`。 */
export function formatShortStamp(timestamp, now) {
  if (!timestamp) return '—'
  const date = new Date(timestamp)
  const today = new Date(now || Date.now())
  const pad = (value) => String(value).padStart(2, '0')
  const time = `${pad(date.getHours())}:${pad(date.getMinutes())}`
  const sameDay = date.getFullYear() === today.getFullYear()
    && date.getMonth() === today.getMonth()
    && date.getDate() === today.getDate()
  return sameDay ? time : `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${time}`
}

// 宿主桥的薄封装。三条纪律（与资讯包一致）：
//  1. 每个能力**先探测再使用**——宿主没装/没授权时 `window.aibox.<ns>` 根本不存在，
//     入口要整块不渲染，而不是留一个点了没反应的按钮；
//  2. 所有调用都不抛到 UI 层，失败回落成可判定的返回值；
//  3. 没有 aibox 时（普通浏览器预览、node 自测）退化成内存实现，页面仍能跑。

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

export function hasNamespace(name, method) {
  const api = bridge()
  if (!api || !api[name]) return false
  return method ? typeof api[name][method] === 'function' : true
}

export const capabilities = {
  get tabs() { return hasNamespace('tabs', 'getState') },
  get toolbar() { return hasNamespace('toolbar', 'on') },
  get net() { return hasNamespace('net', 'fetch') },
  get ai() { return hasNamespace('ai', 'generate') },
  get chat() { return hasNamespace('chat', 'open') },
  get notifications() { return hasNamespace('notifications', 'schedule') },
  get share() { return hasNamespace('share', 'file') },
  get action() { return hasNamespace('action', 'register') },
  get haptics() { return hasNamespace('haptics', 'impact') },
}

// —— storage（per-applet KV）——

const memoryStore = new Map()

export const storage = {
  async get(key) {
    const api = bridge()
    if (!api || !api.storage) return memoryStore.has(key) ? memoryStore.get(key) : null
    try {
      const value = await api.storage.get(key)
      return value === undefined ? null : value
    } catch (error) {
      return null
    }
  },
  async set(key, value) {
    const api = bridge()
    if (!api || !api.storage) { memoryStore.set(key, value); return true }
    try {
      await api.storage.set(key, value)
      return true
    } catch (error) {
      return false
    }
  },
  async remove(key) {
    const api = bridge()
    if (!api || !api.storage) { memoryStore.delete(key); return true }
    try {
      await api.storage.remove(key)
      return true
    } catch (error) {
      return false
    }
  },
}

// —— 事件总线 ——

export function onEvent(name, handler) {
  const api = bridge()
  if (!api || !api.events || typeof api.events.on !== 'function') return () => {}
  return api.events.on(name, handler)
}

export function onNamespaceEvent(namespace, event, handler) {
  const api = bridge()
  if (!api || !api[namespace] || typeof api[namespace].on !== 'function') return () => {}
  return api[namespace].on(event, handler)
}

// —— AI ——

export async function aiAvailability() {
  const api = bridge()
  if (!api || !api.ai || typeof api.ai.availability !== 'function') return { available: false }
  try {
    const info = await api.ai.availability()
    return info && typeof info === 'object' ? info : { available: false }
  } catch (error) {
    return { available: false }
  }
}

/** 降级路径：没有停靠会话时跳聊天页开一个带种子的会话（原生自己就有这条降级）。 */
export async function openChat({ prompt, categoryKey, autoSend = true, identity }) {
  const api = bridge()
  if (api && api.chat && typeof api.chat.open === 'function') {
    try {
      await api.chat.open({ prompt, categoryKey, autoSend, identity })
      return true
    } catch (error) { /* 落到 ai.generate */ }
  }
  return false
}

export async function aiGenerate(input) {
  const api = bridge()
  if (!api || !api.ai || typeof api.ai.generate !== 'function') throw new Error('aibox/ai-unavailable')
  return api.ai.generate(input)
}

// —— 本地通知（到价提醒）——
//
// 容器只有 `schedule`，**没有后台唤醒**——所以到价检查照原生做法放在「前台刷新时」，
// UI 文案如实说明「App 活跃时生效」，不假装能后台盯盘。

export async function scheduleNotification({ title, body, afterMinutes = 0 }) {
  const api = bridge()
  if (!api || !api.notifications || typeof api.notifications.schedule !== 'function') return false
  try {
    await api.notifications.schedule({ title, body, afterMinutes })
    return true
  } catch (error) {
    return false
  }
}

// —— 文件导出（账户归档）——

export async function shareFile({ filename, content, mimeType }) {
  const api = bridge()
  if (!api || !api.share || typeof api.share.file !== 'function') return false
  try {
    await api.share.file({ filename, content, mimeType })
    return true
  } catch (error) {
    return false
  }
}

export function impact(style = 'light') {
  const api = bridge()
  if (api && api.haptics && typeof api.haptics.impact === 'function') {
    try { api.haptics.impact({ style }) } catch (error) { /* 触觉是锦上添花 */ }
  }
}

/** 注册一个可被 AI / 自动化调用的 action（manifest.actions 里已静态声明的那些）。 */
export function registerAction(name, handler) {
  const api = bridge()
  if (!api || !api.action || typeof api.action.register !== 'function') return false
  try {
    api.action.register(name, handler)
    return true
  } catch (error) {
    return false
  }
}

// HTTP 层：`aibox.net.fetch` 的薄封装 + GBK/GB18030 解码 + 同 key 并发合并。
//
// **为什么必须走 base64**：腾讯 / 新浪的行情响应是 GBK。`responseType:'text'` 会按 UTF-8 解，
// 失败时返回**空字符串**（不是乱码，是什么都没有）——所以 GBK 端点一律 `responseType:'base64'`
// 再在 Web 侧用 `TextDecoder('gb18030')` 解，合同见
// docs/capabilities/applet/framework-capabilities.md §3.35。
//
// 请求头是能透传的（这是「网络必须经原生中转」的红利：浏览器 fetch 设不了 Referer）。
// 所有失败一律回落成可判定的返回值，**不抛到 UI 层**（规格 §8.9）。

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

export const FAILURE = {
  configuration: 'configuration',
  invalidURL: 'invalidURL',
  timeout: 'timeout',
  network: 'network',
  http: 'http',
  decoding: 'decoding',
  unknown: 'unknown',
}

export const DEFAULT_TIMEOUT_MS = 8000
export const CATALOG_TIMEOUT_MS = 12000
const USER_AGENT = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15'

function classify(message) {
  const text = String(message || '').toLowerCase()
  if (text.includes('aibox/denied')) return FAILURE.configuration
  if (text.includes('timed out') || text.includes('timeout')) return FAILURE.timeout
  if (text.includes('invalid') || text.includes('non-http')) return FAILURE.invalidURL
  if (text.includes('offline') || text.includes('network') || text.includes('connection')
      || text.includes('host') || text.includes('internet')) return FAILURE.network
  return FAILURE.unknown
}

/**
 * 基础请求。`responseType` 默认 `'text'`；GBK 端点传 `'base64'`。
 * 返回 `{ ok, status, body, contentType, truncated, failure }`。
 */
export async function request(url, options = {}) {
  const api = bridge()
  if (!api || !api.net || typeof api.net.fetch !== 'function') {
    return { ok: false, failure: FAILURE.configuration }
  }
  if (!/^https?:\/\//i.test(String(url || ''))) {
    return { ok: false, failure: FAILURE.invalidURL }
  }
  const {
    headers = {}, responseType = 'text', maxBytes, timeoutMs = DEFAULT_TIMEOUT_MS, method = 'GET', body,
  } = options

  let timer = null
  const timeout = new Promise((resolve) => {
    timer = setTimeout(() => resolve({ __timeout: true }), timeoutMs)
  })
  try {
    const payload = { method, headers: { 'User-Agent': USER_AGENT, ...headers }, responseType }
    if (maxBytes) payload.maxBytes = maxBytes
    if (body !== undefined) payload.body = body
    const response = await Promise.race([api.net.fetch(url, payload), timeout])
    if (response && response.__timeout) return { ok: false, failure: FAILURE.timeout }
    const status = Number((response && response.status) || 0)
    if (status < 200 || status >= 300) return { ok: false, failure: FAILURE.http, status }
    return {
      ok: true,
      status,
      body: response ? response.body : null,
      contentType: response ? response.contentType : null,
      truncated: !!(response && response.truncated),
    }
  } catch (error) {
    return { ok: false, failure: classify(error && error.message) }
  } finally {
    if (timer) clearTimeout(timer)
  }
}

/** UTF-8 文本端点（东财 datacenter / 天天基金 / 新浪快讯）。 */
export async function getText(url, options = {}) {
  const result = await request(url, { ...options, responseType: 'text' })
  if (!result.ok) return result
  return { ...result, body: String(result.body || '') }
}

/** JSON 端点。解析失败按 decoding 失败回报，不抛。 */
export async function getJSON(url, options = {}) {
  const result = await request(url, { ...options, responseType: 'json' })
  if (!result.ok) return result
  if (result.body && typeof result.body === 'object') return result
  try {
    return { ...result, body: JSON.parse(String(result.body || '')) }
  } catch (error) {
    return { ok: false, failure: FAILURE.decoding }
  }
}

/**
 * GBK/GB18030 端点（腾讯行情、腾讯联想、新浪行情、新浪汇率）。
 * 必须走 base64 —— 见文件头注释。
 */
export async function getGBK(url, options = {}) {
  const result = await request(url, {
    ...options,
    responseType: 'base64',
    maxBytes: options.maxBytes || 4 * 1024 * 1024,
  })
  if (!result.ok) return result
  const text = decodeGBK(result.body)
  if (text === null) return { ok: false, failure: FAILURE.decoding }
  return { ...result, body: text }
}

/** base64 → GB18030 文本。解不出来返回 null（调用方按失败处理，不伪造数据）。 */
export function decodeGBK(base64) {
  try {
    const binary = atob(String(base64 || ''))
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
    return new TextDecoder('gb18030').decode(bytes)
  } catch (error) {
    return null
  }
}

// —— 同 key 并发合并（规格 §8.8）——
//
// 同一批代码在两个页面同时刷新时，key 相同的请求共享同一次网络调用。
// 这不是缓存，是**去重**：TTL 缓存在 quotes.js 里，这里只防「同一瞬间打两次」。

const inflight = new Map()

export function coalesce(key, factory) {
  if (inflight.has(key)) return inflight.get(key)
  const promise = Promise.resolve()
    .then(factory)
    .finally(() => { inflight.delete(key) })
  inflight.set(key, promise)
  return promise
}

/** 固定并发窗口跑一批任务（基金估值固定 4）。 */
export async function runPool(items, width, worker) {
  const out = new Array(items.length)
  let cursor = 0
  const runners = new Array(Math.max(1, Math.min(width, items.length))).fill(0).map(async () => {
    for (;;) {
      const index = cursor
      cursor += 1
      if (index >= items.length) return
      out[index] = await worker(items[index], index)
    }
  })
  await Promise.all(runners)
  return out
}

/** JSON 式 `\uXXXX` 反转义（腾讯联想的名称字段必须过这一道，否则中文全乱）。 */
export function unescapeUnicode(text) {
  return String(text || '').replace(/\\u([0-9a-fA-F]{4})/g, (whole, hex) => String.fromCharCode(parseInt(hex, 16)))
}

/** 缺失值：东财 clist 用字符串 `"-"` 表示无数据，要当 0 / 空串。 */
export function num(value, fallback = 0) {
  if (value === null || value === undefined || value === '-' || value === '') return fallback
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : fallback
}

export function str(value, fallback = '') {
  if (value === null || value === undefined || value === '-') return fallback
  return String(value)
}

// 技术指标（规格 §7.3，对齐原生 `FinIndicators`）。纯本地计算，零网络。
//
// 三条容易写错、这里逐字照抄原生的口径：
//  · MACD 的 hist **乘 2**（DIF−DEA 的 2 倍，不是 1 倍）；
//  · KDJ 的 Ln 只在「low > 0」的样本里取 min（脏数据里 low=0 会把 RSV 拉成 100）；
//  · BOLL 的标准差是**总体**标准差（除以 n），不是样本（n−1）。
//    ——而绩效那边的年化波动率也是除以 n，回测那边却是除以 n−1，两处刻意不同，别统一。

/** 简单均线；暖机期（i < n−1）输出 null。 */
export function sma(values, period) {
  const out = new Array(values.length).fill(null)
  if (period <= 0) return out
  let sum = 0
  for (let i = 0; i < values.length; i += 1) {
    sum += values[i]
    if (i >= period) sum -= values[i - period]
    if (i >= period - 1) out[i] = sum / period
  }
  return out
}

/** EMA：k = 2/(n+1)，out[0] = v[0]，全长无 null。 */
export function ema(values, period) {
  const out = new Array(values.length).fill(null)
  if (values.length === 0 || period <= 0) return out
  const k = 2 / (period + 1)
  out[0] = values[0]
  for (let i = 1; i < values.length; i += 1) {
    out[i] = values[i] * k + out[i - 1] * (1 - k)
  }
  return out
}

/** MACD(12,26,9)：DIF = EMA12 − EMA26；DEA = EMA(DIF,9)；hist = (DIF − DEA) × 2。 */
export function macd(values, fast = 12, slow = 26, signal = 9) {
  const fastLine = ema(values, fast)
  const slowLine = ema(values, slow)
  const dif = values.map((_, i) => fastLine[i] - slowLine[i])
  const dea = ema(dif, signal)
  const hist = dif.map((value, i) => (value - dea[i]) * 2)
  return { dif, dea, hist }
}

/**
 * KDJ(9,3,3)。窗口是最近 9 根（开头处截断），prevK / prevD 初值都是 50。
 * Hn 用窗口最高价 max；Ln 用窗口内 low > 0 的最低价 min（全为 0 时退化成 Hn，RSV 走 50 分支）。
 */
export function kdj(candles, period = 9) {
  const k = []
  const d = []
  const j = []
  let prevK = 50
  let prevD = 50
  for (let i = 0; i < candles.length; i += 1) {
    const from = Math.max(0, i - period + 1)
    let high = -Infinity
    let low = Infinity
    for (let n = from; n <= i; n += 1) {
      if (candles[n].high > high) high = candles[n].high
      if (candles[n].low > 0 && candles[n].low < low) low = candles[n].low
    }
    if (!Number.isFinite(low)) low = high
    const rsv = high > low ? ((candles[i].close - low) / (high - low)) * 100 : 50
    const currentK = (rsv + prevK * 2) / 3
    const currentD = (currentK + prevD * 2) / 3
    k.push(currentK)
    d.push(currentD)
    j.push(3 * currentK - 2 * currentD)
    prevK = currentK
    prevD = currentD
  }
  return { k, d, j }
}

/** BOLL(20,2)：mid = MA20；sd = 窗口**总体**标准差；upper/lower = mid ± 2sd。暖机期 null。 */
export function boll(values, period = 20, multiplier = 2) {
  const mid = sma(values, period)
  const upper = new Array(values.length).fill(null)
  const lower = new Array(values.length).fill(null)
  for (let i = 0; i < values.length; i += 1) {
    if (mid[i] === null) continue
    let variance = 0
    for (let n = i - period + 1; n <= i; n += 1) {
      const diff = values[n] - mid[i]
      variance += diff * diff
    }
    const sd = Math.sqrt(variance / period)
    upper[i] = mid[i] + multiplier * sd
    lower[i] = mid[i] - multiplier * sd
  }
  return { mid, upper, lower }
}

/** 总体标准差（除以 n）。绩效年化波动用它。 */
export function stdDevPopulation(values) {
  if (values.length === 0) return 0
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / values.length
  return Math.sqrt(variance)
}

/** 样本标准差（除以 n−1）。回测波动用它——与上面刻意不同口径。 */
export function stdDevSample(values) {
  if (values.length < 2) return 0
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (values.length - 1)
  return Math.sqrt(variance)
}

/** 最大回撤（%）：max over i of (peak_i − v_i)/peak_i × 100。 */
export function maxDrawdown(values) {
  let peak = -Infinity
  let worst = 0
  for (const value of values) {
    if (value > peak) peak = value
    if (peak > 0) {
      const drawdown = ((peak - value) / peak) * 100
      if (drawdown > worst) worst = drawdown
    }
  }
  return worst
}

/** 曲线降采样到 ≤ ~60 点（步长 n/60，末点补齐）。 */
export function downsample(points, target = 60) {
  if (points.length <= target) return points.slice()
  const step = Math.max(1, Math.floor(points.length / target))
  const out = []
  for (let i = 0; i < points.length; i += step) out.push(points[i])
  const last = points[points.length - 1]
  if (out[out.length - 1] !== last) out.push(last)
  return out
}

// 模拟账本（规格 §9.3 的 FinAccount / FinPosition / FinTradeOrder / FinCashFlow / FinAccountSnapshot）。
//
// **事务**：整本账（账户 + 持仓 + 成交 + 流水 + 快照）住在**同一个 KV key** 里。
// 一次买入/卖出/现金流是「用 portfolio.js 的纯函数算出新账本 → 一次 `storage.set`」，
// 所以余额变更与流水写入同生共死；写失败就整体回滚（内存状态也一并还原）。
//
// 清仓不删持仓行：quantity 归 0、累计已实现盈亏留档，再买入自动复活；
// 列表按 `quantity > 0` 过滤（§15 第 9 条）。

import { storage } from './host.js'
import { MoneyError } from './money.js'
import {
  allocation, applyBuy, applyCashFlow, applySell, diagnose, fxMapFor, fxRate, performance, valueAccount,
} from './portfolio.js'
import { snapshotFor, startOfDay } from './strategy.js'
import { newID } from './store.js'

export const LEDGER_KEY = 'finance.ledger.v1'

/** 首启种子 1 个账户：CNY，初始 100_000_000 分 = ¥1,000,000.00。 */
export function seedAccount() {
  return {
    id: newID('a'),
    name: 'account.default.name',
    currency: 'CNY',
    initialCashMinor: 100000000,
    cashMinor: 100000000,
    isRealCopy: false,
    note: '',
    colorHex: '34C759',
    sortOrder: 0,
    isArchived: false,
    createdAt: Date.now(),
  }
}

export class Ledger {
  constructor() {
    this.accounts = []
    this.positions = []
    this.orders = []
    this.cashFlows = []
    this.snapshots = []
    this.storageHealthy = true
    this.version = 0
    this.listeners = new Set()
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  bump() {
    this.version += 1
    for (const listener of this.listeners) listener()
  }

  async load() {
    const saved = await storage.get(LEDGER_KEY)
    if (saved && typeof saved === 'object' && Array.isArray(saved.accounts) && saved.accounts.length > 0) {
      this.accounts = saved.accounts
      this.positions = saved.positions || []
      this.orders = saved.orders || []
      this.cashFlows = saved.cashFlows || []
      this.snapshots = saved.snapshots || []
    } else {
      this.accounts = [seedAccount()]
      await this.commit(this.state())
    }
    this.bump()
  }

  state() {
    return {
      accounts: this.accounts,
      positions: this.positions,
      orders: this.orders,
      cashFlows: this.cashFlows,
      snapshots: this.snapshots,
    }
  }

  /** 原子提交：一次 KV 写入。失败时**不改内存状态**，调用方拿到 false 即整体回滚。 */
  async commit(next) {
    const ok = await storage.set(LEDGER_KEY, next)
    this.storageHealthy = ok
    if (!ok) { this.bump(); return false }
    this.accounts = next.accounts
    this.positions = next.positions
    this.orders = next.orders
    this.cashFlows = next.cashFlows
    this.snapshots = next.snapshots
    this.bump()
    return true
  }

  // —— 账户解析（§13.4 解析纪律：**绝不静默落主账户**）——

  /** 主账户 = 第一个未归档。 */
  primaryAccount() {
    return this.accounts.find((row) => !row.isArchived) || null
  }

  accountByID(id) {
    return this.accounts.find((row) => row.id === id) || null
  }

  /**
   * 层层放宽：精确名 → 币种词 → 模糊子串 → 币种收窄。
   * 对不上时返回 `{ ok:false, candidates }` 让调用方（AI）挑，**不静默落主账户**。
   */
  resolveAccount(query) {
    const active = this.accounts.filter((row) => !row.isArchived)
    if (active.length === 0) return { ok: false, error: 'noAccount', candidates: [] }
    const text = String(query || '').trim()
    if (!text) return { ok: true, account: this.primaryAccount() }

    const byID = active.find((row) => row.id === text)
    if (byID) return { ok: true, account: byID }
    const exact = active.filter((row) => row.name === text)
    if (exact.length === 1) return { ok: true, account: exact[0] }

    const lower = text.toLowerCase()
    const currency = CURRENCY_WORDS.find((row) => row.words.some((word) => lower.includes(word)))
    if (currency) {
      const matched = active.filter((row) => row.currency === currency.code)
      if (matched.length === 1) return { ok: true, account: matched[0] }
      if (matched.length > 1) {
        return { ok: false, error: 'ambiguous', candidates: matched.map(describeAccount) }
      }
    }

    const fuzzy = active.filter((row) => row.name.toLowerCase().includes(lower))
    if (fuzzy.length === 1) return { ok: true, account: fuzzy[0] }
    if (fuzzy.length > 1) return { ok: false, error: 'ambiguous', candidates: fuzzy.map(describeAccount) }
    return { ok: false, error: 'notFound', candidates: active.map(describeAccount) }
  }

  positionsOf(accountID) {
    return this.positions.filter((row) => row.accountID === accountID)
  }

  openPositionsOf(accountID) {
    return this.positionsOf(accountID).filter((row) => row.quantity > 0)
  }

  ordersOf(accountID, limit = 20) {
    return this.orders
      .filter((row) => row.accountID === accountID)
      .sort((a, b) => b.tradedAt - a.tradedAt)
      .slice(0, limit)
  }

  cashFlowsOf(accountID, limit) {
    const rows = this.cashFlows
      .filter((row) => row.accountID === accountID)
      .sort((a, b) => b.occurredAt - a.occurredAt)
    return limit ? rows.slice(0, limit) : rows
  }

  snapshotsOf(accountID) {
    return this.snapshots.filter((row) => row.accountID === accountID).sort((a, b) => a.date - b.date)
  }

  // —— 交易 ——

  async buy({ accountID, symbol, name, market, currency, quantity, price, fxRate: rate, feeMinor, note, source }) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    const account = this.accountByID(accountID)
    const position = this.positions.find((row) => row.accountID === accountID && row.instrumentSymbol === symbol) || null
    let result
    try {
      result = applyBuy({
        account, position, symbol, name, market, currency, quantity, price, fxRate: rate, feeMinor, note, source,
      })
    } catch (error) {
      return { ok: false, error: error instanceof MoneyError ? error.code : 'unknown', detail: error.detail }
    }
    const nextPosition = position
      ? { ...result.position }
      : { ...result.position, id: newID('p'), realizedPnlMinor: 0 }
    const next = {
      ...this.state(),
      accounts: this.accounts.map((row) => (row.id === accountID ? result.account : row)),
      positions: position
        ? this.positions.map((row) => (row.id === position.id ? nextPosition : row))
        : [...this.positions, nextPosition],
      orders: [...this.orders, { ...result.order, id: newID('o') }],
    }
    const ok = await this.commit(next)
    return ok ? { ok: true, order: result.order, debitMinor: result.debitMinor } : { ok: false, error: 'storageUnavailable' }
  }

  async sell({ accountID, symbol, quantity, price, fxRate: rate, feeMinor, note, source }) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    const account = this.accountByID(accountID)
    const position = this.positions.find((row) => row.accountID === accountID && row.instrumentSymbol === symbol) || null
    let result
    try {
      result = applySell({ account, position, quantity, price, fxRate: rate, feeMinor, note, source })
    } catch (error) {
      return { ok: false, error: error instanceof MoneyError ? error.code : 'unknown', detail: error.detail }
    }
    const next = {
      ...this.state(),
      accounts: this.accounts.map((row) => (row.id === accountID ? result.account : row)),
      positions: this.positions.map((row) => (row.id === position.id ? result.position : row)),
      orders: [...this.orders, { ...result.order, id: newID('o') }],
    }
    const ok = await this.commit(next)
    return ok
      ? { ok: true, order: result.order, proceedsMinor: result.proceedsMinor, realizedDeltaMinor: result.realizedDeltaMinor }
      : { ok: false, error: 'storageUnavailable' }
  }

  async addCashFlow({ accountID, kind, amountMinor, note, source }) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    const account = this.accountByID(accountID)
    let result
    try {
      result = applyCashFlow({ account, kind, amountMinor, note, source })
    } catch (error) {
      return { ok: false, error: error instanceof MoneyError ? error.code : 'unknown' }
    }
    const next = {
      ...this.state(),
      accounts: this.accounts.map((row) => (row.id === accountID ? result.account : row)),
      cashFlows: [...this.cashFlows, { ...result.flow, id: newID('c') }],
    }
    const ok = await this.commit(next)
    return ok ? { ok: true, flow: result.flow } : { ok: false, error: 'storageUnavailable' }
  }

  // —— 账户生命周期 ——

  async createAccount({ name, currency = 'CNY', initialCashMinor = 100000000, note = '', isRealCopy = false }) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    const account = {
      id: newID('a'),
      name: String(name || '').trim() || 'account.default.name',
      currency,
      initialCashMinor: Math.max(0, Math.trunc(initialCashMinor)),
      cashMinor: Math.max(0, Math.trunc(initialCashMinor)),
      isRealCopy,
      note,
      colorHex: '34C759',
      sortOrder: this.accounts.reduce((max, row) => Math.max(max, row.sortOrder), -1) + 1,
      isArchived: false,
      createdAt: Date.now(),
    }
    const ok = await this.commit({ ...this.state(), accounts: [...this.accounts, account] })
    return ok ? { ok: true, account } : { ok: false, error: 'storageUnavailable' }
  }

  async updateAccount(id, patch) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    const ok = await this.commit({
      ...this.state(),
      accounts: this.accounts.map((row) => (row.id === id ? { ...row, ...patch } : row)),
    })
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  /** 复制账户：只复制身份与初始资金，不复制持仓与成交（原生同）。 */
  async copyAccount(id, name) {
    const source = this.accountByID(id)
    if (!source) return { ok: false, error: 'notFound' }
    return this.createAccount({
      name: name || `${source.name} 2`,
      currency: source.currency,
      initialCashMinor: source.initialCashMinor,
      note: source.note,
      isRealCopy: source.isRealCopy,
    })
  }

  /** 重置：现金回初始，清空该账户的持仓/成交/流水/快照。 */
  async resetAccount(id) {
    const account = this.accountByID(id)
    if (!account) return { ok: false, error: 'notFound' }
    const ok = await this.commit({
      accounts: this.accounts.map((row) => (row.id === id ? { ...row, cashMinor: row.initialCashMinor } : row)),
      positions: this.positions.filter((row) => row.accountID !== id),
      orders: this.orders.filter((row) => row.accountID !== id),
      cashFlows: this.cashFlows.filter((row) => row.accountID !== id),
      snapshots: this.snapshots.filter((row) => row.accountID !== id),
    })
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  async deleteAccount(id) {
    if (this.accounts.length <= 1) return { ok: false, error: 'lastAccount' }
    const ok = await this.commit({
      accounts: this.accounts.filter((row) => row.id !== id),
      positions: this.positions.filter((row) => row.accountID !== id),
      orders: this.orders.filter((row) => row.accountID !== id),
      cashFlows: this.cashFlows.filter((row) => row.accountID !== id),
      snapshots: this.snapshots.filter((row) => row.accountID !== id),
    })
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  // —— 估值 / 绩效 / 快照 ——

  valuation(accountID, quotes, fxToCNY) {
    const account = this.accountByID(accountID)
    if (!account) return null
    return valueAccount({
      account,
      positions: this.positionsOf(accountID),
      quotes,
      fxToCNY,
      cashFlows: this.cashFlowsOf(accountID),
    })
  }

  performance(accountID) {
    return performance({ orders: this.orders.filter((row) => row.accountID === accountID), snapshots: this.snapshotsOf(accountID) })
  }

  allocation(valuation) {
    return allocation(valuation.rows)
  }

  diagnose(valuation, perf) {
    return diagnose({ valuation, perf })
  }

  fxRateFor(fromCurrency, accountCurrency, fxToCNY) {
    return fxRate(fromCurrency, accountCurrency, fxMapFor(accountCurrency, fxToCNY))
  }

  /** §10.7：**仅当估值完整才写**快照；按天归一，同日覆盖。 */
  async writeSnapshot(valuation, when) {
    const row = snapshotFor(valuation, when)
    if (!row) return { ok: false, error: 'incomplete' }
    const date = startOfDay(when || Date.now())
    const existing = this.snapshots.find((entry) => entry.accountID === row.accountID && entry.date === date)
    const next = existing
      ? this.snapshots.map((entry) => (entry === existing ? { ...row, id: existing.id } : entry))
      : [...this.snapshots, { ...row, id: newID('s') }]
    const ok = await this.commit({ ...this.state(), snapshots: next })
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  /** 账户归档 JSON（导出/导入用）。 */
  archiveFor(accountID) {
    const account = this.accountByID(accountID)
    if (!account) return null
    return {
      schema: 'finance.account.archive.v1',
      exportedAt: new Date().toISOString(),
      account,
      positions: this.positionsOf(accountID),
      orders: this.orders.filter((row) => row.accountID === accountID),
      cashFlows: this.cashFlows.filter((row) => row.accountID === accountID),
      snapshots: this.snapshotsOf(accountID),
    }
  }
}

const CURRENCY_WORDS = [
  { code: 'USD', words: ['美元', '美金', '美股', 'usd'] },
  { code: 'HKD', words: ['港币', '港元', '港股', 'hkd'] },
  { code: 'CNY', words: ['人民币', 'rmb', 'a股', '沪深', 'cny'] },
]

export function describeAccount(account) {
  return { id: account.id, name: account.name, currency: account.currency }
}

// 金额纪律（规格 §9 / §11）：**现金与盈亏一律 Int「分」**，份额与价格才是 Double。
// 浮点只允许出现在最终显示格式化里，任何账目运算都在整数分上做。
//
// JS 没有 Int64；Number.MAX_SAFE_INTEGER = 9007199254740991 分 ≈ 9 万亿元，
// 对模拟账户足够，但**必须显式钳制**——溢出静默变成不精确整数比报错更危险。

export const MAX_MINOR = Number.MAX_SAFE_INTEGER

export class MoneyError extends Error {
  constructor(code, detail) {
    super(code)
    this.code = code
    this.detail = detail || null
  }
}

export function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value)
}

/**
 * 二进制浮点噪声的归一：`0.145 * 100` 在 IEEE754 下是 `14.499999999999998`，
 * 直接舍入会得到 14 分，而原生走 Decimal 得到的是 15 分。先把小数尾巴削到 6 位再舍入，
 * 结果与 Decimal 一致，同时不影响任何量级正常的账目数字。
 */
function snap(value) {
  if (!Number.isFinite(value)) return value
  if (Math.abs(value) >= 1e15) return value       // 已超出小数有效位，toFixed 无意义
  return Number(value.toFixed(6))
}

/** 四舍五入**远离 0**（与原生 Decimal plain 舍入一致）；非有限值当 0。 */
export function roundHalfAway(value) {
  if (!isFiniteNumber(value)) return 0
  const normalized = snap(value)
  return normalized < 0 ? -Math.round(-normalized) : Math.round(normalized)
}

/** 元 → 分。非有限当 0，溢出钳制（不抛）。 */
export function toMinor(value) {
  if (!isFiniteNumber(value)) return 0
  const minor = roundHalfAway(value * 100)
  return clampMinor(minor)
}

/** 分 → 元（只用于显示与比率计算）。 */
export function toMajor(minor) {
  return (Number(minor) || 0) / 100
}

export function clampMinor(minor) {
  if (!Number.isFinite(minor)) return 0
  if (minor > MAX_MINOR) return MAX_MINOR
  if (minor < -MAX_MINOR) return -MAX_MINOR
  return Math.trunc(minor)
}

/** 加法：溢出即抛（账目路径宁可报错也不能默默算错）。 */
export function addMinor(a, b) {
  const sum = Number(a) + Number(b)
  if (!Number.isFinite(sum) || Math.abs(sum) > MAX_MINOR) throw new MoneyError('overflow')
  return Math.trunc(sum)
}

export function subMinor(a, b) {
  return addMinor(a, -Number(b))
}

/** 分 × 倍率（汇率等）→ 分，四舍五入远离 0；溢出即抛。 */
export function scaleMinor(minor, factor) {
  if (!isFiniteNumber(factor)) throw new MoneyError('invalidRate')
  const scaled = Number(minor) * factor
  if (!Number.isFinite(scaled) || Math.abs(scaled) > MAX_MINOR) throw new MoneyError('overflow')
  return roundHalfAway(scaled)
}

/**
 * 数量 × 价格 → 标的币「分」。规格 §10.1：`grossValue = quantity * price * 100`，
 * 必须有限且不越界，否则报错。
 */
export function grossMinorOf(quantity, price) {
  if (!isFiniteNumber(quantity) || quantity <= 0) throw new MoneyError('invalidQuantity')
  if (!isFiniteNumber(price) || price <= 0) throw new MoneyError('invalidPrice')
  const gross = quantity * price * 100
  if (!Number.isFinite(gross) || Math.abs(gross) > MAX_MINOR) throw new MoneyError('overflow')
  return roundHalfAway(gross)
}

/**
 * 宽松数字解析：locale 感知失败时剥掉分组符号、把小数点归一成 `.` 再 parse。
 * 用于所有用户输入的金额/数量/价格框。
 */
export function parseNumberInput(text) {
  const raw = String(text == null ? '' : text).trim()
  if (!raw) return null
  const direct = Number(raw)
  if (Number.isFinite(direct)) return direct
  const normalized = raw
    .replace(/[\s   ]/g, '')
    .replace(/[，,]/g, '')
    .replace(/[。．]/g, '.')
    .replace(/[^0-9.\-+]/g, '')
  // 剥完一个数字都不剩（"abc"）不能当 0——`Number('')` 是 0，
  // 会把无效输入静默变成一笔 0 元交易。
  if (!/\d/.test(normalized)) return null
  const value = Number(normalized)
  return Number.isFinite(value) ? value : null
}

// 组合口径（规格 §10）—— 全部纯函数：吃普通对象、吐普通对象，不碰宿主、不碰存储。
// 这样 §10 的每条公式都能被 node 自测逐条断言，也让「事务」在 store 层是一次原子替换。
//
// 三条最容易做错、这里刻意写死的规则：
//  1. **手续费不进成本价**（买入 avgCost 只算 qty×price），但**卖出时手续费吃进已实现盈亏**；
//  2. **总盈亏要扣掉净外部资金流**（入金/出金），否则追加本金会被误算成投资收益；
//  3. **缺行情或缺汇率一律按 0 计并打标**，绝不用汇率 1 兜底、绝不伪造数值。

import {
  MoneyError, addMinor, clampMinor, grossMinorOf, isFiniteNumber, roundHalfAway, scaleMinor, subMinor,
} from './money.js'

export const CASH_FLOW_KINDS = ['deposit', 'withdrawal', 'dividend', 'interest', 'tax', 'fee', 'adjustment']

export function isExternalFlow(kind) {
  return kind === 'deposit' || kind === 'withdrawal'
}

/** withdrawal / tax / fee 为 −1，其余 +1。 */
export function defaultSign(kind) {
  return (kind === 'withdrawal' || kind === 'tax' || kind === 'fee') ? -1 : 1
}

// —— §10.3 汇率 ——

export const FX_CURRENCIES = ['USD', 'HKD', 'EUR', 'GBP', 'JPY', 'CNY']

/** `fxToCNY[c]` 语义 = 1 单位外币 = ? 人民币；CNY 隐含 1。 */
export function cnyPer(currency, fxToCNY) {
  if (currency === 'CNY' || currency === 'RMB') return 1
  const value = fxToCNY ? fxToCNY[currency] : undefined
  return isFiniteNumber(value) && value > 0 ? value : null
}

/**
 * 账户币视角的汇率表。账户币本身取不到 CNY 报价时返回**空表**——
 * 该账户什么都估不了，这比用 1 兜底诚实。
 */
export function fxMapFor(accountCurrency, fxToCNY) {
  const base = cnyPer(accountCurrency, fxToCNY)
  if (base === null) return {}
  const out = {}
  for (const currency of FX_CURRENCIES) {
    const per = cnyPer(currency, fxToCNY)
    if (per !== null) out[currency] = per / base
  }
  return out
}

/** 标的币 → 账户币。同币种直接 1；查不到返回 null（**不是** 1）。 */
export function fxRate(from, to, fxMap) {
  if (from === to) return 1
  const rate = fxMap ? fxMap[from] : undefined
  return isFiniteNumber(rate) && rate > 0 ? rate : null
}

// —— §10.1 买入 ——

/**
 * 返回 `{ account, position, order }` 的**新对象**（不改入参）。校验不过一律抛 MoneyError，
 * 调用方据此整体回滚——余额与流水必须同生共死。
 */
export function applyBuy({ account, position, symbol, name, market, currency, quantity, price, fxRate: rate, feeMinor = 0, tradedAt, note, source }) {
  if (!account) throw new MoneyError('accountNotFound')
  if (account.isArchived) throw new MoneyError('accountArchived')
  if (!isFiniteNumber(rate) || rate <= 0) throw new MoneyError('invalidRate')
  if (!isFiniteNumber(feeMinor) || feeMinor < 0) throw new MoneyError('invalidFee')

  const grossMinor = grossMinorOf(quantity, price)
  const costAcctMinor = scaleMinor(grossMinor, rate)
  const debit = addMinor(costAcctMinor, Math.trunc(feeMinor))
  if (account.cashMinor < debit) throw new MoneyError('insufficientCash', { need: debit, have: account.cashMinor })

  const oldQty = position ? position.quantity : 0
  const oldAvg = position ? position.avgCost : 0
  const newQty = oldQty + quantity
  // 手续费**不进**成本价：摊薄成本只由 qty×price 决定。
  const avgCost = (oldQty * oldAvg + quantity * price) / newQty

  return {
    account: { ...account, cashMinor: subMinor(account.cashMinor, debit) },
    position: {
      ...(position || { realizedPnlMinor: 0 }),
      instrumentSymbol: symbol,
      accountID: account.id,
      name: name || (position && position.name) || symbol,
      marketRaw: market || (position && position.marketRaw) || null,
      currency,
      quantity: newQty,
      avgCost,
      updatedAt: tradedAt || Date.now(),
    },
    order: {
      accountID: account.id,
      instrumentSymbol: symbol,
      name: name || symbol,
      sideRaw: 'buy',
      quantity,
      price,
      grossMinor,
      feeMinor: Math.trunc(feeMinor),
      currency,
      fxRate: rate,
      tradedAt: tradedAt || Date.now(),
      note: note || '',
      source: source || 'manual',
    },
    debitMinor: debit,
  }
}

// —— §10.2 卖出 ——

export function applySell({ account, position, quantity, price, fxRate: rate, feeMinor = 0, tradedAt, note, source }) {
  if (!account) throw new MoneyError('accountNotFound')
  if (account.isArchived) throw new MoneyError('accountArchived')
  if (!position || position.quantity < quantity - 1e-9) throw new MoneyError('insufficientPosition')
  if (!isFiniteNumber(rate) || rate <= 0) throw new MoneyError('invalidRate')
  if (!isFiniteNumber(feeMinor) || feeMinor < 0) throw new MoneyError('invalidFee')

  const grossMinor = grossMinorOf(quantity, price)
  const proceedsGrossAcct = scaleMinor(grossMinor, rate)
  if (feeMinor > proceedsGrossAcct) throw new MoneyError('invalidFee')
  const proceedsNet = subMinor(proceedsGrossAcct, Math.trunc(feeMinor))
  const costBasisAcct = scaleMinor(roundHalfAway(position.avgCost * quantity * 100), rate)
  // 手续费**吃进**已实现盈亏：realizedDelta 用的是净收入。
  const realizedDelta = proceedsNet - costBasisAcct

  return {
    account: { ...account, cashMinor: addMinor(account.cashMinor, proceedsNet) },
    // 清仓不删行：quantity 归 0，累计已实现盈亏留档，再买入自动复活。
    position: {
      ...position,
      quantity: position.quantity - quantity,
      avgCost: position.avgCost,
      realizedPnlMinor: addMinor(position.realizedPnlMinor || 0, realizedDelta),
      updatedAt: tradedAt || Date.now(),
    },
    order: {
      accountID: account.id,
      instrumentSymbol: position.instrumentSymbol,
      name: position.name,
      sideRaw: 'sell',
      quantity,
      price,
      grossMinor,
      feeMinor: Math.trunc(feeMinor),
      currency: position.currency,
      fxRate: rate,
      tradedAt: tradedAt || Date.now(),
      note: note || '',
      source: source || 'manual',
    },
    proceedsMinor: proceedsNet,
    realizedDeltaMinor: realizedDelta,
  }
}

// —— §10.6 现金流水 ——

export function applyCashFlow({ account, kind, amountMinor, occurredAt, note, source }) {
  if (!account) throw new MoneyError('accountNotFound')
  if (account.isArchived) throw new MoneyError('accountArchived')
  if (!isFiniteNumber(amountMinor) || amountMinor <= 0) throw new MoneyError('invalidAmount')
  const signed = defaultSign(kind) < 0 ? -Math.trunc(amountMinor) : Math.trunc(amountMinor)
  const cashAfter = addMinor(account.cashMinor, signed)
  if (cashAfter < 0) throw new MoneyError('insufficientCash')
  return {
    account: { ...account, cashMinor: cashAfter },
    flow: {
      accountID: account.id,
      kindRaw: kind,
      amountMinor: signed,
      currency: account.currency,
      occurredAt: occurredAt || Date.now(),
      note: note || '',
      source: source || 'manual',
    },
  }
}

// —— §10.4 单持仓估值 ——

export function valuePosition(position, quote, rate) {
  const quoteValid = !!(quote && isFiniteNumber(quote.price) && quote.price > 0)
  const priced = quoteValid && rate !== null && rate !== undefined
  const qty = position.quantity
  const marketValueMinor = priced ? scaleMinor(roundHalfAway(qty * quote.price * 100), rate) : 0
  const costMinor = priced ? scaleMinor(roundHalfAway(qty * position.avgCost * 100), rate) : 0
  const unrealizedMinor = marketValueMinor - costMinor
  const prevClose = quote && isFiniteNumber(quote.prevClose) ? quote.prevClose : 0
  const dayMinor = priced ? scaleMinor(roundHalfAway(qty * (quote.price - prevClose) * 100), rate) : 0
  return {
    position,
    priced,
    marketValueMinor,
    costMinor,
    unrealizedMinor,
    unrealizedPct: costMinor !== 0 ? (unrealizedMinor / Math.abs(costMinor)) * 100 : 0,
    dayMinor,
    missingQuote: !quoteValid,
    missingFX: rate === null || rate === undefined,
  }
}

// —— §10.5 账户估值 ——

/**
 * `quotes` = canonical → quote；`fxToCNY` = 币种 → 人民币中间价；`cashFlows` = 该账户全部流水。
 * `positions` 要传**全部行（含 quantity=0 的历史行）**——已实现盈亏靠它们累加。
 */
export function valueAccount({ account, positions, quotes, fxToCNY, cashFlows }) {
  const fxMap = fxMapFor(account.currency, fxToCNY)
  const open = positions.filter((row) => row.quantity > 0)
  const rows = open.map((position) => {
    const quote = quotes ? quotes[position.instrumentSymbol] : null
    return valuePosition(position, quote, fxRate(position.currency, account.currency, fxMap))
  })

  const marketValueMinor = rows.reduce((sum, row) => sum + row.marketValueMinor, 0)
  const costMinor = rows.reduce((sum, row) => sum + row.costMinor, 0)
  const unrealizedMinor = rows.reduce((sum, row) => sum + row.unrealizedMinor, 0)
  const dayMinor = rows.reduce((sum, row) => sum + row.dayMinor, 0)
  const realizedMinor = positions.reduce((sum, row) => sum + (row.realizedPnlMinor || 0), 0)
  const totalMinor = clampMinor(account.cashMinor + marketValueMinor)
  const externalCashFlowMinor = (cashFlows || [])
    .filter((flow) => isExternalFlow(flow.kindRaw))
    .reduce((sum, flow) => sum + flow.amountMinor, 0)
  // 追加入金不算收益：总盈亏必须扣掉净外部资金流。
  const totalPnlMinor = totalMinor - account.initialCashMinor - externalCashFlowMinor
  const returnRate = account.initialCashMinor !== 0
    ? (totalPnlMinor / Math.abs(account.initialCashMinor)) * 100
    : 0

  const missingQuotes = rows.filter((row) => row.missingQuote).map((row) => row.position.instrumentSymbol)
  const missingFX = [...new Set(rows.filter((row) => row.missingFX).map((row) => row.position.currency))]

  return {
    account,
    rows,
    cashMinor: account.cashMinor,
    marketValueMinor,
    costMinor,
    unrealizedMinor,
    dayMinor,
    realizedMinor,
    totalMinor,
    externalCashFlowMinor,
    totalPnlMinor,
    returnRate,
    missingQuotes,
    missingFX,
    isComplete: missingQuotes.length === 0 && missingFX.length === 0,
  }
}

// —— §10.8 组合绩效 ——

/** 胜率：成交按时间升序回放，逐标的重建摊薄成本；卖出价高于当时 avgCost 记一胜。 */
export function winRateOf(orders) {
  const sorted = [...orders].sort((a, b) => a.tradedAt - b.tradedAt)
  const state = new Map()
  let closed = 0
  let wins = 0
  for (const order of sorted) {
    const key = order.instrumentSymbol
    const current = state.get(key) || { qty: 0, avg: 0 }
    if (order.sideRaw === 'buy') {
      const nextQty = current.qty + order.quantity
      current.avg = nextQty > 0 ? (current.qty * current.avg + order.quantity * order.price) / nextQty : 0
      current.qty = nextQty
    } else {
      closed += 1
      if (order.price > current.avg) wins += 1
      current.qty = Math.max(0, current.qty - order.quantity)
    }
    state.set(key, current)
  }
  return { closed, wins, winRate: closed > 0 ? (wins / closed) * 100 : 0 }
}

const RISK_FREE = 0.02

/** 快照 ≥ 2 才算回撤/波动/夏普，否则全 0 且 `hasEnoughData=false`。 */
export function performance({ orders, snapshots }) {
  const wins = winRateOf(orders || [])
  const sorted = [...(snapshots || [])].sort((a, b) => a.date - b.date)
  const base = {
    ...wins,
    hasEnoughData: false,
    totalReturn: 0,
    annualized: 0,
    maxDrawdown: 0,
    volatility: 0,
    sharpe: 0,
  }
  if (sorted.length < 2) return base

  const values = sorted.map((row) => row.totalValueMinor / 100)
  const first = values[0]
  const last = values[values.length - 1]
  const totalReturn = first !== 0 ? ((last - first) / first) * 100 : 0
  const days = Math.max(1, Math.round((sorted[sorted.length - 1].date - sorted[0].date) / 86400000))
  const annualized = (first > 0 && last > 0) ? ((last / first) ** (365 / days) - 1) : 0

  let peak = -Infinity
  let drawdown = 0
  for (const value of values) {
    if (value > peak) peak = value
    if (peak > 0) drawdown = Math.max(drawdown, ((peak - value) / peak) * 100)
  }

  const returns = []
  for (let i = 1; i < values.length; i += 1) {
    if (values[i - 1] === 0) continue
    returns.push(values[i] / values[i - 1] - 1)
  }
  // 总体标准差（除以 n）——与回测那边的样本口径刻意不同。
  const mean = returns.length ? returns.reduce((sum, value) => sum + value, 0) / returns.length : 0
  const variance = returns.length
    ? returns.reduce((sum, value) => sum + (value - mean) ** 2, 0) / returns.length
    : 0
  const volatility = Math.sqrt(variance) * Math.sqrt(252) * 100
  // 夏普用**年化收益**（不是日均年化），无风险 2%。
  const sharpe = volatility !== 0 ? (annualized - RISK_FREE) / (volatility / 100) : 0

  return {
    ...wins,
    hasEnoughData: true,
    totalReturn,
    annualized: annualized * 100,
    maxDrawdown: drawdown,
    volatility,
    sharpe,
  }
}

// —— §10.9 资产配置 ——

export function allocation(rows) {
  const buckets = new Map()
  for (const row of rows) {
    const key = row.position.marketRaw || 'ashare'
    buckets.set(key, (buckets.get(key) || 0) + row.marketValueMinor)
  }
  const total = [...buckets.values()].reduce((sum, value) => sum + value, 0)
  if (total <= 0) return []
  return [...buckets.entries()]
    .map(([market, marketValueMinor]) => ({ market, marketValueMinor, ratio: marketValueMinor / total }))
    .sort((a, b) => b.marketValueMinor - a.marketValueMinor)
}

// —— §10.10 组合诊断 ——

const FLAG_PENALTY = {
  highConcentration: 20,
  fewPositions: 15,
  singleMarket: 10,
  highCash: 10,
  lowCash: 5,
  bigDrawdown: 15,
  deepLoser: 15,
}

export function diagnose({ valuation, perf }) {
  const rows = valuation.rows
  const holdingsMinor = Math.max(valuation.marketValueMinor, 0)
  const totalMinor = Math.max(valuation.totalMinor, 1)
  const cashPct = (valuation.cashMinor / totalMinor) * 100
  const holdingsPct = (holdingsMinor / totalMinor) * 100

  let hhi = 0
  let topWeight = 0
  if (holdingsMinor > 0) {
    for (const row of rows) {
      const weight = row.marketValueMinor / holdingsMinor
      hhi += weight * weight
      if (weight > topWeight) topWeight = weight
    }
  }

  const alloc = allocation(rows)
  const topMarket = alloc.length > 0 ? alloc[0] : null
  const positive = rows.filter((row) => row.marketValueMinor > 0)
  const contributor = positive
    .filter((row) => row.unrealizedPct > 0)
    .sort((a, b) => b.unrealizedPct - a.unrealizedPct)[0] || null
  const detractor = positive
    .filter((row) => row.unrealizedPct < 0)
    .sort((a, b) => a.unrealizedPct - b.unrealizedPct)[0] || null

  const flags = []
  if (topWeight * 100 > 40) flags.push('highConcentration')
  if (rows.length > 0 && rows.length <= 2) flags.push('fewPositions')
  if (topMarket && topMarket.ratio * 100 > 90 && rows.length >= 2) flags.push('singleMarket')
  if (cashPct > 50) flags.push('highCash')
  if (rows.length > 0 && cashPct < 2) flags.push('lowCash')
  if (perf && perf.hasEnoughData && perf.maxDrawdown > 20) flags.push('bigDrawdown')
  if (detractor && detractor.unrealizedPct < -20) flags.push('deepLoser')

  const penalty = flags.reduce((sum, flag) => sum + (FLAG_PENALTY[flag] || 0), 0)
  return {
    isComplete: valuation.isComplete,
    score: Math.max(0, Math.min(100, 100 - penalty)),
    cashPct,
    holdingsPct,
    hhi,
    topWeight,
    topMarket,
    contributor,
    detractor,
    flags,
  }
}

// 东财 datacenter（财务 / 分红 / 龙虎榜 / 公告 / 业绩预告）—— 规格 §8.4。
// 这一族**全球可达**（与 §8.5 的 push2 不同），所以海外网络下行业页空、基本面仍能出。
//
// 统一信封：`result.data` 是行数组。Header 需要 Referer + 桌面 UA。

import { getJSON, num, str } from '../http.js'
import { secuCode } from '../symbol.js'

const EMWEB = { Referer: 'https://emweb.securities.eastmoney.com/' }
const DATA = { Referer: 'https://data.eastmoney.com/' }

async function rows(url, headers) {
  const result = await getJSON(url, { headers })
  if (!result.ok) return []
  const data = result.body && result.body.result && result.body.result.data
  return Array.isArray(data) ? data : []
}

/** A 股财务主要指标（近 8 期）。港/美用另外两张报表，见下。 */
export async function fetchFinancials(symbol) {
  if (symbol.market === 'ashare') {
    const code = secuCode(symbol)
    if (!code) return []
    const url = 'https://datacenter.eastmoney.com/securities/api/data/v1/get'
      + '?reportName=RPT_F10_FINANCE_MAINFINADATA'
      + '&columns=SECURITY_NAME_ABBR,REPORT_DATE_NAME,EPSJB,BPS,MGJYXJJE,TOTALOPERATEREVE,PARENTNETPROFIT,ROEJQ,XSMLL,TOTALOPERATEREVETZ,PARENTNETPROFITTZ'
      + `&filter=(SECUCODE=%22${code}%22)&pageSize=8&sortColumns=REPORT_DATE&sortTypes=-1`
    return (await rows(url, EMWEB)).map((row) => ({
      periodName: str(row.REPORT_DATE_NAME),
      eps: num(row.EPSJB),
      bps: num(row.BPS),
      cashPerShare: num(row.MGJYXJJE),
      revenue: num(row.TOTALOPERATEREVE),
      netProfit: num(row.PARENTNETPROFIT),
      roe: num(row.ROEJQ),
      grossMargin: num(row.XSMLL),
      revenueYoY: num(row.TOTALOPERATEREVETZ),
      netProfitYoY: num(row.PARENTNETPROFITTZ),
      currency: 'CNY',
    }))
  }
  if (symbol.market === 'hk') {
    const url = 'https://datacenter.eastmoney.com/securities/api/data/v1/get'
      + '?reportName=RPT_HKF10_FN_MAININDICATOR'
      + '&columns=REPORT_TYPE,CURRENCY,BASIC_EPS,BPS,PER_NETCASH_OPERATE,OPERATE_INCOME,OPERATE_INCOME_YOY,HOLDER_PROFIT,HOLDER_PROFIT_YOY,GROSS_PROFIT_RATIO,ROE_AVG'
      + `&filter=(SECURITY_CODE="${symbol.code}")&pageSize=8&sortColumns=STD_REPORT_DATE&sortTypes=-1`
    return (await rows(url, EMWEB)).map((row) => ({
      periodName: str(row.REPORT_TYPE),
      eps: num(row.BASIC_EPS),
      bps: num(row.BPS),
      cashPerShare: num(row.PER_NETCASH_OPERATE),
      revenue: num(row.OPERATE_INCOME),
      netProfit: num(row.HOLDER_PROFIT),
      roe: num(row.ROE_AVG),
      grossMargin: num(row.GROSS_PROFIT_RATIO),
      revenueYoY: num(row.OPERATE_INCOME_YOY),
      netProfitYoY: num(row.HOLDER_PROFIT_YOY),
      currency: str(row.CURRENCY, 'HKD'),
    }))
  }
  if (symbol.market === 'us') {
    // 008 = 单季。银行/保险常无此报表 → 空结果，上层要给「不可用」而不是报错。
    const url = 'https://datacenter.eastmoney.com/securities/api/data/v1/get'
      + '?reportName=RPT_USF10_FN_GMAININDICATOR'
      + '&columns=REPORT_DATE,BASIC_EPS,OPERATE_INCOME,OPERATE_INCOME_YOY,PARENT_HOLDER_NETPROFIT,PARENT_HOLDER_NETPROFIT_YOY,GROSS_PROFIT_RATIO,ROE_AVG'
      + `&filter=(SECURITY_CODE="${symbol.code}")(DATE_TYPE_CODE="008")&pageSize=8&sortColumns=REPORT_DATE&sortTypes=-1`
    return (await rows(url, EMWEB)).map((row) => ({
      periodName: str(row.REPORT_DATE).slice(0, 10),
      eps: num(row.BASIC_EPS),
      bps: 0,
      cashPerShare: 0,
      revenue: num(row.OPERATE_INCOME),
      netProfit: num(row.PARENT_HOLDER_NETPROFIT),
      roe: num(row.ROE_AVG),
      grossMargin: num(row.GROSS_PROFIT_RATIO),
      revenueYoY: num(row.OPERATE_INCOME_YOY),
      netProfitYoY: num(row.PARENT_HOLDER_NETPROFIT_YOY),
      currency: 'USD',
    }))
  }
  return []
}

/** 分红送配（仅 A 股）。日期截前 10 字符；`IMPL_PLAN_PROFILE` 为空丢弃该行。 */
export async function fetchDividends(symbol) {
  if (symbol.market !== 'ashare') return []
  const url = 'https://datacenter-web.eastmoney.com/api/data/v1/get'
    + '?reportName=RPT_SHAREBONUS_DET'
    + '&columns=SECURITY_NAME_ABBR,REPORT_DATE,PLAN_NOTICE_DATE,IMPL_PLAN_PROFILE'
    + `&filter=(SECURITY_CODE=%22${symbol.code}%22)&pageSize=8&sortColumns=REPORT_DATE&sortTypes=-1`
  return (await rows(url, DATA))
    .map((row) => ({
      reportDate: str(row.REPORT_DATE).slice(0, 10),
      noticeDate: str(row.PLAN_NOTICE_DATE).slice(0, 10),
      plan: str(row.IMPL_PLAN_PROFILE),
    }))
    .filter((row) => row.plan)
}

/**
 * 龙虎榜。后处理三步：只保留首行日期（= 最新交易日）→ **按代码去重**（一股多因会重复）→ 取前 40。
 */
export async function fetchDragonBoard(limit = 40) {
  const url = 'https://datacenter-web.eastmoney.com/api/data/v1/get'
    + '?reportName=RPT_DAILYBILLBOARD_DETAILSNEW'
    + '&columns=TRADE_DATE,SECURITY_CODE,SECURITY_NAME_ABBR,CHANGE_RATE,BILLBOARD_NET_AMT,BILLBOARD_BUY_AMT,BILLBOARD_SELL_AMT,EXPLANATION'
    + '&pageSize=200&sortColumns=TRADE_DATE,BILLBOARD_NET_AMT&sortTypes=-1,-1'
  const data = await rows(url, DATA)
  if (data.length === 0) return []
  const latest = str(data[0].TRADE_DATE).slice(0, 10)
  const seen = new Set()
  const out = []
  for (const row of data) {
    if (str(row.TRADE_DATE).slice(0, 10) !== latest) continue
    const code = str(row.SECURITY_CODE)
    if (!code || seen.has(code)) continue
    seen.add(code)
    out.push({
      tradeDate: latest,
      code,
      name: str(row.SECURITY_NAME_ABBR),
