    + `?pn=1&pz=${limit}&po=${ascending ? 0 : 1}&fid=${fid}`
    + `&fs=${encodeURIComponent(fs)}&fields=${fields}`
  const result = await getJSON(url, { headers: QUOTE_REFERER })
  if (!result.ok) return []
  return diffRows(result.body)
}

