// 腾讯（主源，A/港/美通吃）—— 规格 §8.1。零 API Key，靠 `Referer: https://gu.qq.com` 绕反爬。
//
// 响应是 **GBK**，必须 `responseType:'base64'` + `TextDecoder('gb18030')`（见 lib/http.js 文件头）。
// 三个必须照抄的细节：
//  · 字段数 ≤ 34 的行**直接丢弃**（半截响应比没有更危险）；
//  · 下标 37 成交额，**A 股单位是万元（×10000），港/美是元**；
//  · 联想搜索的名称是 JSON 式 `\uXXXX` 转义，不反转义中文全乱。

import { coalesce, getGBK, getJSON, unescapeUnicode } from '../http.js'
import { canonicalOf, currencyOf, padHK, tencentKlineCode, tencentQuoteCode } from '../symbol.js'

const REFERER = { Referer: 'https://gu.qq.com' }

function pick(parts, index) {
  const raw = parts[index]
  if (raw === undefined || raw === '') return null
  const value = Number(raw)
  return Number.isFinite(value) ? value : null
}

/** 五档：价格 > 0 才收。原始量单位是股，UI 侧再 ÷100 成手。 */
function levels(parts, priceStart) {
  const out = []
  for (let i = 0; i < 5; i += 1) {
    const price = pick(parts, priceStart + i * 2)
    const volume = pick(parts, priceStart + i * 2 + 1)
    if (price !== null && price > 0) out.push({ price, volume: volume || 0 })
  }
  return out
}

/** 解析一行 `v_<key>="1~字段~...";` 的主体。 */
export function parseQuoteLine(body, symbol) {
  const parts = body.split('~')
  if (parts.length <= 34) return null
  const market = symbol.market
  const price = pick(parts, 3)
  if (price === null) return null
  const prevClose = pick(parts, 4) || 0
  let change = pick(parts, 31)
  if (change === null) change = price - prevClose
  const amountRaw = pick(parts, 37)
  // A 股成交额单位是**万元**，港/美是元。
  const amount = amountRaw === null ? null : (market === 'ashare' ? amountRaw * 10000 : amountRaw)

  return {
    symbol: canonicalOf(symbol),
    market,
    name: parts[1] || '',
    price,
    prevClose,
    open: pick(parts, 5) || 0,
    high: pick(parts, 33) || 0,
    low: pick(parts, 34) || 0,
    change,
    changePct: pick(parts, 32) || 0,
    volume: pick(parts, 6) || 0,
    amount,
    turnover: (market === 'ashare' || market === 'hk') ? pick(parts, 38) : null,
    pe: pick(parts, 39),
    pb: market === 'ashare' ? pick(parts, 48) : null,
    marketCap: (market === 'ashare' || market === 'hk') ? pick(parts, 46) : null,
    amplitude: (market === 'ashare' || market === 'hk') ? pick(parts, 44) : null,
    bids: market === 'ashare' ? levels(parts, 9) : [],
    asks: market === 'ashare' ? levels(parts, 19) : [],
    time: parts[30] || '',
    currency: currencyOf(symbol),
    isEstimate: false,
    source: 'tencent',
  }
}

/**
 * 批量实时行情。返回 canonical → quote 的字典（拿不到的代码直接缺席，**不填假值**）。
 * 网络/解析失败一律返回空字典，不抛。
 */
export async function fetchQuotes(symbols) {
  const usable = symbols.map((symbol) => ({ symbol, code: tencentQuoteCode(symbol) })).filter((row) => row.code)
  if (usable.length === 0) return {}
  const codes = usable.map((row) => row.code).join(',')
  const url = `https://qt.gtimg.cn/q=${codes}`
  const result = await coalesce(`tencent:q:${[...usable.map((r) => r.code)].sort().join(',')}`,
    () => getGBK(url, { headers: REFERER }))
  if (!result.ok) return {}

  const byCode = new Map(usable.map((row) => [row.code.toLowerCase(), row.symbol]))
  const out = {}
  for (const line of String(result.body).split(';')) {
    const match = /v_([^=]+)="([^"]*)"/.exec(line)
    if (!match) continue
    const symbol = byCode.get(match[1].trim().toLowerCase())
    if (!symbol) continue
    const quote = parseQuoteLine(match[2], symbol)
    if (quote) out[quote.symbol] = quote
  }
  return out
}

const PERIOD_TOKEN = { '5m': 'm5', '15m': 'm15', '30m': 'm30', '60m': 'm60' }

/** 每行 `[date, open, close, high, low, volume]`——**close 在第 3 位、high 在第 4 位**。 */
function parseCandleRows(rows) {
  const out = []
  for (const row of rows || []) {
    if (!Array.isArray(row) || row.length < 6) continue
    const open = Number(row[1])
    const close = Number(row[2])
    const high = Number(row[3])
    const low = Number(row[4])
    // 防脏：OHLC 任一 ≤ 0 就丢弃整根。
    if (!(open > 0) || !(close > 0) || !(high > 0) || !(low > 0)) continue
    out.push({ date: String(row[0]), open, close, high, low, volume: Number(row[5]) || 0 })
  }
  return out
}

/** 日/周/月 K 线（港股换 hkfqkline host 路径）。`n` 钳到 1..800。 */
export async function fetchDailyCandles(symbol, period, adjust, count) {
  const code = tencentKlineCode(symbol)
  if (!code) return []
  const n = Math.max(1, Math.min(800, count || 160))
  const path = symbol.market === 'hk' ? 'hkfqkline' : 'fqkline'
  const url = `https://web.ifzq.gtimg.cn/appstock/app/${path}/get?param=${code},${period},,,${n},${adjust}`
  const result = await coalesce(`tencent:k:${code}:${period}:${adjust}:${n}`, () => getJSON(url, { headers: REFERER }))
  if (!result.ok) return []
  const bucket = result.body && result.body.data ? result.body.data[code] : null
  if (!bucket) return []
  // 缺复权键则退回裸键。
  const rows = bucket[`${adjust}${period}`] || bucket[period] || []
  return parseCandleRows(rows)
}

/** 分钟 K 线。（原生注明该端点未经 CI 验证，故失败时静默回空。） */
export async function fetchMinuteCandles(symbol, period, count) {
  const code = tencentKlineCode(symbol)
  const token = PERIOD_TOKEN[period]
  if (!code || !token) return []
  const n = Math.max(1, Math.min(800, count || 160))
  const url = `https://ifzq.gtimg.cn/appstock/app/kline/mkline?param=${code},${token},,${n}`
  const result = await coalesce(`tencent:m:${code}:${token}:${n}`, () => getJSON(url, { headers: REFERER }))
  if (!result.ok) return []
  const bucket = result.body && result.body.data ? result.body.data[code] : null
  if (!bucket) return []
  return parseCandleRows(bucket[token] || [])
}

/**
 * 搜索联想。响应 GBK，引号内主体按 `^` 分条，条内按 `~` 分段：`[0]=交易所 [1]=代码 [2]=名称`。
 * 只收 sh/sz/bj/hk/us，美股代码转大写。
 */
export async function search(query) {
  const text = String(query || '').trim()
  if (!text) return []
  const url = `https://smartbox.gtimg.cn/s3/?q=${encodeURIComponent(text)}&t=all`
  const result = await getGBK(url, { headers: REFERER })
  if (!result.ok) return []
  const match = /"([\s\S]*)"/.exec(String(result.body))
  if (!match) return []

  const out = []
  for (const entry of match[1].split('^')) {
    const parts = entry.split('~')
    if (parts.length < 3) continue
    const exchange = parts[0].trim().toLowerCase()
    const code = parts[1].trim()
    const name = unescapeUnicode(parts[2].trim())
    if (!code || !name) continue
    if (exchange === 'sh' || exchange === 'sz' || exchange === 'bj') {
      out.push({ market: 'ashare', code, exchange, name, symbol: `${exchange}${code}` })
    } else if (exchange === 'hk') {
      const padded = padHK(code)
      out.push({ market: 'hk', code: padded, exchange: null, name, symbol: `hk${padded}` })
    } else if (exchange === 'us') {
      const ticker = code.toUpperCase()
      out.push({ market: 'us', code: ticker, exchange: null, name, symbol: `us${ticker}` })
    }
  }
  return out
}

// 行情服务：TTL 缓存 + 故障切换 + 数据可信状态机（规格 §2.5 / §2.6 / §8.8 / §8.9）。
//
// 失败语义是这一层的灵魂（§15 第 8 条）：
//   **全部拉取失败时保留旧缓存和旧 lastUpdated**，只加一行「刷新失败」——
//   绝不能把旧内容伪装成刚刷新过。

import * as tencent from './providers/tencent.js'
import * as sina from './providers/sina.js'
import * as fund from './providers/fund.js'
import { canonicalOf, resolveSymbol } from './symbol.js'

/** 内存 TTL = clamp(refreshInterval, 10, 60) 秒；`force` 旁路。 */
export function quoteTTL(refreshInterval) {
  return Math.max(10, Math.min(60, refreshInterval || 30)) * 1000
}

const KLINE_TTL_MS = 120000
const KLINE_MAX_ENTRIES = 40
const FX_TTL_MS = 3600000

export class QuoteService {
  constructor() {
    this.cache = new Map()          // canonical → { quote, at }
    this.klineCache = new Map()     // key → { rows, at }
    this.fx = null
    this.fxAt = 0
    this.refreshing = false
    this.lastUpdated = null
    this.lastFailed = false
    this.lastPartial = false
    this.missingSymbols = []
    this.source = 'automatic'
    this.refreshInterval = 30
    this.listeners = new Set()
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  emit() {
    for (const listener of this.listeners) listener()
  }

  quote(canonical) {
    const entry = this.cache.get(canonical)
    return entry ? entry.quote : null
  }

  /** 全部缓存的快照（写盘用，带 `at` 时间戳）。 */
  snapshot() {
    const out = {}
    for (const [canonical, entry] of this.cache) out[canonical] = entry
    return out
  }

  /** canonical → quote 的扁平字典（估值与上下文构造用）。 */
  quoteMap() {
    const out = {}
    for (const [canonical, entry] of this.cache) out[canonical] = entry.quote
    return out
  }

  /** 从磁盘快照 hydrate（进页秒显，避免价格闪 0）。 */
  hydrate(rows, lastUpdated) {
    if (rows && typeof rows === 'object') {
      for (const canonical of Object.keys(rows)) {
        const entry = rows[canonical]
        if (entry && entry.quote) this.cache.set(canonical, entry)
      }
    }
    if (lastUpdated) this.lastUpdated = lastUpdated
    this.emit()
  }

  isFresh(canonical, now, force) {
    if (force) return false
    const entry = this.cache.get(canonical)
    if (!entry) return false
    return now - entry.at < quoteTTL(this.refreshInterval)
  }

  /**
   * 批量刷新。返回 `{ quotes, missing, failed }`。
   * 并发保护由调用方（页面）做——这里只保证同 key 网络请求合并（见 http.coalesce）。
   */
  async refresh(canonicals, { force = false } = {}) {
    const now = Date.now()
    const unique = [...new Set(canonicals.filter(Boolean))]
    if (unique.length === 0) return { quotes: {}, missing: [], failed: false }

    const stale = unique.filter((canonical) => !this.isFresh(canonical, now, force))
    if (stale.length === 0) {
      const cached = {}
      for (const canonical of unique) cached[canonical] = this.quote(canonical)
      return { quotes: cached, missing: [], failed: false, fromCache: true }
    }

    const symbols = stale.map((canonical) => ({ canonical, symbol: resolveSymbol(canonical) }))
      .filter((row) => row.symbol)
    const funds = symbols.filter((row) => row.symbol.market === 'fund')
    const listed = symbols.filter((row) => row.symbol.market !== 'fund')

    const collected = {}
    const tasks = []

    if (funds.length > 0) {
      tasks.push(fund.fetchEstimates(funds.map((row) => row.symbol.code))
        .then((rows) => Object.assign(collected, rows)).catch(() => {}))
    }
    if (listed.length > 0) {
      tasks.push(this.fetchListed(listed.map((row) => row.symbol))
        .then((rows) => Object.assign(collected, rows)).catch(() => {}))
    }
    await Promise.all(tasks)

    const at = Date.now()
    for (const canonical of Object.keys(collected)) {
      this.cache.set(canonical, { quote: collected[canonical], at })
    }

    const missing = stale.filter((canonical) => !collected[canonical])
    const failed = Object.keys(collected).length === 0
    // 全失败：保留旧 lastUpdated 与旧缓存，只打失败标。
    if (!failed) this.lastUpdated = at
    this.lastFailed = failed
    this.lastPartial = !failed && missing.length > 0
    this.missingSymbols = missing
    this.emit()

    const quotes = {}
    for (const canonical of unique) quotes[canonical] = this.quote(canonical)
    return { quotes, missing, failed }
  }

  /**
   * 故障切换（§8.8）：`automatic` 先打腾讯 → 把**没拿到的代码**再打新浪补齐；
   * `tencent` / `sina` 固定单源。
   */
  async fetchListed(symbols) {
    if (this.source === 'sina') return sina.fetchQuotes(symbols)
    const primary = await tencent.fetchQuotes(symbols)
    if (this.source === 'tencent') return primary
    const missing = symbols.filter((symbol) => !primary[canonicalOf(symbol)])
    if (missing.length === 0) return primary
    const fallback = await sina.fetchQuotes(missing)
    return { ...primary, ...fallback }
  }

  /** K 线：会话内 TTL 120s，key = 代码#周期#复权#根数；**条目超 40 整表清空**（不做 LRU）。 */
  async candles(symbol, period, adjust, count, { force = false } = {}) {
    const key = `${symbol.market}:${symbol.code}#${period}#${adjust}#${count}`
    const entry = this.klineCache.get(key)
    const now = Date.now()
    if (!force && entry && now - entry.at < KLINE_TTL_MS) return entry.rows

    let rows = []
    if (symbol.market === 'fund') {
      rows = await fund.fetchNavHistory(symbol.code, count)
    } else if (period === 'day' || period === 'week' || period === 'month') {
      rows = await tencent.fetchDailyCandles(symbol, period, adjust, count)
    } else {
      rows = await tencent.fetchMinuteCandles(symbol, period, count)
    }
    if (rows.length > 0) {
      if (this.klineCache.size >= KLINE_MAX_ENTRIES) this.klineCache.clear()
      this.klineCache.set(key, { rows, at: now })
    }
    return rows
  }

  /** 汇率：TTL 1 小时。拿不到返回 null——**绝不用 1 兜底**。 */
  async exchangeRates({ force = false } = {}) {
    const now = Date.now()
    if (!force && this.fx && now - this.fxAt < FX_TTL_MS) return this.fx
    const rows = await sina.fetchFX()
    if (rows) { this.fx = rows; this.fxAt = now }
    return this.fx
  }
}

/**
 * 数据可信状态机（§2.6 `FinanceWatchlistDataState.resolve`）。
 * 显示「缓存 · 」的条件 = `cached || failedWithCache`。
 */
export function resolveDataState({ failed, lastUpdated, refreshing, missingCount, ttlMs, now }) {
  // 显式判 null/undefined：`lastUpdated === 0`（epoch）也是「有过数据」，
  // 用真值判断会把它误当成从未刷新过。
  const hasStamp = lastUpdated !== null && lastUpdated !== undefined
  if (failed) return hasStamp ? 'failedWithCache' : 'failedWithoutData'
  if (!hasStamp) return refreshing ? 'loading' : 'unavailable'
  if (missingCount > 0) return 'partial'
  return (now - lastUpdated) > ttlMs ? 'cached' : 'fresh'
}

export function showsCachedBadge(state) {
  return state === 'cached' || state === 'failedWithCache'
}

// 持久化与自选（规格 §9.3 的 FinInstrument / FinWatchGroup / FinWatchItem + 设置）。
//
// **事务口径**：容器给的是 per-applet KV，没有 SQL 事务。这里的做法是
// 「纯函数算出新状态 → **单 key 一次写入**」——KV 的单键写入是原子的，
// 所以「余额变更 + 流水写入」要么全成要么全不成（账目在同一个 key 里）。
// 见 lib/ledger.js。存储不健康时所有写操作被拒并返回错误（§1 全局横幅）。

import { storage } from './host.js'
import { resolveSymbol } from './symbol.js'

export const KEYS = {
  watch: 'finance.watch.v1',
  settings: 'finance.settings.v1',
  quotes: 'finance.quotes.v1',
  recent: 'finance.recentSearches',
  alerts: 'finance.alerts.v1',
  industry: 'finance.industry.v1',
}

export const RECENT_LIMIT = 12
const QUOTE_SNAPSHOT_LIMIT = 200      // 磁盘快照只留最近 200 条行情
const QUOTE_WRITE_THROTTLE_MS = 20000

/** 首启种子 4 组（规格 §9.3）。 */
export const SEED_GROUPS = [
  { id: 'group.ashare', name: 'group.ashare', sortOrder: 0, isDefault: true },
  { id: 'group.hk', name: 'group.hk', sortOrder: 1, isDefault: false },
  { id: 'group.us', name: 'group.us', sortOrder: 2, isDefault: false },
  { id: 'group.fund', name: 'group.fund', sortOrder: 3, isDefault: false },
]

export const DEFAULT_SETTINGS = {
  upIsRed: true,                 // 默认红涨绿跌
  autoRefresh: true,
  refreshInterval: 30,
  quoteSource: 'automatic',      // automatic | tencent | sina
  industryAutoRefresh: false,    // 默认**关**
  notifyAlerts: false,
}

/** 热门段的 8 个策展种子（固定，海外 IP 也稳）。 */
export const HOT_SEEDS = [
  { symbol: 'sh600519', name: '贵州茅台' },
  { symbol: 'sz300750', name: '宁德时代' },
  { symbol: 'sz002594', name: '比亚迪' },
  { symbol: 'hk00700', name: '腾讯控股' },
  { symbol: 'hk09988', name: '阿里巴巴' },
  { symbol: 'usAAPL', name: 'Apple' },
  { symbol: 'usNVDA', name: 'NVIDIA' },
  { symbol: 'usTSLA', name: 'Tesla' },
]

let counter = 0
export function newID(prefix) {
  counter += 1
  return `${prefix}-${Date.now().toString(36)}-${counter.toString(36)}`
}

export class FinanceStore {
  constructor() {
    this.groups = SEED_GROUPS.map((row) => ({ ...row }))
    this.items = []               // { id, instrumentSymbol, groupID, sortOrder, addedAt }
    this.instruments = {}         // canonical → { name, market, currency, kind, updatedAt }
    this.settings = { ...DEFAULT_SETTINGS }
    this.recent = []
    this.alerts = []
    this.version = 0
    this.storageHealthy = true
    this.listeners = new Set()
    this.lastQuoteWriteAt = 0
  }

  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  bump() {
    this.version += 1
    for (const listener of this.listeners) listener()
  }

  async load() {
    const [watch, settings, recent, alerts] = await Promise.all([
      storage.get(KEYS.watch), storage.get(KEYS.settings), storage.get(KEYS.recent), storage.get(KEYS.alerts),
    ])
    if (watch && typeof watch === 'object') {
      if (Array.isArray(watch.groups) && watch.groups.length > 0) this.groups = watch.groups
      if (Array.isArray(watch.items)) this.items = watch.items
      if (watch.instruments && typeof watch.instruments === 'object') this.instruments = watch.instruments
    }
    if (settings && typeof settings === 'object') this.settings = { ...DEFAULT_SETTINGS, ...settings }
    if (Array.isArray(recent)) this.recent = recent.slice(0, RECENT_LIMIT)
    if (Array.isArray(alerts)) this.alerts = alerts
    this.bump()
  }

  async persistWatch() {
    const ok = await storage.set(KEYS.watch, {
      groups: this.groups, items: this.items, instruments: this.instruments,
    })
    this.storageHealthy = ok
    if (!ok) this.bump()
    return ok
  }

  async updateSettings(patch) {
    this.settings = { ...this.settings, ...patch }
    this.bump()
    const ok = await storage.set(KEYS.settings, this.settings)
    this.storageHealthy = ok
    return ok
  }

  // —— 自选 ——

  /** 当前可见（按分组过滤后的）自选，含排序。 */
  itemsInGroup(groupID) {
    const rows = groupID ? this.items.filter((row) => row.groupID === groupID) : this.items.slice()
    return rows.sort((a, b) => a.sortOrder - b.sortOrder)
  }

  isWatched(canonical) {
    return this.items.some((row) => row.instrumentSymbol === canonical)
  }

  instrumentName(canonical) {
    const meta = this.instruments[canonical]
    return meta && meta.name ? meta.name : canonical
  }

  /** 回写标的名字到本地元数据（拉到行情后调用）。 */
  noteInstrument(canonical, { name, market, currency, kind }) {
    const current = this.instruments[canonical] || {}
    if (name && current.name === name && current.market === market) return
    this.instruments[canonical] = {
      ...current,
      name: name || current.name || canonical,
      market: market || current.market || null,
      currency: currency || current.currency || null,
      kind: kind || current.kind || 'stock',
      updatedAt: Date.now(),
    }
    this.persistWatch()
  }

  /**
   * 加自选：优先落到**与标的市场同名的种子分组**（`group.<market>`），找不到落默认组；
   * `sortOrder = 全局 max + 1`；同 symbol **幂等**（已存在直接返回）。
   */
  async addWatch(canonical, { name, groupID } = {}) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    if (this.isWatched(canonical)) return { ok: true, existed: true }
    const symbol = resolveSymbol(canonical)
    const preferred = groupID
      || (symbol && this.groups.find((row) => row.id === `group.${symbol.market}`)?.id)
      || (this.groups.find((row) => row.isDefault) || this.groups[0] || {}).id
      || null
    const maxOrder = this.items.reduce((max, row) => Math.max(max, row.sortOrder), -1)
    this.items = [...this.items, {
      id: newID('w'),
      instrumentSymbol: canonical,
      groupID: preferred,
      sortOrder: maxOrder + 1,
      addedAt: Date.now(),
    }]
    if (name) {
      this.instruments[canonical] = {
        ...(this.instruments[canonical] || {}),
        name,
        market: symbol ? symbol.market : null,
        updatedAt: Date.now(),
      }
    }
    this.bump()
    const ok = await this.persistWatch()
    return ok ? { ok: true } : { ok: false, error: 'storageUnavailable' }
  }

  async removeWatch(canonical) {
    if (!this.storageHealthy) return { ok: false, error: 'storageUnavailable' }
    this.items = this.items.filter((row) => row.instrumentSymbol !== canonical)
    this.bump()
    await this.persistWatch()
    return { ok: true }
  }

  /** 拖拽重排：只在手动排序 + 编辑态下由 UI 调用。 */
  async reorderWatch(canonicals) {
    const order = new Map(canonicals.map((canonical, index) => [canonical, index]))
    this.items = this.items.map((row) => (
      order.has(row.instrumentSymbol) ? { ...row, sortOrder: order.get(row.instrumentSymbol) } : row
    ))
    this.bump()
    await this.persistWatch()
  }

  async moveWatch(canonical, groupID) {
    this.items = this.items.map((row) => (
      row.instrumentSymbol === canonical ? { ...row, groupID } : row
    ))
    this.bump()
    await this.persistWatch()
    return { ok: true }
  }

  // —— 分组 ——

  async createGroup(name) {
    if (!name) return { ok: false, error: 'invalidName' }
    if (this.groups.some((row) => row.name === name)) return { ok: false, error: 'duplicate' }
    const sortOrder = this.groups.reduce((max, row) => Math.max(max, row.sortOrder), -1) + 1
    this.groups = [...this.groups, { id: newID('g'), name, sortOrder, isDefault: false }]
    this.bump()
    await this.persistWatch()
    return { ok: true }
  }

  async renameGroup(id, name) {
    this.groups = this.groups.map((row) => (row.id === id ? { ...row, name } : row))
    this.bump()
    await this.persistWatch()
    return { ok: true }
  }

  /** 删组：组内条目落回默认组（不连坐删自选）。 */
  async deleteGroup(id) {
    const fallback = (this.groups.find((row) => row.isDefault && row.id !== id) || this.groups.find((row) => row.id !== id) || {}).id || null
    this.groups = this.groups.filter((row) => row.id !== id)
    this.items = this.items.map((row) => (row.groupID === id ? { ...row, groupID: fallback } : row))
    this.bump()
    await this.persistWatch()
    return { ok: true }
  }

  // —— 历史搜索 ——
  //
  // **打开详情时才记入**（不是敲键或点加自选时）；上限 12，去重置顶。

  async noteRecent(canonical) {
    this.recent = [canonical, ...this.recent.filter((row) => row !== canonical)].slice(0, RECENT_LIMIT)
    this.bump()
    await storage.set(KEYS.recent, this.recent)
  }

  async clearRecent() {
    this.recent = []
    this.bump()
    await storage.set(KEYS.recent, [])
  }

  // —— 行情磁盘快照（节流 20s，退出时强制写，只留最近 200 条）——

  async persistQuotes(snapshot, lastUpdated, { force = false } = {}) {
    const now = Date.now()
    if (!force && now - this.lastQuoteWriteAt < QUOTE_WRITE_THROTTLE_MS) return false
    this.lastQuoteWriteAt = now
    const entries = Object.entries(snapshot)
      .sort((a, b) => (b[1].at || 0) - (a[1].at || 0))
      .slice(0, QUOTE_SNAPSHOT_LIMIT)
    const rows = {}
    for (const [canonical, entry] of entries) rows[canonical] = entry
    return storage.set(KEYS.quotes, { rows, lastUpdated })
  }

  async loadQuotes() {
    const saved = await storage.get(KEYS.quotes)
    if (!saved || typeof saved !== 'object') return null
    return { rows: saved.rows || {}, lastUpdated: saved.lastUpdated || null }
  }

  // —— 行业页磁盘快照（stale-while-revalidate 的「先显缓存」半程）——

  async persistIndustry(segment, payload) {
    const saved = (await storage.get(KEYS.industry)) || {}
    saved[segment] = { payload, at: Date.now() }
    return storage.set(KEYS.industry, saved)
  }

  async loadIndustry(segment) {
    const saved = await storage.get(KEYS.industry)
    if (!saved || !saved[segment]) return null
    return saved[segment]
  }
}

// 回测 / 定投 / 再平衡（规格 §10.11–§10.13）。纯本地模拟，**只提案不下单**。
//
// 注意两处与绩效不同的口径，别顺手统一：
//  · 波动率用**样本**标准差（除以 n−1），绩效那边是总体（除以 n）；
//  · 年化的 days 用**K 线根数**，不是日历天数。

import { downsample, maxDrawdown, sma, stdDevSample } from './indicators.js'
import { roundHalfAway } from './money.js'

function annualizedFrom(totalPct, days) {
  if (days <= 0) return 0
  const years = days / 252
  if (years <= 0) return 0
  return (((1 + totalPct / 100) ** (1 / years)) - 1) * 100
}

/**
 * 回测。候选 = close > 0 的 K 线，需 ≥ 20 根否则返回 null。
 * maCross 的关键细节：**开仓当根不吃涨跌**（nav 先乘再判信号）。
 */
export function backtest(candles, strategy = 'buyhold') {
  const rows = (candles || []).filter((row) => row.close > 0)
  if (rows.length < 20) return null
  const closes = rows.map((row) => row.close)

  let equity = []
  let trades = 0
  let wins = 0

  if (strategy === 'macross') {
    const ma5 = sma(closes, 5)
    const ma20 = sma(closes, 20)
    let nav = 1
    let holding = false
    let entry = 0
    for (let i = 0; i < rows.length; i += 1) {
      if (holding && i > 0) nav *= closes[i] / closes[i - 1]
      equity.push(nav)
      if (i < 20) continue
      if (ma5[i] === null || ma20[i] === null || ma5[i - 1] === null || ma20[i - 1] === null) continue
      const golden = ma5[i - 1] <= ma20[i - 1] && ma5[i] > ma20[i]
      const dead = ma5[i - 1] >= ma20[i - 1] && ma5[i] < ma20[i]
      if (golden && !holding) {
        holding = true
        entry = closes[i]
        trades += 1
      } else if (dead && holding) {
        holding = false
        if (closes[i] > entry) wins += 1
      }
    }
    if (holding && closes[closes.length - 1] > entry) wins += 1
  } else {
    equity = closes.map((close) => close / closes[0])
  }

  const first = equity[0]
  const last = equity[equity.length - 1]
  const totalReturn = first !== 0 ? ((last - first) / first) * 100 : 0
  const dailyReturns = []
  for (let i = 1; i < equity.length; i += 1) {
    if (equity[i - 1] === 0) continue
    dailyReturns.push(equity[i] / equity[i - 1] - 1)
  }
  const sd = stdDevSample(dailyReturns)
  const mean = dailyReturns.length
    ? dailyReturns.reduce((sum, value) => sum + value, 0) / dailyReturns.length
    : 0
  const volatility = sd * Math.sqrt(252) * 100

  return {
    strategy,
    curve: downsample(equity.map((value, index) => ({ index, value }))),
    totalReturn,
    // days = **K 线根数**，不是日历天数。
    annualized: annualizedFrom(totalReturn, rows.length),
    maxDrawdown: maxDrawdown(equity),
    volatility,
    sharpe: sd !== 0 ? (mean * 252 - 0.02) / (sd * Math.sqrt(252)) : 0,
    buyHoldReturn: ((closes[closes.length - 1] - closes[0]) / closes[0]) * 100,
    trades,
    wins,
    winRate: trades > 0 ? (wins / trades) * 100 : 0,
  }
}

/** 定投：step = 每月 21 / 每周 5（交易日）。需 K 线数 ≥ step 且 amount > 0。 */
export function dcaPlan(candles, { amount = 1000, frequency = 'monthly' } = {}) {
  const rows = (candles || []).filter((row) => row.close > 0)
  const step = frequency === 'weekly' ? 5 : 21
  if (rows.length < step || !(amount > 0)) return null

  let invested = 0
  let shares = 0
  const points = []
  for (let i = 0; i < rows.length; i += step) {
    invested += amount
    shares += amount / rows[i].close
    points.push({ index: i, value: shares * rows[i].close, base: invested })
  }
  const lastClose = rows[rows.length - 1].close
  points.push({ index: rows.length - 1, value: shares * lastClose, base: invested })

  const finalValue = shares * lastClose
  const totalReturn = invested > 0 ? ((finalValue - invested) / invested) * 100 : 0
  return {
    frequency,
    amount,
    periods: Math.ceil(rows.length / step),
    invested,
    shares,
    avgCost: shares > 0 ? invested / shares : 0,
    finalValue,
    totalReturn,
    annualized: annualizedFrom(totalReturn, rows.length),
    lumpSumReturn: ((lastClose - rows[0].close) / rows[0].close) * 100,
    curve: downsample(points),
  }
}

/**
 * 再平衡提案（§10.13）。容差 = max(100 分, 总资产分/1000)，即「1 个货币单位」与「0.1%」取大。
 * 持有但不在目标里 → 建议清仓全部。
 */
export function rebalance({ valuation, targets, quotes, fxMap }) {
  const totalMinor = valuation.totalMinor
  const weightSum = targets.reduce((sum, row) => sum + Math.max(0, row.weight), 0)
  if (weightSum <= 0) return []
  const tolerance = Math.max(100, Math.round(totalMinor / 1000))

  const currentBySymbol = new Map()
  for (const row of valuation.rows) currentBySymbol.set(row.position.instrumentSymbol, row)

  const proposals = []
  for (const target of targets) {
    const normalized = Math.max(0, target.weight) / weightSum
    const targetMinor = Math.round(totalMinor * normalized)
    const row = currentBySymbol.get(target.symbol)
    const currentMinor = row ? row.marketValueMinor : 0
    const delta = targetMinor - currentMinor
    const quote = quotes ? quotes[target.symbol] : null
    const currency = row ? row.position.currency : (target.currency || valuation.account.currency)
    const rate = currency === valuation.account.currency ? 1 : (fxMap ? fxMap[currency] : null)
    const price = quote && quote.price > 0 ? quote.price : null
    const shares = (price && rate) ? (Math.abs(delta) / 100) / (price * rate) : null
    proposals.push({
      symbol: target.symbol,
      name: row ? row.position.name : target.symbol,
      weight: normalized,
      targetMinor,
      currentMinor,
      deltaMinor: delta,
      shares,
      onTarget: Math.abs(delta) < tolerance,
      action: Math.abs(delta) < tolerance ? 'hold' : (delta > 0 ? 'buy' : 'sell'),
    })
    currentBySymbol.delete(target.symbol)
  }

  for (const [symbol, row] of currentBySymbol) {
    if (row.marketValueMinor <= 0) continue
    proposals.push({
      symbol,
      name: row.position.name,
      weight: 0,
      targetMinor: 0,
      currentMinor: row.marketValueMinor,
      deltaMinor: -row.marketValueMinor,
      shares: row.position.quantity,
      onTarget: false,
      action: 'sell',
    })
  }
  return proposals
}

/** 快照日期归一到当天 0 点（本地时区），同日覆盖。 */
export function startOfDay(timestamp) {
  const date = new Date(timestamp)
  date.setHours(0, 0, 0, 0)
  return date.getTime()
}

/** §10.7：**仅当估值完整才写**快照——不完整的估值不进曲线。 */
export function snapshotFor(valuation, when) {
  if (!valuation.isComplete) return null
  return {
    accountID: valuation.account.id,
    date: startOfDay(when || Date.now()),
    totalValueMinor: roundHalfAway(valuation.totalMinor),
    cashMinor: valuation.cashMinor,
    marketValueMinor: valuation.marketValueMinor,
  }
}

// 子页导航 —— 把本应用的路由栈**镜像**成宿主的系统原生页栈。
//
// 用户的原话：「在小应用里面的页面导航栈，你要用系统的，这样我才能够完整地做滑返回到
// 上一个页面，而且能实时看到上一个页面。」这件事宿主已经做完了（真 `UINavigationController`
// + 冻结像素 + 活 WebView 住栈顶，见 docs/capabilities/applet/native-navigation.md），
// 应用侧要做的只有三件：
//
//   ① manifest 声明 `presentation.subpages: true` —— 这是这条能力的 opt-in 开关；
//   ② 进子页时先 `aibox.navigation.push()` **并等顺序屏障**，再渲染新路由；
//   ③ 返回一律经 `popstate` 回来，把自己的栈**对齐到 history 深度**。
//
// 不接 ②③ 的后果不是「返回没有动画」，而是「返回手势是错的」：`history.pushState`
// 从未发生 → 宿主看到的 `webDepth` 恒为 0 → 认为在根路由 → 最左缘左滑**直接退出整个
// 小应用**，用户的子页栈无声消失。这正是真机上被抱怨的那个形状。
//
// 降级（逐点与改造前一致）：宿主不在（浏览器里调试）、形态是 card/sheet/drawer、
// 或没声明 subpages 时，这里退化成纯内存栈 + 纯 Web History，功能不变。

import React from 'react'

function hostNavigation() {
  const api = (typeof window !== 'undefined' && window.aibox) || null
  return (api && api.navigation) || null
}

/**
 * 宿主桥在 `history.state` 上维护的深度标记（`AppletHostBridge` 包装了 pushState/popstate）。
 * 返回 null = 桥不在（或这条 history 记录不是桥写的）→ 调用方回落纯内存栈。
 */
export function historyDepth() {
  try {
    const state = window.history.state
    const marked = state ? Number(state.__aiboxDepth) : NaN
    return Number.isFinite(marked) ? Math.max(0, marked) : null
  } catch (error) {
    return null
  }
}

/**
 * 进一层：先让宿主冻结**当前页**的像素，再由调用方渲染新路由。
 *
 * 顺序屏障是这里唯一的技术要点：`navigation.push()` 是纯 JS，返回的是一个**已解决的**
 * Promise，`await` 它只让出一个微任务，不足以保证宿主已经处理完 `stateChanged`（= 冻结）。
 * 紧接着 `await getState()` 才是真屏障 —— 两条消息走同一个 reply handler、宿主按 FIFO
 * 在主线程处理，`getState` 的回包到达时 `stateChanged` 必然已处理完。
 *
 * 违反屏障是**观感退化而非功能损坏**：冻结下来的会是新页面的像素，于是拖动中露出的
 * 「上一页」看着像当前页；返回本身照常工作。
 */
async function hostPush(path, title) {
  const nav = hostNavigation()
  if (!nav || typeof nav.push !== 'function') return false
  try {
    await nav.push(title ? { route: path, title } : { route: path })
  } catch (error) {
    return false
  }
  if (typeof nav.getState === 'function') {
    try { await nav.getState() } catch (error) { /* 屏障失败只影响观感 */ }
  }
  return true
}

function hostBack() {
  const nav = hostNavigation()
  if (nav && typeof nav.back === 'function') {
    try { nav.back().catch(() => {}) } catch (error) { return false }
    return true
  }
  if (typeof window !== 'undefined' && window.history) { window.history.back(); return true }
  return false
}

function hostPopToRoot() {
  const nav = hostNavigation()
  if (nav && typeof nav.popToRoot === 'function') {
    try { nav.popToRoot().catch(() => {}) } catch (error) { /* 桥拒绝：栈已在本地清空 */ }
    return
  }
  const depth = historyDepth()
  if (typeof window !== 'undefined' && window.history && depth) window.history.go(-depth)
}

/** 宿主是否真的装了原生页栈。页面据此决定要不要自绘转场（本仓四个应用都不自绘）。 */
export async function subpageTransition() {
  const nav = hostNavigation()
  if (!nav || typeof nav.getState !== 'function') return 'web'
  try {
    const state = await nav.getState()
    return (state && state.transition) || 'web'
  } catch (error) {
    return 'web'
  }
}

/**
 * 路由栈 + 宿主页栈的镜像。
 *
 * - `pathFor(route)` → `#/...`，只用于宿主诊断与 `getState().url`，页面自己不读它；
 * - `titleFor(route)` → 顶栏标题；宿主会把它记进标题栈，返回时自动还原。
 */
export function useSubpageStack(options) {
  const configRef = React.useRef(options || {})
  configRef.current = options || {}

  const [stack, setStack] = React.useState([])

  // 所有返回路径（系统手势、宿主顶栏返回键、页面自己的返回键、popToRoot）最后都落到
  // popstate。这里**对齐到深度**而不是「弹一层」——popToRoot 会一次退多层。
  React.useEffect(() => {
    const onPopState = () => {
      const depth = historyDepth()
      setStack((rows) => {
        const target = depth === null ? rows.length - 1 : depth
        const clamped = Math.max(0, Math.min(rows.length, target))
        return clamped === rows.length ? rows : rows.slice(0, clamped)
      })
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])

  const push = React.useCallback((route) => {
    const { pathFor, titleFor } = configRef.current
    const path = pathFor ? pathFor(route) : `#/${(route && route.name) || 'page'}`
    const title = titleFor ? titleFor(route) : null
    // 渲染新路由必须等屏障回来，否则冻结的是新页面的像素（见 hostPush 注释）。
    hostPush(path, title).then(() => setStack((rows) => [...rows, route]))
  }, [])

  const back = React.useCallback(() => {
    // **不乐观更新**：返回要么由宿主的原生 pop 驱动、要么由 WebKit 的 back-forward 手势
    // 驱动，两条路最后都落到 popstate。抢先 setState 会让宿主的转场演给一个空页面看。
    const depth = historyDepth()
    if (depth !== null && depth > 0 && hostBack()) return
    setStack((rows) => rows.slice(0, -1))
  }, [])

  const reset = React.useCallback(() => {
    // 切 Tab 是「整条子页栈作废」，没有转场可言：乐观清空 + 通知宿主对账（幂等）。
    const depth = historyDepth()
    if (depth) hostPopToRoot()
    setStack((rows) => (rows.length === 0 ? rows : []))
  }, [])

  return {
    stack,
    route: stack.length > 0 ? stack[stack.length - 1] : null,
    push,
    back,
    reset,
  }
}

// FinSymbol —— 标的标识（规格 §9.2）。纯函数，无宿主依赖，可在 node 下直接跑自测。
//
// canonical 形态：A股 `sh600519` / 港股 `hk00700` / 美股 `usAAPL` / 基金 `fund161725`。
// 两级解析是刻意的：`parseStrict` 只认明确写法，`parse` 才对全字母兜底成美股 ticker。
// 关键坑：`"Tesla"` 全字母，宽松 parse 会造出永远查不到的假代码 `usTESLA`——
// 所以名字类输入必须先 strict 判空再走搜索。

export const MARKETS = ['ashare', 'hk', 'us', 'fund']

export const MARKET_CURRENCY = {
  ashare: 'CNY',
  hk: 'HKD',
  us: 'USD',
  fund: 'CNY',
}

/** 价格小数位：基金 4 位，其余 2 位。 */
export function decimalsFor(market) {
  return market === 'fund' ? 4 : 2
}

function makeSymbol(market, code, exchange) {
  return { market, code, exchange: exchange || null }
}

/** A 股交易所推断：6/9→sh，0/2/3→sz，4/8→bj，其余 sh。 */
export function exchangeForAShare(code) {
  const head = String(code).charAt(0)
  if (head === '6' || head === '9') return 'sh'
  if (head === '0' || head === '2' || head === '3') return 'sz'
  if (head === '4' || head === '8') return 'bj'
  return 'sh'
}

/** 港股代码补 0 到 5 位。 */
export function padHK(code) {
  const digits = String(code).replace(/\D/g, '')
  return digits.padStart(5, '0').slice(-5)
}

export function canonicalOf(symbol) {
  if (!symbol) return ''
  switch (symbol.market) {
    case 'ashare': return `${symbol.exchange || exchangeForAShare(symbol.code)}${symbol.code}`
    case 'hk': return `hk${symbol.code}`
    case 'us': return `us${symbol.code}`
    case 'fund': return `fund${symbol.code}`
    default: return symbol.code
  }
}

/**
 * 严格解析：只认明确写法。全字母**不认**（返回 null）——这是与 `parse` 的唯一区别。
 */
export function parseStrict(input) {
  const raw = String(input || '').trim()
  if (!raw) return null
  const lower = raw.toLowerCase()

  let match = /^(sh|sz|bj)(\d{6})$/.exec(lower)
  if (match) return makeSymbol('ashare', match[2], match[1])

  match = /^of(\d{6})$/.exec(lower)
  if (match) return makeSymbol('fund', match[1], null)

  match = /^fund(\d+)$/.exec(lower)
  if (match) return makeSymbol('fund', match[1].padStart(6, '0'), null)

  match = /^hk(\d+)$/.exec(lower)
  if (match) return makeSymbol('hk', padHK(match[1]), null)

  match = /^us(.+)$/.exec(raw)
  if (match && /^[A-Za-z0-9.\-]+$/.test(match[1])) return makeSymbol('us', match[1].toUpperCase(), null)

  if (/^\d+$/.test(raw)) {
    if (raw.length === 6) return makeSymbol('ashare', raw, exchangeForAShare(raw))
    if (raw.length === 5) return makeSymbol('hk', raw, null)
    if (raw.length === 4) return makeSymbol('hk', padHK(raw), null)
  }
  return null
}

/**
 * 宽松解析：先 strict，失败时全 ASCII 字母/点 → 当美股 ticker 大写兜底。
 * 只有「用户明确在输代码」的路径才该用它。
 */
export function parseSymbol(input) {
  const strict = parseStrict(input)
  if (strict) return strict
  const raw = String(input || '').trim()
  if (raw && /^[A-Za-z.]+$/.test(raw) && raw.length <= 8) return makeSymbol('us', raw.toUpperCase(), null)
  return null
}

/** canonical 串 → symbol；解析不出来时返回 null。 */
export function symbolFromCanonical(canonical) {
  return parseStrict(canonical)
}

export function currencyOf(symbol) {
  return MARKET_CURRENCY[symbol && symbol.market] || 'CNY'
}

// —— Provider 代码映射（规格 §8）——

/** 腾讯实时行情代码：A股 sh/sz/bj+6位；港股 r_hk+5位；美股 us+大写 ticker。 */
export function tencentQuoteCode(symbol) {
  switch (symbol.market) {
    case 'ashare': return `${symbol.exchange || exchangeForAShare(symbol.code)}${symbol.code}`
    case 'hk': return `r_hk${symbol.code}`
    case 'us': return `us${symbol.code}`
    default: return null
  }
}

/** 腾讯 K 线代码：港股用 `hk`+5 位（**不是** r_hk）。 */
export function tencentKlineCode(symbol) {
  switch (symbol.market) {
    case 'ashare': return `${symbol.exchange || exchangeForAShare(symbol.code)}${symbol.code}`
    case 'hk': return `hk${symbol.code}`
    case 'us': return `us${symbol.code}`
    default: return null
  }
}

/** 新浪实时行情代码：A股 sh/sz/bj+码；港股 rt_hk+码；美股 gb_+小写 ticker。 */
export function sinaQuoteCode(symbol) {
  switch (symbol.market) {
    case 'ashare': return `${symbol.exchange || exchangeForAShare(symbol.code)}${symbol.code}`
    case 'hk': return `rt_hk${symbol.code}`
    case 'us': return `gb_${symbol.code.toLowerCase()}`
    default: return null
  }
}

/** 东财 SECUCODE：`600519.SH`（大写交易所）。 */
export function secuCode(symbol) {
  if (symbol.market !== 'ashare') return null
  return `${symbol.code}.${(symbol.exchange || exchangeForAShare(symbol.code)).toUpperCase()}`
}

/** push2 secid：1.<code>（沪）/ 0.<code>（深、北）。 */
export function secid(symbol) {
  if (symbol.market !== 'ashare') return null
  return `${(symbol.exchange || exchangeForAShare(symbol.code)) === 'sh' ? 1 : 0}.${symbol.code}`
}

/** 从裸 A 股代码按首位数字推 secid（行业页资金榜用）。 */
export function secidFromCode(code, marketFlag) {
  if (marketFlag === 1 || marketFlag === '1') return `1.${code}`
  if (marketFlag === 0 || marketFlag === '0') return `0.${code}`
  return `${exchangeForAShare(code) === 'sh' ? 1 : 0}.${code}`
}

// —— 固定指数表（规格 §2.1，顺序不可配置）——

export const INDEX_ROWS = [
  { canonical: 'sh000001', key: 'idx.sse' },
  { canonical: 'sz399001', key: 'idx.szse' },
  { canonical: 'sz399006', key: 'idx.chinext' },
  { canonical: 'hkHSI', key: 'idx.hsi' },
  { canonical: 'usIXIC', key: 'idx.nasdaq' },
  { canonical: 'usDJI', key: 'idx.dji' },
  { canonical: 'usINX', key: 'idx.sp500' },
]

/**
 * 指数 canonical → symbol。`hkHSI` / `usIXIC` 这类不是普通代码（`hk` 后面是字母），
 * `parseStrict` 认不出来，所以这里单独造，且**不能**走宽松 parse 兜底。
 */
export function indexSymbol(canonical) {
  if (canonical.startsWith('hk')) return makeSymbol('hk', canonical.slice(2), null)
  if (canonical.startsWith('us')) return makeSymbol('us', canonical.slice(2), null)
  return parseStrict(canonical)
}

/** 自选/详情通吃的解析入口：先当指数，再 strict。 */
export function resolveSymbol(canonical) {
  const row = INDEX_ROWS.find((entry) => entry.canonical === canonical)
  if (row) return indexSymbol(canonical)
  return parseStrict(canonical) || (canonical.startsWith('us') ? indexSymbol(canonical) : null)
}

